use std::cell::RefCell;
use std::path::PathBuf;
use std::rc::Rc;

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, Default, PartialOrd, Ord)]
pub struct Span {
    pub lo: u32,
    pub hi: u32,
}

impl Span {
    pub const DUMMY: Span = Span { lo: 0, hi: 0 };
    pub fn new(lo: u32, hi: u32) -> Span {
        if lo <= hi {
            Span { lo, hi }
        } else {
            Span { lo: hi, hi: lo }
        }
    }
    pub fn is_dummy(&self) -> bool {
        self.lo == 0 && self.hi == 0
    }
    pub fn to(self, other: Span) -> Span {
        Span::new(self.lo.min(other.lo), self.hi.max(other.hi))
    }
    pub fn shrink_to_hi(self) -> Span {
        Span { lo: self.hi, hi: self.hi }
    }
    pub fn shrink_to_lo(self) -> Span {
        Span { lo: self.lo, hi: self.lo }
    }
    pub fn with_hi(self, hi: u32) -> Span {
        Span::new(self.lo, hi)
    }
    pub fn with_lo(self, lo: u32) -> Span {
        Span::new(lo, self.hi)
    }
    pub fn until(self, end: Span) -> Span {
        Span::new(self.lo, end.lo.max(self.lo))
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum FileName {
    Real(PathBuf),
    Stdin,
}

pub struct SourceFile {
    pub name: FileName,
    /// Display name, used in diagnostics.
    pub display: String,
    pub src: String,
    pub start_pos: u32,
    /// Byte offsets (relative) of line starts.
    pub lines: Vec<u32>,
}

impl SourceFile {
    pub fn end_pos(&self) -> u32 {
        self.start_pos + self.src.len() as u32
    }
    pub fn len(&self) -> u32 {
        self.src.len() as u32
    }
    /// Returns the line content without its line terminator.
    pub fn line_content(&self, idx: usize) -> &str {
        let start = self.lines[idx] as usize;
        let end = if idx + 1 < self.lines.len() { self.lines[idx + 1] as usize } else { self.src.len() };
        let s = &self.src[start..end];
        let s = s.strip_suffix('\n').unwrap_or(s);
        s.strip_suffix('\r').unwrap_or(s)
    }
    /// Line start (relative) and end including terminator.
    pub fn line_bounds(&self, idx: usize) -> (usize, usize) {
        let start = self.lines[idx] as usize;
        let end = if idx + 1 < self.lines.len() { self.lines[idx + 1] as usize } else { self.src.len() };
        (start, end)
    }
    /// 0-based line index for a relative offset (rustc semantics: offset at line start belongs to that line).
    pub fn lookup_line(&self, off: u32) -> usize {
        match self.lines.binary_search(&off) {
            Ok(i) => i,
            Err(i) => i.saturating_sub(1),
        }
    }
    /// (line index 0-based, char column 0-based)
    pub fn lookup_line_col(&self, off: u32) -> (usize, usize) {
        let line = self.lookup_line(off);
        let start = self.lines[line] as usize;
        let off = (off as usize).min(self.src.len());
        let col = if off >= start { char_count(&self.src.as_bytes()[start..off]) } else { 0 };
        (line, col)
    }
    pub fn num_lines(&self) -> usize {
        self.lines.len()
    }
}

fn char_count(b: &[u8]) -> usize {
    b.iter().filter(|&&c| (c & 0xC0) != 0x80).count()
}

pub fn compute_lines(src: &str) -> Vec<u32> {
    let mut lines = vec![0u32];
    let b = src.as_bytes();
    for (i, &c) in b.iter().enumerate() {
        if c == b'\n' && i + 1 < b.len() {
            lines.push(i as u32 + 1);
        }
    }
    lines
}

#[derive(Default)]
pub struct SourceMap {
    pub files: RefCell<Vec<Rc<SourceFile>>>,
}

impl SourceMap {
    pub fn new() -> Self {
        Self::default()
    }
    pub fn add_file(&self, name: FileName, display: String, src: String) -> Rc<SourceFile> {
        let mut files = self.files.borrow_mut();
        // Leave a gap of 1 between files so that empty spans at EOF are unambiguous.
        let start_pos = match files.last() {
            Some(f) => f.end_pos() + 1,
            None => 1,
        };
        let lines = compute_lines(&src);
        let f = Rc::new(SourceFile { name, display, src, start_pos, lines });
        files.push(f.clone());
        f
    }
    pub fn lookup_file(&self, pos: u32) -> Option<Rc<SourceFile>> {
        let files = self.files.borrow();
        for f in files.iter().rev() {
            if pos >= f.start_pos {
                if pos <= f.end_pos() {
                    return Some(f.clone());
                }
                return None;
            }
        }
        None
    }
    pub fn file_by_name(&self, name: &FileName) -> Option<Rc<SourceFile>> {
        self.files.borrow().iter().find(|f| &f.name == name).cloned()
    }
    pub fn span_to_snippet(&self, sp: Span) -> String {
        if let Some(f) = self.lookup_file(sp.lo) {
            let lo = (sp.lo - f.start_pos) as usize;
            let hi = ((sp.hi - f.start_pos) as usize).min(f.src.len());
            if lo <= hi {
                return f.src[lo..hi].to_string();
            }
        }
        String::new()
    }
    pub fn is_multiline(&self, sp: Span) -> bool {
        if let Some(f) = self.lookup_file(sp.lo) {
            let a = f.lookup_line(sp.lo - f.start_pos);
            let b = f.lookup_line(sp.hi.saturating_sub(f.start_pos));
            a != b
        } else {
            false
        }
    }
}
EOF"}

