// Human-readable diagnostic renderer modeled on rustc's emitter.
use crate::diag::{Diag, DiagConfig, HumanStyle, Level, MultiSpan};
use crate::source_map::{SourceFile, SourceMap, Span};
use crate::width::char_width;
use std::rc::Rc;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Style {
    NoStyle,
    MainHeaderMsg,
    HeaderMsg,
    LineAndColumn,
    LineNumber,
    Quotation,
    UnderlinePrimary,
    UnderlineSecondary,
    LabelPrimary,
    LabelSecondary,
    Level(Level),
}

pub struct StyledBuffer {
    lines: Vec<Vec<(char, Style)>>,
}

impl StyledBuffer {
    fn new() -> Self {
        StyledBuffer { lines: vec![] }
    }
    fn ensure_lines(&mut self, line: usize) {
        while self.lines.len() <= line {
            self.lines.push(vec![]);
        }
    }
    fn putc(&mut self, line: usize, col: usize, c: char, style: Style) {
        self.ensure_lines(line);
        let l = &mut self.lines[line];
        while l.len() <= col {
            l.push((' ', Style::NoStyle));
        }
        l[col] = (c, style);
    }
    fn puts(&mut self, line: usize, col: usize, s: &str, style: Style) {
        let mut n = col;
        for c in s.chars() {
            self.putc(line, n, c, style);
            n += 1;
        }
    }
    fn replace(&mut self, line: usize, start: usize, end: usize, s: &str) {
        if line >= self.lines.len() {
            return;
        }
        let l = &mut self.lines[line];
        if start >= l.len() || end > l.len() || start > end {
            return;
        }
        let style = l[start].1;
        let new: Vec<(char, Style)> = s.chars().map(|c| (c, style)).collect();
        l.splice(start..end, new);
    }
    fn prepend(&mut self, line: usize, s: &str, style: Style) {
        self.ensure_lines(line);
        let n = s.chars().count();
        let l = &mut self.lines[line];
        for _ in 0..n {
            l.insert(0, (' ', Style::NoStyle));
        }
        self.puts(line, 0, s, style);
    }
    fn append(&mut self, line: usize, s: &str, style: Style) {
        if line >= self.lines.len() {
            self.puts(line, 0, s, style);
        } else {
            let col = self.lines[line].len();
            self.puts(line, col, s, style);
        }
    }
    fn num_lines(&self) -> usize {
        self.lines.len()
    }
}

fn level_color(l: Level) -> &'static str {
    match l {
        Level::Bug | Level::Error => "\x1b[1m\x1b[91m",
        Level::Warning => "\x1b[1m\x1b[93m",
        Level::Note => "\x1b[1m\x1b[92m",
        Level::Help => "\x1b[1m\x1b[96m",
        Level::FailureNote => "\x1b[1m",
    }
}

fn style_code(s: Style, level: Level) -> Option<&'static str> {
    match s {
        Style::NoStyle | Style::HeaderMsg | Style::LineAndColumn | Style::Quotation => None,
        Style::MainHeaderMsg => Some("\x1b[1m"),
        Style::LineNumber | Style::UnderlineSecondary | Style::LabelSecondary => Some("\x1b[1m\x1b[94m"),
        Style::UnderlinePrimary | Style::LabelPrimary => Some(level_color(level)),
        Style::Level(l) => Some(level_color(l)),
    }
}

fn render_buffer(buf: &StyledBuffer, color: bool, level: Level, out: &mut String) {
    for line in &buf.lines {
        if !color {
            for (c, _) in line {
                out.push(*c);
            }
        } else {
            let mut i = 0;
            while i < line.len() {
                let st = line[i].1;
                let mut j = i;
                let mut s = String::new();
                while j < line.len() && line[j].1 == st {
                    s.push(line[j].0);
                    j += 1;
                }
                match style_code(st, level) {
                    Some(code) => {
                        out.push_str(code);
                        out.push_str(&s);
                        out.push_str("\x1b[0m");
                    }
                    None => out.push_str(&s),
                }
                i = j;
            }
        }
        out.push('\n');
    }
}

struct Theme {
    unicode: bool,
}

#[derive(Clone, Copy)]
struct UnderlineParts {
    style: Style,
    underline: char,
    label_start: char,
    vertical_text_line: char,
    multiline_vertical: char,
    multiline_horizontal: char,
    multiline_whole_line: char,
