    fn draw_note_separator(&self, buf: &mut StyledBuffer, line: usize, col: usize, is_cont: bool) {
        let s = if self.unicode {
            if is_cont { "├ " } else { "╰ " }
        } else {
            "= "
        };
        buf.puts(line, col, s, Style::LineNumber);
    }
    fn draw_multiline_line(&self, buf: &mut StyledBuffer, line: usize, offset: usize, depth: usize, style: Style) {
        let c = if self.unicode {
            if style == Style::UnderlinePrimary || style == Style::LabelPrimary { '┃' } else { '│' }
        } else {
            '|'
        };
        let st = if style == Style::LabelPrimary { Style::UnderlinePrimary } else if style == Style::LabelSecondary { Style::UnderlineSecondary } else { style };
        buf.putc(line, offset + depth - 1, c, st);
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug, PartialOrd, Ord)]
struct AnnCol {
    display: usize,
    file: usize,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum AnnType {
    Singleline,
    MultilineStart(usize),
    MultilineEnd(usize),
    MultilineLine(usize),
}

#[derive(Clone, Debug)]
struct Annotation {
    start_col: AnnCol,
    end_col: AnnCol,
    is_primary: bool,
    label: Option<String>,
    ann_type: AnnType,
}

impl Annotation {
    fn is_line(&self) -> bool {
        matches!(self.ann_type, AnnType::MultilineLine(_))
    }
    fn len(&self) -> usize {
        if self.end_col.display > self.start_col.display {
            self.end_col.display - self.start_col.display
        } else {
            self.start_col.display - self.end_col.display
        }
    }
    fn has_label(&self) -> bool {
        if let Some(l) = &self.label {
            !l.is_empty()
        } else {
            false
        }
    }
    fn takes_space(&self) -> bool {
        matches!(self.ann_type, AnnType::MultilineStart(_) | AnnType::MultilineEnd(_))
    }
}

#[derive(Clone, Debug)]
struct MultilineAnnotation {
    depth: usize,
    line_start: usize,
    line_end: usize,
    start_col: AnnCol,
    end_col: AnnCol,
    is_primary: bool,
    label: Option<String>,
    overlaps_exactly: bool,
}

impl MultilineAnnotation {
    fn same_span(&self, o: &MultilineAnnotation) -> bool {
        self.line_start == o.line_start && self.line_end == o.line_end && self.start_col == o.start_col && self.end_col == o.end_col
    }
    fn as_start(&self) -> Annotation {
        Annotation {
            start_col: self.start_col,
            end_col: AnnCol { display: self.start_col.display + 1, file: self.start_col.file + 1 },
            is_primary: self.is_primary,
            label: None,
            ann_type: AnnType::MultilineStart(self.depth),
        }
    }
    fn as_end(&self) -> Annotation {
        Annotation {
            start_col: AnnCol { display: self.end_col.display.saturating_sub(1), file: self.end_col.file.saturating_sub(1) },
            end_col: self.end_col,
            is_primary: self.is_primary,
            label: self.label.clone(),
            ann_type: AnnType::MultilineEnd(self.depth),
        }
    }
    fn as_line(&self) -> Annotation {
        Annotation {
            start_col: AnnCol { display: 0, file: 0 },
            end_col: AnnCol { display: 0, file: 0 },
            is_primary: self.is_primary,
            label: None,
            ann_type: AnnType::MultilineLine(self.depth),
        }
    }
}

struct Line {
    line_index: usize, // 1-based
    annotations: Vec<Annotation>,
}

struct FileWithAnnotatedLines {
    file: Rc<SourceFile>,
    lines: Vec<Line>,
    multiline_depth: usize,
}

fn display_col(line: &str, file_col: usize) -> usize {
    line.chars().take(file_col).map(char_width).sum()
}

/// Returns (line_index 0-based, file col) for lo, and similarly for hi with inclusive-end semantics.
fn lookup_lo(f: &SourceFile, off: u32) -> (usize, usize) {
    f.lookup_line_col(off)
}
fn lookup_hi(f: &SourceFile, lo: u32, hi: u32) -> (usize, usize) {
    if hi > lo {
        let line = f.lookup_line(hi - 1);
        let start = f.lines[line] as usize;
        let hi = (hi as usize).min(f.src.len());
        let col = f.src[start..hi].chars().count();
        (line, col)
    } else {
        f.lookup_line_col(hi)
    }
}

fn add_annotation_to_file(file_vec: &mut Vec<FileWithAnnotatedLines>, file: &Rc<SourceFile>, line_index: usize, ann: Annotation) {
    for slot in file_vec.iter_mut() {
        if Rc::ptr_eq(&slot.file, file) {
            for line_slot in slot.lines.iter_mut() {
                if line_slot.line_index == line_index {
                    line_slot.annotations.push(ann);
                    return;
                }
            }
            slot.lines.push(Line { line_index, annotations: vec![ann] });
            slot.lines.sort_by_key(|l| l.line_index);
            return;
        }
    }
    file_vec.push(FileWithAnnotatedLines { file: file.clone(), lines: vec![Line { line_index, annotations: vec![ann] }], multiline_depth: 0 });
}

fn collect_annotations(sm: &SourceMap, msp: &MultiSpan) -> Vec<FileWithAnnotatedLines> {
    let mut output: Vec<FileWithAnnotatedLines> = vec![];
    let mut multiline_annotations: Vec<(Rc<SourceFile>, MultilineAnnotation)> = vec![];

    for sl in msp.span_labels() {
        if sl.span.is_dummy() {
            continue;
        }
        let Some(file) = sm.lookup_file(sl.span.lo) else { continue };
        let lo_rel = sl.span.lo - file.start_pos;
        let hi_rel = sl.span.hi.min(file.end_pos()) - file.start_pos;
        let (lo_line, mut lo_col) = lookup_lo(&file, lo_rel);
        let (hi_line, mut hi_col) = lookup_hi(&file, lo_rel, hi_rel);
        let label = sl.label.clone();
        if lo_line != hi_line {
            let lo_src = file.line_content(lo_line).to_string();
            let hi_src = file.line_content(hi_line).to_string();
            let lo_disp = display_col_ext(&lo_src, lo_col);
            let hi_disp = display_col_ext(&hi_src, hi_col);
            let ml = MultilineAnnotation {
                depth: 1,
                line_start: lo_line + 1,
                line_end: hi_line + 1,
                start_col: AnnCol { display: lo_disp, file: lo_col },
                end_col: AnnCol { display: hi_disp, file: hi_col },
                is_primary: sl.is_primary,
                label,
                overlaps_exactly: false,
            };
            multiline_annotations.push((file.clone(), ml));
        } else {
            let src = file.line_content(lo_line).to_string();
            let content_len = src.chars().count();
            lo_col = lo_col.min(content_len);
            hi_col = hi_col.min(content_len);
            let mut lo_disp = display_col(&src, lo_col);
            let mut hi_disp = display_col(&src, hi_col);
            if lo_disp == hi_disp {
                hi_disp += 1;
                hi_col += 1;
            }
            if hi_disp < lo_disp {
                std::mem::swap(&mut lo_disp, &mut hi_disp);
            }
            let ann = Annotation {
                start_col: AnnCol { display: lo_disp, file: lo_col },
                end_col: AnnCol { display: hi_disp, file: hi_col },
                is_primary: sl.is_primary,
                label,
                ann_type: AnnType::Singleline,
            };
            add_annotation_to_file(&mut output, &file, lo_line + 1, ann);
        }
    }

    // Find overlapping multiline annotations, put them at different depths
    multiline_annotations.sort_by_key(|(_, ml)| (ml.line_start, usize::MAX - ml.line_end));
    let snapshot: Vec<MultilineAnnotation> = multiline_annotations.iter().map(|(_, m)| m.clone()).collect();
    for ann in snapshot.iter() {
        for (_, a) in multiline_annotations.iter_mut() {
            if !ann.same_span(a) && num_overlap(ann.line_start, ann.line_end, a.line_start, a.line_end, true) {
                a.depth += 1;
            } else if ann.same_span(a) && !ml_eq(ann, a) {
                a.overlaps_exactly = true;
            } else {
                break;
            }
        }
    }

    let mut max_depth = 0;
    for (_, a) in &multiline_annotations {
        max_depth = max_depth.max(a.depth);
    }
    for (_, a) in multiline_annotations.iter_mut() {
        a.depth = max_depth - a.depth + 1;
    }
    for (file, ann) in multiline_annotations {
        let mut end_ann = ann.as_end();
        if !ann.overlaps_exactly {
            add_annotation_to_file(&mut output, &file, ann.line_start, ann.as_start());
            let middle = (ann.line_start + 4).min(ann.line_end);
            let filter = |s: &str| {
                let s = s.trim();
                !(s.starts_with("//") && !(s.starts_with("///") || s.starts_with("//!")))
                    && !["", "{", "}", "(", ")", "[", "]"].contains(&s)
            };
            let mut until = ann.line_start;
            let mut line = middle;
            while line > ann.line_start {
                line -= 1;
                if line >= 1 && line - 1 < file.num_lines() {
                    let s = file.line_content(line - 1);
                    if filter(s) {
                        until = line + 1;
                        break;
                    }
                }
            }
            for line in ann.line_start + 1..until {
                add_annotation_to_file(&mut output, &file, line, ann.as_line());
            }
            let line_end = ann.line_end - 1;
            let end_is_empty = line_end >= 1 && line_end - 1 < file.num_lines() && !filter(file.line_content(line_end - 1));
            if middle < line_end && !end_is_empty {
                add_annotation_to_file(&mut output, &file, line_end, ann.as_line());
            }
        } else {
            end_ann.ann_type = AnnType::Singleline;
        }
        add_annotation_to_file(&mut output, &file, ann.line_end, end_ann);
    }
    for f in output.iter_mut() {
        f.multiline_depth = max_depth;
    }
    output
}

fn display_col_ext(line: &str, file_col: usize) -> usize {
    let n = line.chars().count();
    if file_col <= n {
        display_col(line, file_col)
    } else {
        display_col(line, n) + (file_col - n)
    }
}

fn ml_eq(a: &MultilineAnnotation, b: &MultilineAnnotation) -> bool {
    a.depth == b.depth
        && a.line_start == b.line_start
        && a.line_end == b.line_end
        && a.start_col == b.start_col
        && a.end_col == b.end_col
        && a.is_primary == b.is_primary
        && a.label == b.label
        && a.overlaps_exactly == b.overlaps_exactly
}

fn num_overlap(a_start: usize, a_end: usize, b_start: usize, b_end: usize, inclusive: bool) -> bool {
    let extra = if inclusive { 1 } else { 0 };
    (b_start..b_end + extra).contains(&a_start) || (a_start..a_end + extra).contains(&b_start)
}

fn overlaps(a1: &Annotation, a2: &Annotation, padding: usize) -> bool {
    num_overlap(a1.start_col.display, a1.end_col.display + padding, a2.start_col.display, a2.end_col.display, false)
}

pub fn normalize_whitespace(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '\t' => out.push_str("    "),
            '\u{200D}' => {}
            '\u{202A}' | '\u{202B}' | '\u{202D}' | '\u{202E}' | '\u{2066}' | '\u{2067}' | '\u{2068}' | '\u{202C}' | '\u{2069}' => out.push('�'),
            '\u{0}'..='\u{1F}' => out.push(char::from_u32(0x2400 + c as u32).unwrap()),
            '\u{7F}' => out.push('␡'),
            _ => out.push(c),
        }
    }
    out
}

#[derive(Clone, Copy, Debug)]
struct Margin {
    whitespace_left: usize,
    span_left: usize,
    span_right: usize,
    computed_left: usize,
    computed_right: usize,
    column_width: usize,
    label_right: usize,
}

impl Margin {
    fn new(whitespace_left: usize, span_left: usize, span_right: usize, label_right: usize, column_width: usize, max_line_len: usize) -> Self {
        let mut m = Margin {
            whitespace_left: whitespace_left.saturating_sub(6),
            span_left: span_left.saturating_sub(6),
            span_right: span_right + 6,
            computed_left: 0,
            computed_right: 0,
            column_width,
            label_right: label_right + 6,
        };
        m.compute(max_line_len);
        m
    }
    fn was_cut_left(&self) -> bool {
        self.computed_left > 0
    }
    fn compute(&mut self, max_line_len: usize) {
        self.computed_left = if self.whitespace_left > 20 { self.whitespace_left - 16 } else { 0 };
        self.computed_right = max_line_len.max(self.computed_left);
        if self.computed_right - self.computed_left > self.column_width {
            if self.label_right.saturating_sub(self.whitespace_left) <= self.column_width {
                self.computed_left = self.whitespace_left;
                self.computed_right = self.computed_left + self.column_width;
            } else if self.label_right.saturating_sub(self.span_left) <= self.column_width {
                let padding_left = (self.column_width - (self.label_right - self.span_left)) / 2;
                self.computed_left = self.span_left.saturating_sub(padding_left);
                self.computed_right = self.computed_left + self.column_width;
            } else if self.span_right.saturating_sub(self.span_left) <= self.column_width {
                let padding_left = (self.column_width - (self.span_right - self.span_left)) / 5 * 2;
                self.computed_left = self.span_left.saturating_sub(padding_left);
                self.computed_right = self.computed_left + self.column_width;
            } else {
                self.computed_left = self.span_left;
                self.computed_right = self.span_right;
            }
        }
    }
    fn left(&self, line_len: usize) -> usize {
        self.computed_left.min(line_len)
    }
    fn right(&self, line_len: usize) -> usize {
        if line_len.saturating_sub(self.computed_left) <= self.column_width {
            line_len
        } else {
            line_len.min(self.computed_right)
        }
    }
}

const DEFAULT_COLUMN_WIDTH: usize = 140;

struct Renderer<'a> {
    sm: &'a SourceMap,
    theme: Theme,
    short: bool,
    ui_testing: bool,
    diagnostic_width: Option<usize>,
}

impl<'a> Renderer<'a> {
    fn maybe_anonymized(&self, line_num: usize) -> String {
        if self.ui_testing {
            "LL".to_string()
        } else {
            line_num.to_string()
        }
    }

    #[allow(clippy::too_many_arguments)]
    fn draw_line(
        &self,
        buffer: &mut StyledBuffer,
        source_string: &str,
        line_index: usize,
        line_offset: usize,
        width_offset: usize,
        code_offset: usize,
        margin: Margin,
    ) -> usize {
        let line_len = source_string.chars().count();
        let left = margin.left(line_len);
        let right = margin.right(line_len);
        let code: String = source_string.chars().enumerate().skip_while(|(i, _)| *i < left).take_while(|(i, _)| *i < right).map(|(_, c)| c).collect();
        let code = normalize_whitespace(&code);
        let was_cut_right = source_string.chars().enumerate().skip_while(|(i, _)| *i < right).next().is_some();
        buffer.puts(line_offset, code_offset, &code, Style::Quotation);
        let placeholder = self.theme.margin();
        if margin.was_cut_left() {
            buffer.puts(line_offset, code_offset, placeholder, Style::LineNumber);
        }
        if was_cut_right {
            let padding = placeholder.chars().count();
            buffer.puts(line_offset, code_offset + right - left - padding, placeholder, Style::LineNumber);
        }
        buffer.puts(line_offset, 0, &self.maybe_anonymized(line_index), Style::LineNumber);
        self.theme.draw_col_separator_no_space(buffer, line_offset, width_offset - 2);
        left
    }

    #[allow(clippy::too_many_arguments)]
    fn render_source_line(
        &self,
        buffer: &mut StyledBuffer,
        file: &Rc<SourceFile>,
        line: &Line,
        width_offset: usize,
        code_offset: usize,
        margin: Margin,
        close_window: bool,
    ) -> Vec<(usize, Style)> {
        if line.line_index == 0 || line.line_index > file.num_lines() {
            return vec![];
        }
        let source_string = normalize_whitespace(file.line_content(line.line_index - 1));
        let line_offset = buffer.num_lines();

        let left = margin.left(source_string.chars().count());
        let mut taken = 0;
        for ch in source_string.chars() {
            let next = char_width(ch);
            if taken + next <= left {
                taken += next;
            }
        }
        let left = taken;
        self.draw_line(buffer, &source_string, line.line_index, line_offset, width_offset, code_offset, margin);

        let mut buffer_ops = vec![];
        let mut annotations_ret = vec![];
        let mut short_start = true;
        for ann in &line.annotations {
            if let AnnType::MultilineStart(depth) = ann.ann_type {
                if source_string.chars().take(ann.start_col.file).all(|c| c.is_whitespace()) {
                    let uline = self.theme.underline(ann.is_primary);
                    let chr = uline.multiline_whole_line;
                    annotations_ret.push((depth, uline.style));
                    buffer_ops.push((line_offset, width_offset + depth - 1, chr, uline.style));
                } else {
                    short_start = false;
                    break;
                }
            } else if let AnnType::MultilineLine(_) = ann.ann_type {
            } else {
                short_start = false;
                break;
            }
        }
        if short_start {
            for (y, x, c, s) in buffer_ops {
                buffer.putc(y, x, c, s);
            }
            return annotations_ret;
        }

        let mut annotations = line.annotations.clone();
        // stable sort by reverse start col
        annotations.sort_by(|a, b| b.start_col.cmp(&a.start_col));

        let mut overlap = vec![false; annotations.len()];
        let mut annotations_position: Vec<(usize, Annotation)> = vec![];
        let mut line_len: usize = 0;
        let mut p = 0;
        for (i, annotation) in annotations.iter().enumerate() {
            for (j, next) in annotations.iter().enumerate() {
                if overlaps(next, annotation, 0) && j > i {
                    overlap[i] = true;
                    overlap[j] = true;
                }
                if overlaps(next, annotation, 0) && annotation.has_label() && j > i && p == 0 {
                    if next.start_col == annotation.start_col && next.end_col == annotation.end_col && !next.has_label() {
                        continue;
                    }
                    p += 1;
                    break;
                }
            }
            annotations_position.push((p, annotation.clone()));
            for (j, next) in annotations.iter().enumerate() {
                if j > i {
                    let l = next.label.as_ref().map_or(0, |label| label.chars().count() + 2);
                    if (overlaps(next, annotation, l) && annotation.has_label() && next.has_label())
                        || (annotation.takes_space() && next.has_label())
                        || (annotation.has_label() && next.takes_space())
                        || (annotation.takes_space() && next.takes_space())
                        || (overlaps(next, annotation, l) && next.end_col <= annotation.end_col && next.has_label() && p == 0)
                    {
                        p += 1;
                        break;
                    }
                }
            }
            line_len = line_len.max(p);
        }

        if line_len != 0 {
            line_len += 1;
        }

        if line.annotations.iter().all(|a| a.is_line()) {
            return vec![];
        }

        if annotations_position.iter().all(|(_, ann)| matches!(ann.ann_type, AnnType::MultilineStart(_))) {
            if let Some(max_pos) = annotations_position.iter().map(|(pos, _)| *pos).max() {
                for (pos, _) in annotations_position.iter_mut() {
                    *pos = max_pos - *pos;
                }
                line_len = line_len.saturating_sub(1);
            }
        }

        for pos in 0..=line_len {
            self.theme.draw_col_separator_no_space(buffer, line_offset + pos + 1, width_offset - 2);
        }
        if close_window {
            self.theme.draw_col_separator_end(buffer, line_offset + line_len + 1, width_offset - 2);
        }

        for (pos, annotation) in &annotations_position {
            let underline = self.theme.underline(annotation.is_primary);
            let pos = pos + 1;
            match annotation.ann_type {
                AnnType::MultilineStart(depth) | AnnType::MultilineEnd(depth) => {
                    self.draw_range(
                        buffer,
                        underline.multiline_horizontal,
                        line_offset + pos,
                        width_offset + depth,
                        (code_offset + annotation.start_col.display).saturating_sub(left),
                        underline.style,
                    );
                }
                _ => {}
            }
        }

        // Vertical lines for labels on a different line than the underline.
        for (pos, annotation) in &annotations_position {
            let underline = self.theme.underline(annotation.is_primary);
            let pos = pos + 1;
            if pos > 1 && (annotation.has_label() || annotation.takes_space()) {
                for p in line_offset + 1..=line_offset + pos {
                    buffer.putc(
                        p,
                        (code_offset + annotation.start_col.display).saturating_sub(left),
                        match annotation.ann_type {
                            AnnType::MultilineLine(_) => underline.multiline_vertical,
                            _ => underline.vertical_text_line,
                        },
                        underline.style,
                    );
                }
                if let AnnType::MultilineStart(_) = annotation.ann_type {
                    buffer.putc(line_offset + pos, (code_offset + annotation.start_col.display).saturating_sub(left), underline.bottom_right, underline.style);
                }
                if let AnnType::MultilineEnd(_) = annotation.ann_type {
                    if annotation.has_label() {
                        buffer.putc(
                            line_offset + pos,
                            (code_offset + annotation.start_col.display).saturating_sub(left),
                            underline.multiline_bottom_right_with_text,
                            underline.style,
                        );
                    }
                }
            }
            match annotation.ann_type {
                AnnType::MultilineStart(depth) => {
                    buffer.putc(line_offset + pos, width_offset + depth - 1, underline.top_left, underline.style);
                }
                AnnType::MultilineEnd(depth) => {
                    for p in line_offset..line_offset + pos {
                        buffer.putc(p, width_offset + depth - 1, underline.multiline_vertical, underline.style);
                    }
                    buffer.putc(line_offset + pos, width_offset + depth - 1, underline.bottom_left, underline.style);
                }
                _ => {}
            }
        }

        // Labels
        for (pos, annotation) in &annotations_position {
            let style = if annotation.is_primary { Style::LabelPrimary } else { Style::LabelSecondary };
            let (pos, col) = if *pos == 0 {
                if annotation.end_col.display == 0 {
                    (pos + 1, (annotation.end_col.display + 2).saturating_sub(left))
                } else {
                    (pos + 1, (annotation.end_col.display + 1).saturating_sub(left))
                }
            } else {
                (pos + 2, annotation.start_col.display.saturating_sub(left))
            };
            if let Some(label) = &annotation.label {
                buffer.puts(line_offset + pos, code_offset + col, label, style);
            }
        }

        // Underlines
        for (pos, annotation) in &annotations_position {
            let uline = self.theme.underline(annotation.is_primary);
            for p in annotation.start_col.display..annotation.end_col.display {
                buffer.putc(line_offset + 1, (code_offset + p).saturating_sub(left), uline.underline, uline.style);
            }
            if *pos == 0 && matches!(annotation.ann_type, AnnType::MultilineStart(_) | AnnType::MultilineEnd(_)) {
                buffer.putc(
                    line_offset + 1,
                    (code_offset + annotation.start_col.display).saturating_sub(left),
                    match annotation.ann_type {
                        AnnType::MultilineStart(_) => uline.top_right_flat,
                        _ => uline.multiline_end_same_line,
                    },
                    uline.style,
                );
            } else if *pos != 0 && matches!(annotation.ann_type, AnnType::MultilineStart(_) | AnnType::MultilineEnd(_)) {
                buffer.putc(
                    line_offset + 1,
                    (code_offset + annotation.start_col.display).saturating_sub(left),
                    match annotation.ann_type {
                        AnnType::MultilineStart(_) => uline.multiline_start_down,
                        _ => uline.multiline_end_up,
                    },
                    uline.style,
                );
            } else if *pos != 0 && annotation.has_label() {
                buffer.putc(line_offset + 1, (code_offset + annotation.start_col.display).saturating_sub(left), uline.label_start, uline.style);
            }
        }

        for (i, (_pos, annotation)) in annotations_position.iter().enumerate() {
            if overlap[i] {
                continue;
            }
            if annotation.ann_type != AnnType::Singleline {
                continue;
            }
            let width = annotation.end_col.display - annotation.start_col.display;
            if width > margin.column_width * 2 && width > 10 {
                let pad = (margin.column_width / 3).max(5);
                buffer.replace(line_offset, annotation.start_col.file + pad, annotation.end_col.file - pad, self.theme.margin());
                buffer.replace(line_offset + 1, annotation.start_col.file + pad, annotation.end_col.file - pad, self.theme.margin());
            }
        }

        annotations_position
            .iter()
            .filter_map(|(_, annotation)| match annotation.ann_type {
                AnnType::MultilineStart(p) | AnnType::MultilineEnd(p) => {
                    let style = if annotation.is_primary { Style::LabelPrimary } else { Style::LabelSecondary };
                    Some((p, style))
                }
                _ => None,
            })
            .collect()
    }

    fn draw_range(&self, buffer: &mut StyledBuffer, symbol: char, line: usize, col_from: usize, col_to: usize, style: Style) {
        for col in col_from..col_to {
            buffer.putc(line, col, symbol, style);
        }
    }

    fn msgs_to_buffer(&self, buffer: &mut StyledBuffer, msg: &str, padding: usize, label: &str, style: Style) -> usize {
        // Lines after the first are padded to align with the message.
        let padding = " ".repeat(padding + label.chars().count() + 5);
        let mut line_number = 0;
        let lines: Vec<&str> = msg.split('\n').collect();
        for (i, l) in lines.iter().enumerate() {
            if i > 0 {
                line_number += 1;
                buffer.append(line_number, &padding, Style::NoStyle);
            }
            buffer.append(line_number, l, style);
        }
        line_number
    }

    #[allow(clippy::too_many_arguments)]
    fn emit_message_default(
        &self,
        msp: &MultiSpan,
        msg: &str,
        code: &Option<String>,
        level: Level,
        max_line_num_len: usize,
        is_secondary: bool,
        is_cont: bool,
    ) -> (StyledBuffer, bool) {
        let mut buffer = StyledBuffer::new();
        if msp.is_empty() && is_secondary && !self.short {
            // A secondary message with no span info
            for _ in 0..max_line_num_len {
                buffer.prepend(0, " ", Style::NoStyle);
            }
            self.theme.draw_note_separator(&mut buffer, 0, max_line_num_len + 1, is_cont);
            buffer.append(0, level.as_str(), Style::MainHeaderMsg);
            buffer.append(0, ": ", Style::NoStyle);
            let printed_lines = self.msgs_to_buffer(&mut buffer, msg, max_line_num_len, "note", Style::NoStyle);
            if is_cont && self.theme.unicode {
                for i in 1..=printed_lines {
                    self.theme.draw_col_separator_no_space(&mut buffer, i, max_line_num_len + 1);
                }
            }
            return (buffer, false);
        }
        if is_secondary {
            buffer.append(0, level.as_str(), Style::Level(level));
            buffer.append(0, ": ", Style::HeaderMsg);
            self.msgs_to_buffer(&mut buffer, msg, max_line_num_len, level.as_str(), Style::NoStyle);
        } else {
            if self.short {
                // header is prepended with location below
            }
            buffer.append(0, level.as_str(), Style::Level(level));
            if let Some(c) = code {
                buffer.append(0, "[", Style::Level(level));
                buffer.append(0, c, Style::Level(level));
                buffer.append(0, "]", Style::Level(level));
            }
            let header_style = Style::MainHeaderMsg;
            buffer.append(0, ": ", header_style);
            self.msgs_to_buffer(&mut buffer, msg, max_line_num_len, level.as_str(), header_style);
        }

        let mut annotated_files = collect_annotations(self.sm, msp);

        let primary_span = msp.primary_span().unwrap_or(Span::DUMMY);
        let primary_file = if primary_span.is_dummy() { None } else { self.sm.lookup_file(primary_span.lo) };

        if let Some(pf) = &primary_file {
            if let Some(pos) = annotated_files.iter().position(|x| Rc::ptr_eq(&x.file, pf)) {
                let f = annotated_files.remove(pos);
                annotated_files.insert(0, f);
            }
        }

        if self.short {
            if let Some(pf) = &primary_file {
                let (line, col) = pf.lookup_line_col(primary_span.lo - pf.start_pos);
                buffer.prepend(0, &format!("{}:{}:{}: ", pf.display, line + 1, col + 1), Style::LineAndColumn);
                let labels: Vec<String> = msp.span_labels().into_iter().filter(|l| l.is_primary).filter_map(|l| l.label).collect();
                if !labels.is_empty() {
                    buffer.append(0, ": ", Style::NoStyle);
                    buffer.append(0, &labels.join(", "), Style::NoStyle);
                }
            }
            return (buffer, false);
        }

        let mut closed = false;
        let n_files = annotated_files.len();
        for (fi, annotated_file) in annotated_files.iter().enumerate() {
            let is_primary = primary_file.as_ref().map_or(false, |pf| Rc::ptr_eq(pf, &annotated_file.file));
            if is_primary {
                let (line, col) = annotated_file.file.lookup_line_col(primary_span.lo - annotated_file.file.start_pos);
                let off = buffer.num_lines();
                buffer.prepend(off, self.theme.file_start(), Style::LineNumber);
                buffer.append(off, &format!("{}:{}:{}", annotated_file.file.display, line + 1, col + 1), Style::LineAndColumn);
                for _ in 0..max_line_num_len {
                    buffer.prepend(off, " ", Style::NoStyle);
                }
            } else {
                let off = buffer.num_lines();
                self.theme.draw_col_separator_no_space(&mut buffer, off, max_line_num_len + 1);
                buffer.prepend(off + 1, self.theme.secondary_file_start(), Style::LineNumber);
                let loc = if let Some(first_line) = annotated_file.lines.first() {
                    let item_col = first_line.annotations.iter().find(|a| !a.is_line()).map_or(0, |a| a.start_col.file);
                    format!("{}:{}:{}", annotated_file.file.display, first_line.line_index, item_col + 1)
                } else {
                    annotated_file.file.display.clone()
                };
                buffer.append(off + 1, &loc, Style::LineAndColumn);
                for _ in 0..max_line_num_len {
                    buffer.prepend(off + 1, " ", Style::NoStyle);
                }
            }

            let off = buffer.num_lines();
            self.theme.draw_col_separator_no_space(&mut buffer, off, max_line_num_len + 1);

            let mut multilines: Vec<(usize, Style)> = vec![];

            let file = &annotated_file.file;
            let mut whitespace_margin = usize::MAX;
            for line in &annotated_file.lines {
                if line.line_index >= 1 && line.line_index <= file.num_lines() {
                    let source_string = file.line_content(line.line_index - 1);
                    let leading_whitespace = source_string.chars().take_while(|c| is_whitespace(*c)).count();
                    if source_string.chars().any(|c| !is_whitespace(c)) {
                        whitespace_margin = whitespace_margin.min(leading_whitespace);
                    }
                }
            }
            if whitespace_margin == usize::MAX {
                whitespace_margin = 0;
            }

            let mut span_left_margin = usize::MAX;
            for line in &annotated_file.lines {
                for ann in &line.annotations {
                    span_left_margin = span_left_margin.min(ann.start_col.display);
                    span_left_margin = span_left_margin.min(ann.end_col.display);
                }
            }
            if span_left_margin == usize::MAX {
                span_left_margin = 0;
            }

            let mut span_right_margin = 0;
            let mut label_right_margin = 0;
            let mut max_line_len = 0;
            for line in &annotated_file.lines {
                if line.line_index >= 1 && line.line_index <= file.num_lines() {
                    max_line_len = max_line_len.max(file.line_content(line.line_index - 1).len());
                }
                for ann in &line.annotations {
                    span_right_margin = span_right_margin.max(ann.start_col.display);
                    span_right_margin = span_right_margin.max(ann.end_col.display);
                    let label_right = ann.label.as_ref().map_or(0, |l| l.chars().count() + 1);
                    label_right_margin = label_right_margin.max(ann.end_col.display + label_right);
                }
            }

            let width_offset = 3 + max_line_num_len;
            let code_offset = if annotated_file.multiline_depth == 0 { width_offset } else { width_offset + annotated_file.multiline_depth + 1 };

            let column_width = if let Some(w) = self.diagnostic_width {
                w.saturating_sub(code_offset)
            } else {
                DEFAULT_COLUMN_WIDTH
            };

            let margin = Margin::new(whitespace_margin, span_left_margin, span_right_margin, label_right_margin, column_width, max_line_len);

            let n_lines = annotated_file.lines.len();
            for line_idx in 0..n_lines {
                let previous_buffer_line = buffer.num_lines();
                let close_window = !is_cont && fi + 1 == n_files && line_idx + 1 == n_lines;
                if close_window {
                    closed = true;
                }
                let depths = self.render_source_line(&mut buffer, file, &annotated_file.lines[line_idx], width_offset, code_offset, margin, close_window);

                let mut to_add: Vec<(usize, Style)> = vec![];
                for (depth, style) in depths {
                    if let Some(pos) = multilines.iter().position(|(d, _)| *d == depth) {
                        multilines.swap_remove(pos);
                    } else {
                        to_add.push((depth, style));
                    }
                }

                for (depth, style) in &multilines {
                    for line in previous_buffer_line..buffer.num_lines() {
                        self.theme.draw_multiline_line(&mut buffer, line, width_offset, *depth, *style);
                    }
                }

                if line_idx < n_lines - 1 {
                    let line_idx_delta = annotated_file.lines[line_idx + 1].line_index - annotated_file.lines[line_idx].line_index;
                    if line_idx_delta > 2 {
                        let last_buffer_line_num = buffer.num_lines();
                        self.theme.draw_line_separator(&mut buffer, last_buffer_line_num, width_offset);
                        for (depth, style) in &multilines {
                            self.theme.draw_multiline_line(&mut buffer, last_buffer_line_num, width_offset, *depth, *style);
                        }
                        for ann in &annotated_file.lines[line_idx].annotations {
                            if let AnnType::MultilineStart(pos) = ann.ann_type {
                                self.theme.draw_multiline_line(
                                    &mut buffer,
                                    last_buffer_line_num,
                                    width_offset,
                                    pos,
                                    if ann.is_primary { Style::UnderlinePrimary } else { Style::UnderlineSecondary },
                                );
                            }
                        }
                    } else if line_idx_delta == 2 {
                        let li = annotated_file.lines[line_idx].line_index; // 1-based of current; next unannotated is li+1 => index li
                        let unannotated_line = if li < file.num_lines() { file.line_content(li).to_string() } else { String::new() };
                        let last_buffer_line_num = buffer.num_lines();
                        self.draw_line(
                            &mut buffer,
                            &normalize_whitespace(&unannotated_line),
                            annotated_file.lines[line_idx + 1].line_index - 1,
                            last_buffer_line_num,
                            width_offset,
                            code_offset,
                            margin,
                        );
                        for (depth, style) in &multilines {
                            self.theme.draw_multiline_line(&mut buffer, last_buffer_line_num, width_offset, *depth, *style);
                        }
                        for ann in &annotated_file.lines[line_idx].annotations {
                            if let AnnType::MultilineStart(pos) = ann.ann_type {
                                self.theme.draw_multiline_line(
                                    &mut buffer,
                                    last_buffer_line_num,
                                    width_offset,
                                    pos,
                                    if ann.is_primary { Style::UnderlinePrimary } else { Style::UnderlineSecondary },
                                );
                            }
                        }
                    }
                }
                multilines.extend(to_add);
            }
        }
        (buffer, closed)
    }
}

fn is_whitespace(c: char) -> bool {
    matches!(
        c,
        '\u{0009}' | '\u{000A}' | '\u{000B}' | '\u{000C}' | '\u{000D}' | '\u{0020}' | '\u{0085}' | '\u{200E}' | '\u{200F}' | '\u{2028}' | '\u{2029}'
    )
}

fn get_max_line_num(sm: &SourceMap, d: &Diag) -> usize {
    let mut max = get_multispan_max_line_num(sm, &d.span);
    for c in &d.children {
        max = max.max(get_multispan_max_line_num(sm, &c.span));
    }
    max
}

fn get_multispan_max_line_num(sm: &SourceMap, msp: &MultiSpan) -> usize {
    let mut max = 0;
    for sl in msp.span_labels() {
        if sl.span.is_dummy() {
            continue;
        }
        if let Some(f) = sm.lookup_file(sl.span.lo) {
            let lo_rel = sl.span.lo - f.start_pos;
            let hi_rel = sl.span.hi.min(f.end_pos()) - f.start_pos;
            let (hl, _) = lookup_hi(&f, lo_rel, hi_rel);
            max = max.max(hl + 1);
            let (ll, _) = lookup_lo(&f, lo_rel);
            max = max.max(ll + 1);
        }
    }
    max
}

pub fn render(sm: &SourceMap, d: &Diag, cfg: &DiagConfig, color: bool) -> String {
    let short = cfg.human == HumanStyle::Short;
    let r = Renderer {
        sm,
        theme: Theme { unicode: cfg.human != HumanStyle::Ascii },
        short,
        ui_testing: cfg.ui_testing,
        diagnostic_width: cfg.width,
    };
    let max_line_num_len = if cfg.ui_testing { 2 } else { get_max_line_num(sm, d).to_string().len() };
    let mut out = String::new();
    let has_children = !d.children.is_empty() && !short;
    let (mut buf, closed) = r.emit_message_default(&d.span, &d.msg, &d.code, d.level, max_line_num_len, false, has_children);
    let _ = closed;
    if !short {
        let children = &d.children;
        // Handle transitions between primary window and children.
        let primary_has_window = !d.span.is_empty();
        if primary_has_window && !children.is_empty() {
            let nl = buf.num_lines();
            if children[0].span.is_empty() {
                r.theme.draw_col_separator_no_space(&mut buf, nl, max_line_num_len + 1);
            } else {
                r.theme.draw_col_separator_end(&mut buf, nl, max_line_num_len + 1);
            }
        }
        render_buffer(&buf, color, d.level, &mut out);
        for (i, child) in children.iter().enumerate() {
            let next = children.get(i + 1);
            let is_cont = match next {
                Some(c) => c.span.is_empty(),
                None => false,
            };
            let child_has_window = !child.span.is_empty();
            let is_cont_window = next.is_some();
            let (mut cbuf, _) = r.emit_message_default(
                &child.span,
                &child.msg,
                &None,
                child.level,
                max_line_num_len,
                true,
                if child_has_window { is_cont_window } else { is_cont },
            );
            if child_has_window {
                if let Some(n) = next {
                    let nl = cbuf.num_lines();
                    if n.span.is_empty() {
                        r.theme.draw_col_separator_no_space(&mut cbuf, nl, max_line_num_len + 1);
                    } else {
                        r.theme.draw_col_separator_end(&mut cbuf, nl, max_line_num_len + 1);
                    }
                }
            }
            render_buffer(&cbuf, color, child.level, &mut out);
        }
    } else {
        render_buffer(&buf, color, d.level, &mut out);
    }
    out.push('\n');
    out
}

fn json_escape(s: &str, out: &mut String) {
    crate::json::escape_str(s, out);
}

pub fn render_solc_json(sm: &SourceMap, d: &Diag, cfg: &DiagConfig) -> String {
    use crate::json::Json;
    let mut obj: Vec<(String, Json)> = vec![];
    let loc = |sp: Span, msg: Option<&str>| -> Json {
        let mut v: Vec<(String, Json)> = vec![];
        if let Some(f) = sm.lookup_file(sp.lo) {
            v.push(("file".into(), Json::Str(f.display.clone())));
            v.push(("start".into(), Json::Int((sp.lo - f.start_pos) as i64)));
            v.push(("end".into(), Json::Int((sp.hi - f.start_pos) as i64)));
        }
        if let Some(m) = msg {
            v.push(("message".into(), Json::Str(m.to_string())));
        }
        Json::Obj(v)
    };
    match d.span.primary_span() {
        Some(sp) if !sp.is_dummy() => obj.push(("sourceLocation".into(), loc(sp, None))),
        _ => obj.push(("sourceLocation".into(), Json::Null)),
    }
    let mut secondary = vec![];
    for c in &d.children {
        if let Some(sp) = c.span.primary_span() {
            if !sp.is_dummy() {
                secondary.push(loc(sp, Some(&c.msg)));
            }
        }
    }
    obj.push(("secondarySourceLocations".into(), Json::Arr(secondary)));
    obj.push(("type".into(), Json::Str(if d.level == Level::Warning { "Warning".into() } else { "Exception".into() })));
    obj.push(("component".into(), Json::Str("general".into())));
    let sev = match d.level {
        Level::Error | Level::Bug => "error",
        Level::Warning => "warning",
        _ => "info",
    };
    obj.push(("severity".into(), Json::Str(sev.into())));
    obj.push(("errorCode".into(), match &d.code {
        Some(c) => Json::Str(c.clone()),
        None => Json::Null,
    }));
    obj.push(("message".into(), Json::Str(d.msg.clone())));
    let cfg2 = DiagConfig { human: HumanStyle::Unicode, ..*cfg };
    obj.push(("formattedMessage".into(), Json::Str(render(sm, d, &cfg2, false))));
    let mut s = if cfg.pretty_json_err { Json::Obj(obj).to_pretty() } else { Json::Obj(obj).to_compact() };
    s.push('\n');
    s
}

pub fn render_rustc_json(sm: &SourceMap, d: &Diag, cfg: &DiagConfig) -> String {
    use crate::json::Json;
    fn spans_json(sm: &SourceMap, msp: &MultiSpan) -> Json {
        let mut v = vec![];
        for sl in msp.span_labels() {
            if sl.span.is_dummy() {
                continue;
            }
            let Some(f) = sm.lookup_file(sl.span.lo) else { continue };
            let lo = sl.span.lo - f.start_pos;
            let hi = sl.span.hi.min(f.end_pos()) - f.start_pos;
            let (ll, lc) = f.lookup_line_col(lo);
            let (hl, hc) = f.lookup_line_col(hi);
            let mut text = vec![];
            for li in ll..=hl.min(f.num_lines() - 1) {
                let content = f.line_content(li);
                let hs = if li == ll { lc + 1 } else { 1 };
                let he = if li == hl { hc + 1 } else { content.chars().count() + 1 };
                text.push(Json::Obj(vec![
                    ("text".into(), Json::Str(content.to_string())),
                    ("highlight_start".into(), Json::Int(hs as i64)),
                    ("highlight_end".into(), Json::Int(he as i64)),
                ]));
            }
            v.push(Json::Obj(vec![
                ("file_name".into(), Json::Str(f.display.clone())),
                ("byte_start".into(), Json::Int(lo as i64)),
                ("byte_end".into(), Json::Int(hi as i64)),
                ("line_start".into(), Json::Int(ll as i64 + 1)),
                ("line_end".into(), Json::Int(hl as i64 + 1)),
                ("column_start".into(), Json::Int(lc as i64 + 1)),
                ("column_end".into(), Json::Int(hc as i64 + 1)),
                ("is_primary".into(), Json::Bool(sl.is_primary)),
                ("text".into(), Json::Arr(text)),
                ("label".into(), match sl.label {
                    Some(l) => Json::Str(l),
                    None => Json::Null,
                }),
                ("suggested_replacement".into(), Json::Null),
            ]));
        }
        Json::Arr(v)
    }
    let mut children = vec![];
    for c in &d.children {
        children.push(Json::Obj(vec![
            ("message".into(), Json::Str(c.msg.clone())),
            ("code".into(), Json::Null),
            ("level".into(), Json::Str(c.level.as_str().into())),
            ("spans".into(), spans_json(sm, &c.span)),
            ("children".into(), Json::Arr(vec![])),
            ("rendered".into(), Json::Null),
        ]));
    }
    let cfg2 = DiagConfig { human: HumanStyle::Unicode, ..*cfg };
    let obj = Json::Obj(vec![
        ("$message_type".into(), Json::Str("diagnostic".into())),
        ("message".into(), Json::Str(d.msg.clone())),
        ("code".into(), match &d.code {
            Some(c) => Json::Obj(vec![("code".into(), Json::Str(c.clone())), ("explanation".into(), Json::Null)]),
            None => Json::Null,
        }),
        ("level".into(), Json::Str(d.level.as_str().into())),
        ("spans".into(), spans_json(sm, &d.span)),
        ("children".into(), Json::Arr(children)),
        ("rendered".into(), Json::Str(render(sm, d, &cfg2, false))),
    ]);
    let _ = json_escape;
    let mut s = if cfg.pretty_json_err { obj.to_pretty() } else { obj.to_compact() };
    s.push('\n');
    s
}
EOF"}

