use std::cell::RefCell;
use std::collections::HashMap;

#[derive(Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord, Debug)]
pub struct Symbol(pub u32);

struct Interner {
    map: HashMap<&'static str, Symbol>,
    strs: Vec<&'static str>,
}

thread_local! {
    static INTERNER: RefCell<Interner> = RefCell::new(Interner::prefill());
}

impl Interner {
    fn prefill() -> Self {
        let mut i = Interner { map: HashMap::new(), strs: vec![] };
        for s in kw::ALL.iter() {
            i.intern(s);
        }
        i
    }
    fn intern(&mut self, s: &str) -> Symbol {
        if let Some(&sym) = self.map.get(s) {
            return sym;
        }
        let s: &'static str = Box::leak(s.to_string().into_boxed_str());
        let sym = Symbol(self.strs.len() as u32);
        self.strs.push(s);
        self.map.insert(s, sym);
        sym
    }
}

impl Symbol {
    pub fn intern(s: &str) -> Symbol {
        INTERNER.with(|i| i.borrow_mut().intern(s))
    }
    pub fn as_str(&self) -> &'static str {
        INTERNER.with(|i| i.borrow().strs[self.0 as usize])
    }
    pub fn is_used_keyword(self) -> bool {
        self.0 >= kw::USED_START && self.0 < kw::USED_END
    }
    pub fn is_reserved_keyword(self) -> bool {
        self.0 >= kw::RESERVED_START && self.0 < kw::RESERVED_END
    }
    /// Keyword in the Solidity sense (used or reserved).
    pub fn is_keyword(self) -> bool {
        self.is_used_keyword() || self.is_reserved_keyword()
    }
    pub fn is_elementary_type(self) -> bool {
        crate::token::elementary_type_of(self).is_some()
    }
    pub fn is_yul_keyword(self) -> bool {
        matches!(self, kw::Function | kw::Let | kw::If | kw::Switch | kw::Case | kw::Default | kw::For | kw::Break | kw::Continue | kw::Leave | kw::True | kw::False)
    }
}

impl std::fmt::Display for Symbol {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(self.as_str())
    }
}

macro_rules! keywords {
