}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct Token {
    pub kind: TokenKind,
    pub span: Span,
}

impl Token {
    pub fn new(kind: TokenKind, span: Span) -> Token {
        Token { kind, span }
    }
    pub fn is_eof(&self) -> bool {
        self.kind == TokenKind::Eof
    }
    pub fn ident(&self) -> Option<Symbol> {
        match self.kind {
            TokenKind::Ident(s) => Some(s),
            _ => None,
        }
    }
    pub fn is_keyword(&self, k: Symbol) -> bool {
        self.kind == TokenKind::Ident(k)
    }
    pub fn is_non_reserved_ident(&self, yul: bool) -> bool {
        match self.kind {
            TokenKind::Ident(s) => {
                if yul {
                    !s.is_yul_keyword() && !is_yul_builtin_reserved(s)
                } else {
                    !is_keyword_like(s)
                }
            }
            _ => false,
        }
    }
    pub fn is_elementary_type(&self) -> bool {
        matches!(self.kind, TokenKind::Ident(s) if elementary_type_of(s).is_some())
    }
    pub fn is_lit(&self) -> bool {
        matches!(self.kind, TokenKind::Literal(..)) || self.is_bool_lit()
    }
    pub fn is_bool_lit(&self) -> bool {
        matches!(self.kind, TokenKind::Ident(kw::True) | TokenKind::Ident(kw::False))
    }
    pub fn is_str_lit(&self) -> bool {
        matches!(self.kind, TokenKind::Literal(LitKind::Str | LitKind::UnicodeStr | LitKind::HexStr, _))
    }

    /// Description for "found ..." messages.
    pub fn full_description(&self) -> String {
        match self.kind {
            TokenKind::Ident(s) => {
                if is_used_keyword_like(s) {
                    format!("keyword `{}`", s)
                } else if s.is_reserved_keyword() {
                    format!("reserved keyword `{}`", s)
                } else {
                    format!("`{}`", s)
                }
            }
            TokenKind::Literal(k, _) => format!("`{}`", lit_kind_descr(k)),
            TokenKind::Eof => "`<eof>`".to_string(),
            _ => format!("`{}`", token_kind_str(&self.kind)),
        }
    }
}

pub fn is_yul_builtin_reserved(_s: Symbol) -> bool {
    false
}

pub fn lit_kind_descr(k: LitKind) -> &'static str {
    match k {
        LitKind::Integer => "<integer>",
        LitKind::Rational => "<rational>",
        LitKind::Str => "<string>",
        LitKind::UnicodeStr => "<unicode string>",
        LitKind::HexStr => "<hex string>",
        LitKind::Err => "<error>",
    }
}

pub fn is_used_keyword_like(s: Symbol) -> bool {
    s.is_used_keyword() || elementary_type_of(s).is_some()
}

pub fn is_keyword_like(s: Symbol) -> bool {
    s.is_keyword() || elementary_type_of(s).is_some()
}

pub fn token_kind_str(k: &TokenKind) -> String {
    use TokenKind::*;
    match k {
        Eq => "=".into(),
        Lt => "<".into(),
        Le => "<=".into(),
        EqEq => "==".into(),
        Ne => "!=".into(),
        Ge => ">=".into(),
        Gt => ">".into(),
        AndAnd => "&&".into(),
        OrOr => "||".into(),
        Not => "!".into(),
        Tilde => "~".into(),
        Walrus => ":=".into(),
        PlusPlus => "++".into(),
        MinusMinus => "--".into(),
        StarStar => "**".into(),
        BinOp(b) => b.as_str().into(),
        BinOpEq(b) => format!("{}=", b.as_str()),
        At => "@".into(),
        Dot => ".".into(),
        Comma => ",".into(),
        Semi => ";".into(),
        Colon => ":".into(),
        Arrow => "->".into(),
        FatArrow => "=>".into(),
        Question => "?".into(),
        OpenDelim(Delim::Paren) => "(".into(),
        OpenDelim(Delim::Brace) => "{".into(),
        OpenDelim(Delim::Bracket) => "[".into(),
        CloseDelim(Delim::Paren) => ")".into(),
        CloseDelim(Delim::Brace) => "}".into(),
        CloseDelim(Delim::Bracket) => "]".into(),
        Literal(_, s) => s.as_str().into(),
        Ident(s) => s.as_str().into(),
        Comment(..) => "<comment>".into(),
        Eof => "<eof>".into(),
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug, Hash)]
pub enum ElemTy {
    Address(bool),
    Bool,
    String,
    Bytes,
    Fixed(u16, u8),
    UFixed(u16, u8),
    Int(u16),
    UInt(u16),
    FixedBytes(u8),
}

pub fn elementary_type_of(s: Symbol) -> Option<ElemTy> {
    match s {
        kw::Address => return Some(ElemTy::Address(false)),
        kw::Bool => return Some(ElemTy::Bool),
        kw::String => return Some(ElemTy::String),
        kw::Bytes => return Some(ElemTy::Bytes),
        kw::Int => return Some(ElemTy::Int(256)),
        kw::UInt => return Some(ElemTy::UInt(256)),
        kw::Fixed => return Some(ElemTy::Fixed(128, 18)),
        kw::UFixed => return Some(ElemTy::UFixed(128, 18)),
        _ => {}
    }
    let st = s.as_str();
    let parse_num = |rest: &str| -> Option<u32> {
        if rest.is_empty() || rest.starts_with('0') || !rest.bytes().all(|b| b.is_ascii_digit()) || rest.len() > 3 {
            return None;
        }
        rest.parse().ok()
    };
    if let Some(rest) = st.strip_prefix("uint") {
        let n = parse_num(rest)?;
        if n % 8 == 0 && (8..=256).contains(&n) {
            return Some(ElemTy::UInt(n as u16));
        }
        return None;
    }
    if let Some(rest) = st.strip_prefix("int") {
        let n = parse_num(rest)?;
        if n % 8 == 0 && (8..=256).contains(&n) {
            return Some(ElemTy::Int(n as u16));
        }
        return None;
    }
    if let Some(rest) = st.strip_prefix("bytes") {
        let n = parse_num(rest)?;
        if (1..=32).contains(&n) {
            return Some(ElemTy::FixedBytes(n as u8));
        }
        return None;
    }
    None
}
