use crate::diag::{Diag, DiagCtxt, Level};
use crate::source_map::Span;
use crate::symbol::Symbol;
use crate::token::*;

pub struct Lexer<'a> {
    src: &'a str,
    bytes: &'a [u8],
    pos: usize,
    base: u32,
    dcx: &'a DiagCtxt,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Base {
    Binary,
    Octal,
    Decimal,
    Hexadecimal,
}

pub fn is_id_start(c: char) -> bool {
    c.is_ascii_alphabetic() || c == '_' || c == '$'
}
pub fn is_id_continue(c: char) -> bool {
    c.is_ascii_alphanumeric() || c == '_' || c == '$'
}

impl<'a> Lexer<'a> {
    pub fn new(src: &'a str, base: u32, dcx: &'a DiagCtxt) -> Self {
        Lexer { src, bytes: src.as_bytes(), pos: 0, base, dcx }
    }

    fn first(&self) -> char {
        self.src[self.pos..].chars().next().unwrap_or('\0')
    }
    fn second(&self) -> char {
        let mut it = self.src[self.pos..].chars();
        it.next();
        it.next().unwrap_or('\0')
    }
    fn is_eof(&self) -> bool {
        self.pos >= self.bytes.len()
    }
    fn bump(&mut self) -> Option<char> {
        let c = self.src[self.pos..].chars().next()?;
        self.pos += c.len_utf8();
        Some(c)
    }
    fn eat_while(&mut self, f: impl Fn(char) -> bool) {
        while !self.is_eof() && f(self.first()) {
            self.bump();
        }
    }
    fn span(&self, lo: usize, hi: usize) -> Span {
        Span::new(self.base + lo as u32, self.base + hi as u32)
    }
    fn err(&self, lo: usize, hi: usize, msg: &str) {
        self.dcx.emit(Diag::new(Level::Error, msg).span(self.span(lo, hi)));
    }

    pub fn tokenize(mut self) -> Vec<Token> {
        let mut toks = Vec::new();
        loop {
            let t = self.next_token();
            let eof = t.kind == TokenKind::Eof;
            toks.push(t);
            if eof {
                break;
            }
        }
        toks
    }

    fn next_token(&mut self) -> Token {
        loop {
            let start = self.pos;
            if self.is_eof() {
                let l = self.bytes.len();
                return Token::new(TokenKind::Eof, self.span(l, l));
            }
            let c = self.bump().unwrap();
            let kind = match c {
                ' ' | '\t' | '\n' | '\r' => {
                    self.eat_while(|c| matches!(c, ' ' | '\t' | '\n' | '\r'));
                    continue;
                }
                '/' => match self.first() {
                    '/' => {
                        self.bump();
                        let is_doc = self.first() == '/' && self.second() != '/';
                        self.eat_while(|c| c != '\n');
                        if is_doc {
                            let content_start = start + 3;
                            let mut end = self.pos;
                            if end > content_start && self.bytes[end - 1] == b'\r' {
                                end -= 1;
                            }
                            let sym = Symbol::intern(&self.src[content_start..end]);
                            TokenKind::Comment(true, CommentKind::Line, sym)
                        } else {
                            continue;
                        }
                    }
                    '*' => {
                        self.bump();
                        let is_doc = self.first() == '*' && !matches!(self.second(), '*' | '/');
                        let mut depth_terminated = false;
                        while let Some(c) = self.bump() {
                            if c == '*' && self.first() == '/' {
                                self.bump();
                                depth_terminated = true;
                                break;
                            }
                        }
                        if !depth_terminated {
                            self.err(start, self.pos, "unterminated block comment");
                            continue;
                        }
                        if is_doc {
                            let sym = Symbol::intern(&self.src[start + 3..self.pos - 2]);
                            TokenKind::Comment(true, CommentKind::Block, sym)
                        } else {
                            continue;
                        }
                    }
                    '=' => {
                        self.bump();
                        TokenKind::BinOpEq(BinOpToken::Slash)
                    }
                    _ => TokenKind::BinOp(BinOpToken::Slash),
                },
                c if is_id_start(c) => {
                    self.eat_while(is_id_continue);
                    let word = &self.src[start..self.pos];
                    if (word == "unicode" || word == "hex") && matches!(self.first(), '"' | '\'') {
                        let q = self.bump().unwrap();
                        let terminated = self.eat_string(q);
                        let kind = if word == "hex" { LitKind::HexStr } else { LitKind::UnicodeStr };
                        let content_start = start + word.len() + 1;
                        let content_end = if terminated { self.pos - 1 } else { self.pos };
                        if !terminated {
                            self.err(start, self.pos, "unterminated string");
                        }
                        TokenKind::Literal(kind, Symbol::intern(&self.src[content_start..content_end]))
                    } else {
                        TokenKind::Ident(Symbol::intern(word))
                    }
                }
                '0'..='9' => self.number(start, c),
                '.' if self.first().is_ascii_digit() => self.number(start, c),
                '"' | '\'' => {
                    let terminated = self.eat_string(c);
                    let content_end = if terminated { self.pos - 1 } else { self.pos };
                    if !terminated {
                        self.err(start, self.pos, "unterminated string");
                    }
                    TokenKind::Literal(LitKind::Str, Symbol::intern(&self.src[start + 1..content_end]))
                }
                ';' => TokenKind::Semi,
                ',' => TokenKind::Comma,
                '.' => TokenKind::Dot,
                '(' => TokenKind::OpenDelim(Delim::Paren),
                ')' => TokenKind::CloseDelim(Delim::Paren),
                '{' => TokenKind::OpenDelim(Delim::Brace),
                '}' => TokenKind::CloseDelim(Delim::Brace),
                '[' => TokenKind::OpenDelim(Delim::Bracket),
                ']' => TokenKind::CloseDelim(Delim::Bracket),
                '~' => TokenKind::Tilde,
                '?' => TokenKind::Question,
                ':' => {
                    if self.first() == '=' {
                        self.bump();
                        TokenKind::Walrus
                    } else {
                        TokenKind::Colon
                    }
                }
                '=' => match self.first() {
                    '=' => {
                        self.bump();
                        TokenKind::EqEq
                    }
                    '>' => {
                        self.bump();
                        TokenKind::FatArrow
                    }
                    _ => TokenKind::Eq,
                },
                '!' => {
                    if self.first() == '=' {
                        self.bump();
                        TokenKind::Ne
                    } else {
                        TokenKind::Not
                    }
                }
                '<' => match self.first() {
                    '=' => {
                        self.bump();
                        TokenKind::Le
                    }
                    '<' => {
                        self.bump();
                        if self.first() == '=' {
                            self.bump();
                            TokenKind::BinOpEq(BinOpToken::Shl)
                        } else {
                            TokenKind::BinOp(BinOpToken::Shl)
                        }
                    }
                    _ => TokenKind::Lt,
                },
                '>' => match self.first() {
                    '=' => {
                        self.bump();
                        TokenKind::Ge
                    }
                    '>' => {
                        self.bump();
                        match self.first() {
                            '=' => {
                                self.bump();
                                TokenKind::BinOpEq(BinOpToken::Shr)
                            }
                            '>' => {
                                self.bump();
                                if self.first() == '=' {
                                    self.bump();
                                    TokenKind::BinOpEq(BinOpToken::Sar)
                                } else {
                                    TokenKind::BinOp(BinOpToken::Sar)
                                }
                            }
                            _ => TokenKind::BinOp(BinOpToken::Shr),
                        }
                    }
                    _ => TokenKind::Gt,
                },
                '&' => match self.first() {
                    '&' => {
                        self.bump();
                        TokenKind::AndAnd
                    }
                    '=' => {
                        self.bump();
                        TokenKind::BinOpEq(BinOpToken::And)
                    }
                    _ => TokenKind::BinOp(BinOpToken::And),
                },
                '|' => match self.first() {
                    '|' => {
                        self.bump();
                        TokenKind::OrOr
                    }
                    '=' => {
                        self.bump();
                        TokenKind::BinOpEq(BinOpToken::Or)
                    }
                    _ => TokenKind::BinOp(BinOpToken::Or),
                },
                '+' => match self.first() {
                    '+' => {
                        self.bump();
                        TokenKind::PlusPlus
                    }
                    '=' => {
                        self.bump();
                        TokenKind::BinOpEq(BinOpToken::Plus)
                    }
                    _ => TokenKind::BinOp(BinOpToken::Plus),
                },
                '-' => match self.first() {
                    '-' => {
                        self.bump();
                        TokenKind::MinusMinus
                    }
                    '=' => {
                        self.bump();
                        TokenKind::BinOpEq(BinOpToken::Minus)
                    }
                    '>' => {
                        self.bump();
                        TokenKind::Arrow
                    }
                    _ => TokenKind::BinOp(BinOpToken::Minus),
                },
                '*' => match self.first() {
                    '*' => {
                        self.bump();
                        TokenKind::StarStar
                    }
                    '=' => {
                        self.bump();
                        TokenKind::BinOpEq(BinOpToken::Star)
                    }
                    _ => TokenKind::BinOp(BinOpToken::Star),
                },
                '%' => {
                    if self.first() == '=' {
                        self.bump();
                        TokenKind::BinOpEq(BinOpToken::Percent)
                    } else {
                        TokenKind::BinOp(BinOpToken::Percent)
                    }
                }
                '^' => {
                    if self.first() == '=' {
                        self.bump();
                        TokenKind::BinOpEq(BinOpToken::Caret)
                    } else {
                        TokenKind::BinOp(BinOpToken::Caret)
                    }
                }
                c => {
                    let repr = if c.is_ascii() && !c.is_ascii_control() { c.to_string() } else { format!("\\u{{{:x}}}", c as u32) };
                    self.err(start, self.pos, &format!("unknown start of token: {repr}"));
                    continue;
                }
            };
            return Token::new(kind, self.span(start, self.pos));
        }
    }

    /// Eats a string body after the opening quote. Returns whether it was terminated.
    fn eat_string(&mut self, q: char) -> bool {
        while let Some(c) = self.bump() {
            if c == q {
                return true;
            }
            if c == '\\' {
                if !self.is_eof() {
                    self.bump();
                }
            }
        }
        false
    }

    fn eat_decimal_digits(&mut self) -> bool {
        let mut has = false;
        loop {
            match self.first() {
                '_' => {
                    self.bump();
                }
                '0'..='9' => {
                    has = true;
                    self.bump();
                }
                _ => break,
            }
        }
        has
    }
    fn eat_hex_digits(&mut self) -> bool {
        let mut has = false;
        loop {
            match self.first() {
                '_' => {
                    self.bump();
                }
                '0'..='9' | 'a'..='f' | 'A'..='F' => {
                    has = true;
                    self.bump();
                }
                _ => break,
            }
        }
        has
    }

    /// Returns (has_digits, plus_pos)
    fn eat_exponent(&mut self) -> (bool, Option<usize>) {
        let mut plus = None;
        if self.first() == '-' {
            self.bump();
        } else if self.first() == '+' {
            plus = Some(self.pos);
            self.bump();
        }
        (self.eat_decimal_digits(), plus)
    }

    fn number(&mut self, start: usize, first: char) -> TokenKind {
        let mut base = Base::Decimal;
        let mut kind = LitKind::Integer;
        let mut empty_int = false;
        let mut empty_exponent = false;
        let mut plus_in_exp = None;
        let mut empty_rational = false;
        if first == '.' {
            // rational starting with a dot
            self.eat_decimal_digits();
            kind = LitKind::Rational;
            if matches!(self.first(), 'e' | 'E') {
                self.bump();
                let (h, p) = self.eat_exponent();
                empty_exponent = !h;
                plus_in_exp = p;
            }
        } else {
            let mut done = false;
            if first == '0' {
                match self.first() {
                    'x' => {
                        self.bump();
                        base = Base::Hexadecimal;
                        if !self.eat_hex_digits() {
                            empty_int = true;
                        }
                    }
                    'b' => {
                        self.bump();
                        base = Base::Binary;
                        if !self.eat_decimal_digits() {
                            empty_int = true;
                        }
                    }
                    'o' => {
                        self.bump();
                        base = Base::Octal;
                        if !self.eat_decimal_digits() {
                            empty_int = true;
                        }
                    }
                    '0'..='9' | '_' => {
                        self.eat_decimal_digits();
                    }
                    '.' | 'e' | 'E' => {}
                    _ => {
                        done = true;
                    }
                }
            } else {
                self.eat_decimal_digits();
            }
            if !done && !empty_int {
                match self.first() {
                    '.' if !is_id_start(self.second()) => {
                        self.bump();
                        kind = LitKind::Rational;
                        if self.first().is_ascii_digit() {
                            self.eat_decimal_digits();
                            if matches!(self.first(), 'e' | 'E') {
                                self.bump();
                                let (h, p) = self.eat_exponent();
                                empty_exponent = !h;
                                plus_in_exp = p;
                            }
                        } else if matches!(self.first(), 'e' | 'E') {
                            self.bump();
                            let (h, p) = self.eat_exponent();
                            empty_exponent = !h;
                            plus_in_exp = p;
                        } else {
                            empty_rational = true;
                        }
                    }
                    'e' | 'E' if base == Base::Decimal => {
                        self.bump();
                        kind = LitKind::Rational;
                        let (h, p) = self.eat_exponent();
                        empty_exponent = !h;
                        plus_in_exp = p;
                    }
                    _ => {}
                }
            }
        }
        let end = self.pos;
        let text = &self.src[start..end];
        let mut kind_out = kind;
        if empty_int {
            self.err(start, end, "no valid digits found for number");
            kind_out = LitKind::Err;
        } else if base == Base::Binary || base == Base::Octal {
            let name = if base == Base::Binary { "binary" } else { "octal" };
            self.err(start + 2, end, &format!("integers in base {name} are not supported"));
            kind_out = LitKind::Err;
        } else if base == Base::Hexadecimal && kind == LitKind::Rational {
            self.err(start, end, "hexadecimal rational numbers are not supported");
            kind_out = LitKind::Err;
        } else if let Some(p) = plus_in_exp {
            let _ = p;
            self.err(start, end, "`+` is not allowed in the exponent");
            kind_out = LitKind::Err;
        } else if empty_exponent {
            self.err(start, end, "expected at least one digit in exponent");
            kind_out = LitKind::Err;
        } else if empty_rational {
            self.err(start, end, "empty rational");
            kind_out = LitKind::Err;
        } else if base == Base::Decimal && text.len() >= 2 && text.as_bytes()[0] == b'0' && text.as_bytes()[1].is_ascii_digit() {
            self.err(start, end, "leading zeros are not allowed in integers");
            kind_out = LitKind::Err;
        }
        let kind_out = if kind_out == LitKind::Err { kind } else { kind_out };
        TokenKind::Literal(kind_out, Symbol::intern(text))
    }
}
