            self.err(start, end, "`+` is not allowed in the exponent");
            kind_out = LitKind::Err;
        } else if empty_exponent {
            self.err(start, end, "expected at least one digit in exponent");
            kind_out = LitKind::Err;
        } else if empty_rational {
