// Minimal clap-like command line parser reproducing clap's messages.
use std::io::Write;

#[derive(Default, Debug, Clone)]
pub struct Args {
    pub inputs: Vec<String>,
    pub threads: Option<usize>,
    pub evm_version: Option<String>,
    pub stop_after: Option<String>,
    pub out_dir: Option<String>,
    pub emit: Vec<String>,
    pub z: Vec<String>,
    pub base_path: Option<String>,
    pub include_paths: Vec<String>,
    pub allow_paths: Vec<String>,
    pub color: Option<String>,
    pub verbose: bool,
    pub pretty_json: bool,
    pub pretty_json_err: bool,
    pub error_format: Option<String>,
    pub error_format_human: Option<String>,
    pub diagnostic_width: Option<usize>,
    pub no_warnings: bool,
    // unstable
    pub ui_testing: bool,
    pub track_diagnostics: bool,
    pub parse_yul: bool,
    pub no_resolve_imports: bool,
    pub dump: Option<(String, Vec<String>)>,
    pub ast_stats: bool,
    pub span_visitor: bool,
    pub print_max_storage_sizes: bool,
    pub typeck: bool,
}

#[derive(Clone, Copy, PartialEq)]
enum Kind {
    Flag,
    Opt,
}

struct ArgDef {
    id: &'static str,
    long: &'static str,
    aliases: &'static [&'static str],
    short: Option<char>,
    kind: Kind,
    value_name: &'static str,
    possible: &'static [&'static str],
    multiple: bool,
}

