#[derive(Default, Debug, Clone)]
pub struct Args {
    pub inputs: Vec<String>,
    pub threads: Option<usize>,
    pub evm_version: Option<String>,
    pub stop_after: Option<String>,
    pub out_dir: Option<String>,
