    pub span_visitor: bool,
    pub print_max_storage_sizes: bool,
    pub typeck: bool,
}

#[derive(Clone, Copy, PartialEq)]
enum Kind {
    Flag,
    Opt,
}

struct ArgDef {
    id: &'static str,
    long: &'static str,
    aliases: &'static [&'static str],
    short: Option<char>,
    kind: Kind,
    value_name: &'static str,
    possible: &'static [&'static str],
    multiple: bool,
}

const EVM_VERSIONS: &[&str] = &[
    "homestead", "tangerineWhistle", "spuriousDragon", "byzantium", "constantinople", "petersburg", "istanbul", "berlin", "london", "paris", "shanghai", "cancun",
    "prague", "osaka",
];

const DEFS: &[ArgDef] = &[
    ArgDef { id: "threads", long: "threads", aliases: &["jobs"], short: Some('j'), kind: Kind::Opt, value_name: "THREADS", possible: &[], multiple: false },
    ArgDef { id: "evm_version", long: "evm-version", aliases: &[], short: None, kind: Kind::Opt, value_name: "EVM_VERSION", possible: EVM_VERSIONS, multiple: false },
    ArgDef { id: "stop_after", long: "stop-after", aliases: &[], short: None, kind: Kind::Opt, value_name: "STOP_AFTER", possible: &["parsing", "lowering", "analysis"], multiple: false },
    ArgDef { id: "out_dir", long: "out-dir", aliases: &[], short: None, kind: Kind::Opt, value_name: "OUT_DIR", possible: &[], multiple: false },
    ArgDef { id: "emit", long: "emit", aliases: &[], short: None, kind: Kind::Opt, value_name: "EMIT", possible: &["abi", "hashes"], multiple: true },
    ArgDef { id: "z", long: "", aliases: &[], short: Some('Z'), kind: Kind::Opt, value_name: "FLAG", possible: &[], multiple: true },
    ArgDef { id: "help", long: "help", aliases: &[], short: Some('h'), kind: Kind::Flag, value_name: "", possible: &[], multiple: true },
    ArgDef { id: "version", long: "version", aliases: &[], short: Some('V'), kind: Kind::Flag, value_name: "", possible: &[], multiple: true },
    ArgDef { id: "base_path", long: "base-path", aliases: &[], short: None, kind: Kind::Opt, value_name: "BASE_PATH", possible: &[], multiple: false },
    ArgDef { id: "include_path", long: "include-path", aliases: &[], short: Some('I'), kind: Kind::Opt, value_name: "INCLUDE_PATH", possible: &[], multiple: true },
