fn arg_display(d: &ArgDef) -> String {
    if d.id == "z" {
        return "-Z <FLAG>".to_string();
    }
    match d.kind {
        Kind::Flag => format!("--{}", d.long),
        Kind::Opt => format!("--{} <{}>", d.long, d.value_name),
    }
}

pub fn bin_name() -> String {
    std::env::args_os()
        .next()
        .and_then(|a| std::path::Path::new(&a).file_name().map(|s| s.to_string_lossy().into_owned()))
        .unwrap_or_else(|| "solar".to_string())
}

fn exit_err(msg: &str) -> ! {
    let _ = std::io::stderr().write_all(msg.as_bytes());
    std::process::exit(2);
}

pub fn jaro(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let (la, lb) = (a.len(), b.len());
    if la == 0 && lb == 0 {
        return 1.0;
    }
    if la == 0 || lb == 0 {
        return 0.0;
    }
    let search_range = (la.max(lb) / 2).saturating_sub(1);
    let mut b_consumed = vec![false; lb];
    let mut matches = 0.0;
    let mut transpositions = 0.0;
    let mut b_match_index = 0;
    for (i, ac) in a.iter().enumerate() {
        let bound_start = i.saturating_sub(search_range);
        let bound_end = (i + search_range + 1).min(lb);
        if bound_start >= bound_end {
            continue;
        }
        for j in bound_start..bound_end {
            if *ac == b[j] && !b_consumed[j] {
                b_consumed[j] = true;
                matches += 1.0;
                if j < b_match_index {
                    transpositions += 1.0;
                }
                b_match_index = j;
                break;
            }
        }
    }
    if matches == 0.0 {
        0.0
    } else {
        (1.0 / 3.0) * ((matches / la as f64) + (matches / lb as f64) + ((matches - transpositions) / matches))
    }
}

fn did_you_mean<'a>(v: &str, candidates: impl Iterator<Item = &'a str>) -> Option<String> {
    let mut best: Option<(f64, String)> = None;
    for c in candidates {
        let conf = jaro(v, c);
        if conf > 0.7 {
            match &best {
                Some((b, _)) if *b >= conf => {}
                _ => best = Some((conf, c.to_string())),
            }
        }
    }
    best.map(|(_, s)| s)
}

struct Parser {
    bin: String,
    used: Vec<&'static str>, // ids in order used
    inputs_used: bool,
}

impl Parser {
    fn usage_default(&self) -> String {
        format!("Usage: {} [OPTIONS] [INPUT]...", self.bin)
    }
    fn usage_used(&self, extra: Option<&'static str>) -> String {
        let mut parts = vec![];
        let mut ids: Vec<&'static str> = self.used.clone();
        if let Some(e) = extra {
            if !ids.contains(&e) {
                ids.push(e);
            }
        }
        for id in ids {
            let d = DEFS.iter().find(|d| d.id == id).unwrap();
            parts.push(arg_display(d));
        }
        if self.inputs_used {
            parts.push("<INPUT>...".to_string());
        } else {
            parts.push("[INPUT]...".to_string());
        }
        format!("Usage: {} {}", self.bin, parts.join(" "))
    }
}

pub fn parse(argv: Vec<String>) -> Args {
    let bin = bin_name();
    let mut p = Parser { bin: bin.clone(), used: vec![], inputs_used: false };
    let mut args = Args::default();
    if argv.is_empty() {
        let help = include_str!("text/short_help.txt").replace("Usage: executable", &format!("Usage: {bin}"));
        exit_err(&help);
    }
    let mut i = 0;
    let mut trailing = false;
    let mut values: Vec<(&'static str, String)> = vec![];
    let mut seen: Vec<&'static str> = vec![];
    while i < argv.len() {
        let a = argv[i].clone();
        i += 1;
        if trailing {
            args.inputs.push(a);
            p.inputs_used = true;
            continue;
        }
        if a == "--" {
            trailing = true;
            continue;
        }
        if let Some(rest) = a.strip_prefix("--") {
            let (name, inline_val) = match rest.find('=') {
                Some(eq) => (&rest[..eq], Some(rest[eq + 1..].to_string())),
                None => (rest, None),
            };
            let def = DEFS.iter().find(|d| !d.long.is_empty() && (d.long == name || d.aliases.contains(&name)));
            let Some(def) = def else {
                // unknown
                let cands: Vec<&str> = DEFS.iter().filter(|d| !d.long.is_empty()).flat_map(|d| std::iter::once(d.long)).collect();
                let sugg = did_you_mean(name, cands.into_iter());
                let mut msg = format!("error: unexpected argument '{}' found\n\n", a);
                match sugg {
                    Some(s) => {
                        let d = DEFS.iter().find(|d| d.long == s).unwrap();
                        msg.push_str(&format!("  tip: a similar argument exists: '--{}'\n\n", s));
                        msg.push_str(&p.usage_used(Some(d.id)));
                    }
                    None => {
                        msg.push_str(&format!("  tip: to pass '{}' as a value, use '-- {}'\n\n", a, a));
                        msg.push_str(&p.usage_default());
                    }
                }
                msg.push_str("\n\nFor more information, try '--help'.\n");
                exit_err(&msg);
            };
            handle_def(def, inline_val, &argv, &mut i, &mut p, &mut values, &mut seen, &mut args);
            continue;
        }
        if a.starts_with('-') && a.len() > 1 {
            // short options
            let chars: Vec<char> = a[1..].chars().collect();
            let mut ci = 0;
            while ci < chars.len() {
                let c = chars[ci];
                let def = DEFS.iter().find(|d| d.short == Some(c));
                let Some(def) = def else {
                    let shown = if ci == 0 { a.clone() } else { format!("-{}", c) };
                    let mut msg = format!("error: unexpected argument '{}' found\n\n", shown);
                    msg.push_str(&format!("  tip: to pass '{}' as a value, use '-- {}'\n\n", shown, shown));
                    msg.push_str(&p.usage_default());
                    msg.push_str("\n\nFor more information, try '--help'.\n");
                    exit_err(&msg);
                };
                if def.kind == Kind::Opt {
                    let rest: String = chars[ci + 1..].iter().collect();
                    let inline = if rest.is_empty() {
                        None
                    } else {
                        Some(rest.strip_prefix('=').map(|s| s.to_string()).unwrap_or(rest))
                    };
                    handle_def(def, inline, &argv, &mut i, &mut p, &mut values, &mut seen, &mut args);
                    break;
                } else {
                    handle_def(def, None, &argv, &mut i, &mut p, &mut values, &mut seen, &mut args);
                }
                ci += 1;
            }
            continue;
        }
        args.inputs.push(a);
        p.inputs_used = true;
    }
    // Apply help/version: clap processes them immediately when encountered; handled in handle_def.
    for (id, v) in values {
        apply_value(id, v, &mut args, &p);
    }
    args
}

#[allow(clippy::too_many_arguments)]
fn handle_def(
    def: &'static ArgDef,
    inline_val: Option<String>,
    argv: &[String],
    i: &mut usize,
    p: &mut Parser,
    values: &mut Vec<(&'static str, String)>,
    seen: &mut Vec<&'static str>,
    args: &mut Args,
) {
    if seen.contains(&def.id) && !def.multiple {
        let msg = format!(
            "error: the argument '{}' cannot be used multiple times\n\n{}\n\nFor more information, try '--help'.\n",
            arg_display(def),
            p.usage_default()
        );
        exit_err(&msg);
    }
    if def.kind == Kind::Flag {
        if let Some(v) = inline_val {
            let msg = format!(
                "error: unexpected value '{}' for '{}' found; no more were expected\n\nUsage: {} {} [INPUT]...\n\nFor more information, try '--help'.\n",
                v,
                arg_display(def),
                p.bin,
                arg_display(def)
            );
            exit_err(&msg);
        }
        seen.push(def.id);
        if !p.used.contains(&def.id) {
            p.used.push(def.id);
        }
        match def.id {
            "help" => {
                let long = argv.iter().take(*i).any(|a| a == "--help");
                let text = if long { include_str!("text/long_help.txt") } else { include_str!("text/short_help.txt") };
                let text = text.replace("Usage: executable", &format!("Usage: {}", p.bin));
                print!("{}", text);
                let _ = std::io::stdout().flush();
                std::process::exit(0);
            }
            "version" => {
                let long = argv.iter().take(*i).any(|a| a == "--version");
                if long {
                    print!("{}", LONG_VERSION);
                } else {
                    println!("solar 0.1.8 (68ee046 2026-06-11T22:26:27.063303266Z)");
                }
                let _ = std::io::stdout().flush();
                std::process::exit(0);
            }
            "verbose" => args.verbose = true,
            "pretty_json" => args.pretty_json = true,
            "pretty_json_err" => args.pretty_json_err = true,
            "no_warnings" => args.no_warnings = true,
            _ => {}
        }
        return;
    }
    let val = match inline_val {
        Some(v) => v,
        None => {
            if *i < argv.len() && !(argv[*i].starts_with('-') && argv[*i].len() > 1 && !is_negative_number(&argv[*i])) {
                let v = argv[*i].clone();
                *i += 1;
                v
            } else {
                let mut msg = format!("error: a value is required for '{}' but none was supplied\n", arg_display(def));
                if !def.possible.is_empty() {
                    msg.push_str(&format!("  [possible values: {}]\n", def.possible.join(", ")));
                }
                msg.push_str("\nFor more information, try '--help'.\n");
                exit_err(&msg);
            }
        }
    };
    seen.push(def.id);
    if !p.used.contains(&def.id) {
        p.used.push(def.id);
    }
    // validate
    let parts: Vec<String> = if def.id == "emit" { val.split(',').map(|s| s.to_string()).collect() } else { vec![val.clone()] };
    for part in &parts {
        if !def.possible.is_empty() && !def.possible.contains(&part.as_str()) {
            let mut msg = format!("error: invalid value '{}' for '{}'\n  [possible values: {}]\n", part, arg_display(def), def.possible.join(", "));
            if let Some(s) = did_you_mean(part, def.possible.iter().copied()) {
                msg.push_str(&format!("\n  tip: a similar value exists: '{}'\n", s));
            }
            msg.push_str("\nFor more information, try '--help'.\n");
            exit_err(&msg);
        }
        if def.id == "threads" || def.id == "diagnostic_width" {
            if let Err(e) = part.parse::<usize>() {
                let msg = format!("error: invalid value '{}' for '{}': {}\n\nFor more information, try '--help'.\n", part, arg_display(def), e);
                exit_err(&msg);
            }
        }
        if def.id == "z" {
            parse_z(part, args, p);
        }
    }
    for part in parts {
        values.push((def.id, part));
    }
}

fn is_negative_number(s: &str) -> bool {
    s.len() > 1 && s.starts_with('-') && s[1..].parse::<f64>().is_ok()
}

fn apply_value(id: &str, v: String, args: &mut Args, _p: &Parser) {
    match id {
        "threads" => args.threads = v.parse().ok(),
        "evm_version" => args.evm_version = Some(v),
        "stop_after" => args.stop_after = Some(v),
        "out_dir" => args.out_dir = Some(v),
        "emit" => {
            if !args.emit.contains(&v) {
                args.emit.push(v)
            }
        }
        "z" => args.z.push(v),
        "base_path" => args.base_path = Some(v),
        "include_path" => args.include_paths.push(v),
        "allow_paths" => args.allow_paths.push(v),
        "color" => args.color = Some(v),
        "error_format" => args.error_format = Some(v),
        "error_format_human" => args.error_format_human = Some(v),
        "diagnostic_width" => args.diagnostic_width = v.parse().ok(),
        _ => {}
    }
}

const LONG_VERSION: &str = "solar Version: 0.1.8\nCommit SHA: 68ee0465d27e83bb91d1fb3a655d4b005394c27a\nBuild Timestamp: 2026-06-11T22:26:27.063303266Z\nBuild Features: mimalloc,tracing\nBuild Profile: release\n";

const Z_FLAGS: &[(&str, bool)] = &[
    ("ui-testing", false),
    ("track-diagnostics", false),
    ("parse-yul", false),
    ("no-resolve-imports", false),
    ("dump", true),
    ("ast-stats", false),
    ("span-visitor", false),
    ("print-max-storage-sizes", false),
    ("typeck", false),
    ("help", false),
];

fn z_err(inner: &str) -> ! {
    let msg = format!("error:  {}\nUsage: solar [OPTIONS] [INPUT]...\n\nFor more information, try '--help'.\n", inner);
    exit_err(&msg);
}

fn parse_z(v: &str, args: &mut Args, _p: &Parser) {
    let (name, val) = match v.find('=') {
        Some(eq) => (&v[..eq], Some(&v[eq + 1..])),
        None => (v, None),
    };
    let Some(&(fname, takes)) = Z_FLAGS.iter().find(|(n, _)| *n == name) else {
        let sugg = did_you_mean(name, Z_FLAGS.iter().map(|(n, _)| *n));
        let mut inner = format!("unexpected argument '-Z{}' found\n\n", v);
        match sugg {
            Some(s) => {
                let takes = Z_FLAGS.iter().find(|(n, _)| *n == s).unwrap().1;
                inner.push_str(&format!("  tip: a similar argument exists: '-Z{}'\n\n", s));
                if takes {
                    inner.push_str("Usage: solar -Zdump=<KIND[=PATHS...]>\n");
                } else {
                    inner.push_str(&format!("Usage: solar -Z{}\n", s));
                }
            }
            None => {
                inner.push_str("Usage: solar [OPTIONS]\n");
            }
        }
        inner.push_str("\nFor more information, try '-Zhelp'.\n");
        z_err(&inner);
    };
    if takes {
        let Some(val) = val else {
            z_err("equal sign is needed when assigning values to '-Zdump=<KIND[=PATHS...]>'\n\nUsage: solar [OPTIONS]\n\nFor more information, try '-Zhelp'.\n");
        };
        let (kind, paths) = match val.find('=') {
            Some(eq) => (&val[..eq], Some(&val[eq + 1..])),
            None => (val, None),
        };
        if kind != "ast" && kind != "hir" {
            z_err(&format!(
                "invalid value '{}' for '-Zdump=<KIND[=PATHS...]>': Matching variant not found\n\nFor more information, try '-Zhelp'.\n",
                val
            ));
        }
        let paths: Vec<String> = paths.map(|p| p.split(',').filter(|s| !s.is_empty()).map(|s| s.to_string()).collect()).unwrap_or_default();
        args.dump = Some((kind.to_string(), paths));
        return;
    }
    if let Some(val) = val {
        z_err(&format!(
            "unexpected value '{}' for '-Z{}' found; no more were expected\n\nUsage: solar -Z{}\n\nFor more information, try '-Zhelp'.\n",
            val, fname, fname
        ));
    }
    let already = match fname {
        "ui-testing" => std::mem::replace(&mut args.ui_testing, true),
        "track-diagnostics" => std::mem::replace(&mut args.track_diagnostics, true),
        "parse-yul" => std::mem::replace(&mut args.parse_yul, true),
        "no-resolve-imports" => std::mem::replace(&mut args.no_resolve_imports, true),
        "ast-stats" => std::mem::replace(&mut args.ast_stats, true),
        "span-visitor" => std::mem::replace(&mut args.span_visitor, true),
        "print-max-storage-sizes" => std::mem::replace(&mut args.print_max_storage_sizes, true),
        "typeck" => std::mem::replace(&mut args.typeck, true),
        "help" => {
            print!("{}", include_str!("text/zhelp.txt"));
            let _ = std::io::stdout().flush();
            std::process::exit(0);
        }
        _ => false,
    };
    if already {
        z_err(&format!(
            "the argument '-Z{}' cannot be used multiple times\n\nUsage: solar [OPTIONS]\n\nFor more information, try '-Zhelp'.\n",
            fname
        ));
    }
}
