            }
            let v = c.to_digit(radix)?;
            r = r.mul_small(radix).add(&BigUint::from_u64(v as u64));
            any = true;
        }
        if any {
            Some(r)
        } else {
            None
        }
    }
    pub fn to_string_radix(&self, radix: u32) -> String {
        if self.is_zero() {
            return "0".to_string();
        }
        let mut digits = vec![];
        let mut cur = self.clone();
        let rb = BigUint::from_u64(radix as u64);
        while !cur.is_zero() {
            let (q, r) = cur.divrem(&rb);
            digits.push(std::char::from_digit(r.to_u64().unwrap() as u32, radix).unwrap());
            cur = q;
        }
        digits.iter().rev().collect()
    }
    pub fn bitand(&self, o: &BigUint) -> BigUint {
        let n = self.d.len().min(o.d.len());
        let mut b = BigUint { d: (0..n).map(|i| self.d[i] & o.d[i]).collect() };
        b.trim();
        b
    }
    pub fn bitor(&self, o: &BigUint) -> BigUint {
        let n = self.d.len().max(o.d.len());
        let mut b = BigUint { d: (0..n).map(|i| self.d.get(i).unwrap_or(&0) | o.d.get(i).unwrap_or(&0)).collect() };
        b.trim();
        b
    }
    pub fn bitxor(&self, o: &BigUint) -> BigUint {
        let n = self.d.len().max(o.d.len());
        let mut b = BigUint { d: (0..n).map(|i| self.d.get(i).unwrap_or(&0) ^ o.d.get(i).unwrap_or(&0)).collect() };
        b.trim();
        b
    }
    pub fn to_bytes_be(&self, len: usize) -> Vec<u8> {
        let mut out = vec![0u8; len];
        for i in 0..len {
            let limb = i / 4;
            let shift = (i % 4) * 8;
            let byte = (*self.d.get(limb).unwrap_or(&0) >> shift) as u8;
            out[len - 1 - i] = byte;
        }
        out
    }
    pub fn gcd(&self, o: &BigUint) -> BigUint {
        let mut a = self.clone();
        let mut b = o.clone();
        while !b.is_zero() {
            let (_, r) = a.divrem(&b);
            a = b;
            b = r;
        }
        a
    }
}

impl PartialOrd for BigUint {
    fn partial_cmp(&self, o: &Self) -> Option<Ordering> {
        Some(self.cmp(o))
    }
}
impl Ord for BigUint {
    fn cmp(&self, o: &Self) -> Ordering {
        if self.d.len() != o.d.len() {
            return self.d.len().cmp(&o.d.len());
        }
        for i in (0..self.d.len()).rev() {
            if self.d[i] != o.d[i] {
                return self.d[i].cmp(&o.d[i]);
            }
        }
        Ordering::Equal
    }
}

#[derive(Clone, Debug, PartialEq, Eq, Default)]
pub struct BigInt {
    pub neg: bool,
    pub mag: BigUint,
}

impl BigInt {
    pub fn zero() -> Self {
        BigInt { neg: false, mag: BigUint::zero() }
    }
    pub fn from_u(mag: BigUint) -> Self {
        BigInt { neg: false, mag }
    }
    pub fn from_i64(v: i64) -> Self {
        BigInt { neg: v < 0, mag: BigUint::from_u64(v.unsigned_abs()) }.norm()
    }
    fn norm(mut self) -> Self {
        if self.mag.is_zero() {
            self.neg = false;
        }
        self
    }
    pub fn is_zero(&self) -> bool {
        self.mag.is_zero()
    }
    pub fn is_neg(&self) -> bool {
        self.neg && !self.mag.is_zero()
    }
    pub fn neg(&self) -> BigInt {
        BigInt { neg: !self.neg, mag: self.mag.clone() }.norm()
    }
    pub fn add(&self, o: &BigInt) -> BigInt {
        if self.neg == o.neg {
            BigInt { neg: self.neg, mag: self.mag.add(&o.mag) }.norm()
        } else if self.mag >= o.mag {
            BigInt { neg: self.neg, mag: self.mag.sub(&o.mag) }.norm()
        } else {
            BigInt { neg: o.neg, mag: o.mag.sub(&self.mag) }.norm()
        }
    }
    pub fn sub(&self, o: &BigInt) -> BigInt {
        self.add(&o.neg())
    }
    pub fn mul(&self, o: &BigInt) -> BigInt {
        BigInt { neg: self.neg != o.neg, mag: self.mag.mul(&o.mag) }.norm()
    }
    /// Truncating division
    pub fn div(&self, o: &BigInt) -> Option<BigInt> {
        if o.is_zero() {
            return None;
        }
        let (q, _) = self.mag.divrem(&o.mag);
        Some(BigInt { neg: self.neg != o.neg, mag: q }.norm())
    }
    pub fn rem(&self, o: &BigInt) -> Option<BigInt> {
        if o.is_zero() {
            return None;
        }
        let (_, r) = self.mag.divrem(&o.mag);
        Some(BigInt { neg: self.neg, mag: r }.norm())
    }
    pub fn to_string(&self) -> String {
        let s = self.mag.to_string_radix(10);
        if self.is_neg() {
            format!("-{s}")
        } else {
            s
        }
    }
    pub fn bits(&self) -> u64 {
        self.mag.bits()
    }
}

impl PartialOrd for BigInt {
    fn partial_cmp(&self, o: &Self) -> Option<Ordering> {
        Some(self.cmp(o))
    }
}
impl Ord for BigInt {
    fn cmp(&self, o: &Self) -> Ordering {
        match (self.is_neg(), o.is_neg()) {
            (false, true) => Ordering::Greater,
            (true, false) => Ordering::Less,
            (false, false) => self.mag.cmp(&o.mag),
            (true, true) => o.mag.cmp(&self.mag),
        }
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct BigRational {
    pub num: BigInt,
    pub den: BigUint,
}

impl BigRational {
    pub fn new(num: BigInt, den: BigUint) -> Self {
        let g = num.mag.gcd(&den);
        if g.is_zero() || g == BigUint::one() {
            return BigRational { num, den };
        }
        let (n, _) = num.mag.divrem(&g);
        let (d, _) = den.divrem(&g);
        BigRational { num: BigInt { neg: num.neg, mag: n }.norm(), den: d }
    }
    pub fn is_integer(&self) -> bool {
        self.den == BigUint::one()
    }
}
