pub const CLOSE_BRACE: TokenKind = TokenKind::CloseDelim(Delim::Brace);
pub const OPEN_BRACKET: TokenKind = TokenKind::OpenDelim(Delim::Bracket);
pub const CLOSE_BRACKET: TokenKind = TokenKind::CloseDelim(Delim::Bracket);

impl<'a> Parser<'a> {
    pub fn new(dcx: &'a DiagCtxt, sm: &'a SourceMap, tokens: Vec<Token>, file_start: u32) -> Self {
        let dummy = Token::new(TokenKind::Eof, Span::DUMMY);
        let mut p = Parser {
            dcx,
            sm,
            tokens,
            pos: 0,
            token: dummy,
            prev_token: dummy,
            expected: vec![],
            pending_docs: vec![],
            in_yul: false,
            file_start,
        };
        p.advance_raw();
        p
    }

    fn advance_raw(&mut self) {
        loop {
            let t = if self.pos < self.tokens.len() { self.tokens[self.pos] } else { *self.tokens.last().unwrap() };
            if self.pos < self.tokens.len() {
                self.pos += 1;
            }
            if let TokenKind::Comment(_, kind, sym) = t.kind {
                let dc = DocComment { is_block: kind == CommentKind::Block, span: t.span, symbol: sym };
                crate::natspec::check_doc_comment(self.dcx, &dc);
                self.pending_docs.push(dc);
                continue;
            }
            self.token = t;
            break;
        }
    }

    pub fn bump(&mut self) {
        self.prev_token = self.token;
        self.advance_raw();
        self.expected.clear();
    }

    pub fn take_docs(&mut self) -> Vec<DocComment> {
        std::mem::take(&mut self.pending_docs)
    }

    pub fn look_ahead(&self, n: usize) -> Token {
        if n == 0 {
            return self.token;
        }
        let mut i = self.pos;
        let mut count = 0;
        let mut last = self.token;
        while i < self.tokens.len() {
            let t = self.tokens[i];
            i += 1;
            if matches!(t.kind, TokenKind::Comment(..)) {
                continue;
            }
            count += 1;
            last = t;
            if count == n {
                return t;
            }
        }
        if last.kind == TokenKind::Eof {
            last
        } else {
            *self.tokens.last().unwrap()
        }
    }

    pub fn check(&mut self, k: TokenKind) -> bool {
        let present = self.token.kind == k;
        if !present {
            self.expected.push(Expected::Token(k));
        }
        present
    }
    pub fn eat(&mut self, k: TokenKind) -> bool {
        let p = self.check(k);
        if p {
            self.bump();
        }
        p
    }
    pub fn check_keyword(&mut self, k: Symbol) -> bool {
        let present = self.token.is_keyword(k);
        if !present {
            self.expected.push(Expected::Keyword(k));
        }
        present
    }
    pub fn eat_keyword(&mut self, k: Symbol) -> bool {
        let p = self.check_keyword(k);
        if p {
            self.bump();
        }
        p
    }
    pub fn check_ident(&mut self) -> bool {
        let p = self.token.is_non_reserved_ident(self.in_yul);
        if !p {
            self.expected.push(Expected::Ident);
        }
        p
    }
    pub fn check_lit(&mut self) -> bool {
        let p = self.token.is_lit();
        if !p {
            self.expected.push(Expected::Lit);
        }
        p
    }
    pub fn check_str_lit(&mut self) -> bool {
        let p = self.token.is_str_lit();
        if !p {
            self.expected.push(Expected::StrLit);
        }
        p
    }
    pub fn check_plain_str_lit(&mut self) -> bool {
        let p = matches!(self.token.kind, TokenKind::Literal(LitKind::Str, _));
        if !p {
            self.expected.push(Expected::StrLit);
        }
        p
    }
    pub fn check_elementary_type(&mut self) -> bool {
        let p = self.token.is_elementary_type();
        if !p {
            self.expected.push(Expected::ElementaryType);
        }
        p
    }
    pub fn check_path(&mut self) -> bool {
        let p = self.token.is_non_reserved_ident(self.in_yul);
        if !p {
            self.expected.push(Expected::Path);
        }
        p
    }
    pub fn push_expected(&mut self, e: Expected) {
        self.expected.push(e);
    }

    pub fn expect(&mut self, k: TokenKind) -> PResult<()> {
        if self.token.kind == k {
            self.bump();
            Ok(())
        } else {
            Err(self.expected_one_of_not_found(&[Expected::Token(k)], &[]))
        }
    }
    pub fn expect_keyword(&mut self, k: Symbol) -> PResult<()> {
        if self.token.is_keyword(k) {
            self.bump();
            Ok(())
        } else {
            Err(self.expected_one_of_not_found(&[Expected::Keyword(k)], &[]))
        }
    }
    pub fn expect_semi(&mut self) -> PResult<()> {
        self.expect(TokenKind::Semi)
    }

    /// Error span for the current token: previous token span at EOF.
    pub fn token_err_span(&self) -> Span {
        if self.token.is_eof() {
            self.prev_token.span
        } else {
            self.token.span
        }
    }

    pub fn unexpected(&mut self) -> Diag {
        self.expected_one_of_not_found(&[], &[])
    }

    pub fn expected_one_of_not_found(&mut self, edible: &[Expected], inedible: &[Expected]) -> Diag {
        let cur = self.token;
        let mut expected: Vec<Expected> = edible.iter().chain(inedible.iter()).cloned().chain(self.expected.iter().cloned()).collect();
        expected.retain(|e| match e {
            Expected::Token(k) => *k != cur.kind,
            Expected::Keyword(k) => !cur.is_keyword(*k),
            _ => true,
        });
        let mut keyed: Vec<(String, Expected)> = expected.into_iter().map(|e| (e.to_str(), e)).collect();
        keyed.sort_by(|a, b| a.0.cmp(&b.0));
        keyed.dedup_by(|a, b| a.0 == b.0);
        let strs: Vec<String> = keyed.into_iter().map(|(s, _)| s).collect();
        let actual = cur.full_description();
        let list = tokens_to_string(&strs);
        let (msg, label) = if strs.len() > 1 {
            let short = if strs.len() > 6 { format!("{} possible tokens", strs.len()) } else { list.clone() };
            (format!("expected one of {list}, found {actual}"), format!("expected one of {short}"))
        } else if strs.is_empty() {
            (format!("unexpected token: {actual}"), "unexpected token after this".to_string())
        } else {
            (format!("expected {list}, found {actual}"), format!("expected {list}"))
        };
        let is_eof = cur.is_eof();
        let primary = if is_eof { self.prev_token.span } else { cur.span };
        let mut d = Diag::new(Level::Error, msg).span(primary);
        if strs.is_empty() {
            d = d.span_label(self.prev_token.span, label);
            return d;
        }
        let gap = Span::new(self.prev_token.span.hi, cur.span.lo);
        if !self.sm.is_multiline(gap) {
            d = d.span_label(primary, label);
        } else {
            let sp = if is_eof { self.prev_token.span } else { self.prev_token.span.shrink_to_hi() };
            d = d.span_label(sp, label);
            d = d.span_label(cur.span, "unexpected token");
        }
        d
    }

    pub fn parse_ident(&mut self) -> PResult<Ident> {
        self.parse_ident_common(true)
    }

    pub fn parse_ident_common(&mut self, recover: bool) -> PResult<Ident> {
        let _ = recover;
        if self.token.is_non_reserved_ident(self.in_yul) {
            let name = self.token.ident().unwrap();
            let span = self.token.span;
            self.bump();
            return Ok(Ident { name, span });
        }
        Err(self.expected_ident_found())
    }

    pub fn expected_ident_found(&mut self) -> Diag {
        let msg = format!("expected identifier, found {}", self.token.full_description());
        Diag::new(Level::Error, msg).span(self.token_err_span())
    }

    pub fn parse_ident_opt(&mut self) -> Option<Ident> {
        if self.check_ident() {
            let name = self.token.ident().unwrap();
            let span = self.token.span;
            self.bump();
            Some(Ident { name, span })
        } else {
            None
        }
    }

    /// Emits a non-fatal error.
    pub fn soft_err(&self, sp: Span, msg: impl Into<String>) {
        self.dcx.emit(Diag::new(Level::Error, msg).span(sp));
    }

    /// rustc-style comma separated sequence parse; returns elements. Trailing separator handling
    /// mirrors solar: errors on trailing separators when not allowed.
    pub fn parse_seq<T>(
        &mut self,
        close: TokenKind,
        sep: TokenKind,
        allow_trailing: bool,
        mut f: impl FnMut(&mut Self) -> PResult<T>,
    ) -> PResult<Vec<T>> {
        let mut v = vec![];
        let mut first = true;
        loop {
            if self.check(close) {
                break;
            }
            if self.token.is_eof() {
                break;
            }
            if let TokenKind::CloseDelim(_) = self.token.kind {
                if !first {
                    // fallthrough to separator expectation
                } else {
                    break;
                }
            }
            if !first {
                if self.token.kind == sep {
                    self.bump();
                } else {
                    return Err(self.expected_one_of_not_found(&[Expected::Token(sep)], &[]));
                }
                if self.check(close) {
                    if !allow_trailing {
                        let sp = self.prev_token.span;
                        return Err(Diag::new(Level::Error, format!("trailing `{}` separator is not allowed", token_kind_str(&sep))).span(sp));
                    }
                    break;
                }
            }
            first = false;
            v.push(f(self)?);
        }
        Ok(v)
    }

    /// Parses `open seq close`.
    pub fn parse_delim_seq<T>(
        &mut self,
        delim: Delim,
        allow_trailing: bool,
        f: impl FnMut(&mut Self) -> PResult<T>,
    ) -> PResult<Vec<T>> {
        self.expect(TokenKind::OpenDelim(delim))?;
        let v = self.parse_seq(TokenKind::CloseDelim(delim), TokenKind::Comma, allow_trailing, f)?;
        self.eat(TokenKind::CloseDelim(delim));
        Ok(v)
    }
}

pub fn tokens_to_string(strs: &[String]) -> String {
    let n = strs.len();
    let mut s = String::new();
    for (i, t) in strs.iter().enumerate() {
        if i > 0 {
            if n == 2 {
                s.push_str(" or ");
            } else if i == n - 1 {
                s.push_str(", or ");
            } else {
                s.push_str(", ");
            }
        }
        s.push_str(t);
    }
    s
}

pub fn parse_file(dcx: &DiagCtxt, sm: &SourceMap, src: &str, start_pos: u32) -> Option<SourceUnit> {
    let tokens = crate::lexer::Lexer::new(src, start_pos, dcx).tokenize();
    let mut p = Parser::new(dcx, sm, tokens, start_pos);
    match p.parse_source_unit() {
        Ok(su) => Some(su),
        Err(d) => {
            dcx.emit(d);
            None
        }
    }
}

pub fn is_kw(t: &Token, k: Symbol) -> bool {
    t.is_keyword(k)
}

