impl<'a> Parser<'a> {
    pub fn parse_source_unit(&mut self) -> PResult<SourceUnit> {
        let mut items = vec![];
        loop {
            if self.token.is_eof() {
                break;
            }
            match self.parse_item(false)? {
                Some(item) => items.push(item),
                None => {
                    let msg = format!(
                        "expected global item (pragma, import directive, contract, interface, library, struct, enum, constant, function, modifier, or error definition), found {}",
                        self.token.full_description()
                    );
                    return Err(Diag::new(Level::Error, msg).span(self.token_err_span()).note(
                        "for a full list of valid global items, see <https://docs.soliditylang.org/en/latest/grammar.html#a4.SolidityParser.sourceUnit>",
                    ));
                }
            }
        }
        Ok(SourceUnit { items })
    }

    fn parse_contract_body(&mut self) -> PResult<Vec<Item>> {
        let mut items = vec![];
        loop {
            if self.eat(CLOSE_BRACE) {
                break;
            }
            match self.parse_item(true)? {
                Some(item) => items.push(item),
                None => {
                    let msg = format!(
                        "expected contract item (function, variable, struct, or modifier definition), found {}",
                        self.token.full_description()
                    );
                    return Err(Diag::new(Level::Error, msg).span(self.token_err_span()).note(
                        "for a full list of valid contract items, see <https://docs.soliditylang.org/en/latest/grammar.html#a4.SolidityParser.contractBodyElement>",
                    ));
                }
            }
        }
        Ok(items)
    }

    pub fn parse_item(&mut self, in_contract: bool) -> PResult<Option<Item>> {
        let docs = self.take_docs();
        let lo = self.token.span;
        let t = self.token;
        let kind = if t.is_keyword(kw::Function) && !matches!(self.look_ahead(1).kind, TokenKind::OpenDelim(Delim::Paren)) {
            self.parse_function(FunctionKind::Function, in_contract)?
        } else if t.is_keyword(kw::Function) && !in_contract {
            self.parse_function(FunctionKind::Function, in_contract)?
        } else if t.is_keyword(kw::Constructor) || t.is_keyword(kw::Fallback) || t.is_keyword(kw::Receive) || t.is_keyword(kw::Modifier) {
            let k = if t.is_keyword(kw::Constructor) {
                FunctionKind::Constructor
            } else if t.is_keyword(kw::Fallback) {
                FunctionKind::Fallback
            } else if t.is_keyword(kw::Receive) {
                FunctionKind::Receive
            } else {
                FunctionKind::Modifier
            };
            self.parse_function(k, in_contract)?
        } else if t.is_keyword(kw::Struct) {
            self.bump();
            self.parse_struct()?
        } else if t.is_keyword(kw::Event) {
            self.bump();
            self.parse_event()?
        } else if t.is_keyword(kw::Error) && self.look_ahead(1).is_non_reserved_ident(false) && self.look_ahead(2).kind == OPEN_PAREN {
            self.bump();
            self.parse_error_def()?
        } else if t.is_keyword(kw::Enum) {
            self.bump();
            self.parse_enum()?
        } else if t.is_keyword(kw::Type) {
            self.bump();
            self.parse_udvt()?
        } else if t.is_keyword(kw::Using) {
            self.bump();
            self.parse_using()?
        } else if t.is_keyword(kw::Pragma) {
            self.bump();
            let it = self.parse_pragma()?;
            if in_contract {
                self.soft_err(lo.to(self.prev_token.span), "pragma directives are not allowed in contracts");
            }
            it
        } else if t.is_keyword(kw::Import) {
            self.bump();
            let it = self.parse_import()?;
            if in_contract {
                self.soft_err(lo.to(self.prev_token.span), "import directives are not allowed in contracts");
            }
            it
        } else if t.is_keyword(kw::Abstract) || t.is_keyword(kw::Contract) || t.is_keyword(kw::Interface) || t.is_keyword(kw::Library) {
            let it = self.parse_contract()?;
            if in_contract {
                let msg = match &it {
                    ItemKind::Contract(c) => format!("{} definitions are not allowed in contracts", match c.kind {
                        ContractKind::Contract | ContractKind::AbstractContract => "contract",
                        ContractKind::Interface => "interface",
                        ContractKind::Library => "library",
                    }),
                    _ => unreachable!(),
                };
                self.soft_err(lo.to(self.prev_token.span), msg);
            }
            it
        } else if self.is_variable_start() {
            let flags = if in_contract { VarFlags::state_var() } else { VarFlags::global_var() };
            let v = self.parse_var_decl_with(flags, true)?;
            if !in_contract {
                let is_const = matches!(v.mutability, Some((VarMut::Constant, _)));
                if !is_const {
                    self.soft_err(v.span, "only constant variables are allowed at file level");
                }
            }
            if matches!(v.mutability, Some((VarMut::Constant, _))) && v.initializer.is_none() {
                self.soft_err(v.span, "constant variable must be initialized");
            }
            ItemKind::Variable(v)
        } else {
            return Ok(None);
        };
        let span = lo.to(self.prev_token.span);
        Ok(Some(Item { docs, span, kind }))
    }

    fn is_variable_start(&self) -> bool {
        let t = self.token;
        if t.is_keyword(kw::Mapping) || t.is_keyword(kw::Function) {
            return true;
        }
        if t.is_elementary_type() {
            return true;
        }
        t.is_non_reserved_ident(false)
    }

    // ---- pragma ----
    fn parse_pragma(&mut self) -> PResult<ItemKind> {
        let lo = self.prev_token.span;
        let tokens = self.parse_pragma_tokens()?;
        let _ = lo;
        Ok(ItemKind::Pragma(Pragma { tokens, span: lo.to(self.prev_token.span) }))
    }

    fn parse_pragma_tokens(&mut self) -> PResult<PragmaTokens> {
        if self.token.kind == TokenKind::Semi {
            let sp = self.token.span;
            return Err(Diag::new(Level::Error, "expected at least one token in pragma directive").span(sp));
        }
        let is_ident_or_str = |t: &Token| matches!(t.kind, TokenKind::Ident(_)) || t.is_str_lit();
        if self.token.is_keyword(kw::Solidity) {
            let name_tok = self.token;
            self.bump();
            let name = Ident { name: kw::Solidity, span: name_tok.span };
            let req = self.parse_semver_req()?;
            self.expect_semi()?;
            return Ok(PragmaTokens::Version(name, req));
        }
        if is_ident_or_str(&self.token) {
            let first = self.token;
            let next = self.look_ahead(1);
            let starts_version = matches!(
                next.kind,
                TokenKind::BinOp(BinOpToken::Caret)
                    | TokenKind::Tilde
                    | TokenKind::Eq
                    | TokenKind::Lt
                    | TokenKind::Le
                    | TokenKind::Gt
                    | TokenKind::Ge
                    | TokenKind::Dot
                    | TokenKind::Literal(LitKind::Integer | LitKind::Rational, _)
            );
            if starts_version {
                self.bump();
                let name = Ident { name: first.ident().unwrap_or(kw::Empty), span: first.span };
                let req = self.parse_semver_req()?;
                self.expect_semi()?;
                return Ok(PragmaTokens::Version(name, req));
            }
            if next.kind == TokenKind::Semi || next.kind == TokenKind::Eof {
                self.bump();
                self.expect_semi()?;
                return Ok(PragmaTokens::Custom(tok_text(&first), None));
            }
            if is_ident_or_str(&next) && self.look_ahead(2).kind == TokenKind::Semi {
                self.bump();
                let v = self.token;
                self.bump();
                self.expect_semi()?;
                return Ok(PragmaTokens::Custom(tok_text(&first), Some(tok_text(&v))));
            }
        }
        let mut toks = vec![];
        while self.token.kind != TokenKind::Semi && !self.token.is_eof() {
            toks.push(tok_text(&self.token));
            self.bump();
        }
        self.expect_semi()?;
        Ok(PragmaTokens::Verbatim(toks))
    }

    // ---- import ----
    fn parse_import(&mut self) -> PResult<ItemKind> {
        if self.check_str_lit() {
            let (path, sp) = self.parse_import_path()?;
            let alias = if self.eat_keyword(kw::As) { Some(self.parse_ident()?) } else { None };
            self.expect_semi()?;
            return Ok(ItemKind::Import(Import { path, path_span: sp, items: ImportItems::Plain(alias) }));
        }
        if self.check(TokenKind::BinOp(BinOpToken::Star)) {
            self.bump();
            self.expect_keyword(kw::As)?;
            let alias = self.parse_ident()?;
            self.expect_keyword(kw::From)?;
            let (path, sp) = self.parse_import_path_required()?;
            self.expect_semi()?;
            return Ok(ItemKind::Import(Import { path, path_span: sp, items: ImportItems::Glob(alias) }));
        }
        if self.check(OPEN_BRACE) {
            self.bump();
            let list = self.parse_seq(CLOSE_BRACE, TokenKind::Comma, false, |p| {
                let name = p.parse_ident()?;
                let alias = if p.eat_keyword(kw::As) { Some(p.parse_ident()?) } else { None };
                Ok((name, alias))
            })?;
            self.eat(CLOSE_BRACE);
            self.expect_keyword(kw::From)?;
            let (path, sp) = self.parse_import_path_required()?;
            self.expect_semi()?;
            return Ok(ItemKind::Import(Import { path, path_span: sp, items: ImportItems::Aliases(list) }));
        }
        Err(self.unexpected())
    }

    fn parse_import_path_required(&mut self) -> PResult<(Symbol, Span)> {
        if self.check_str_lit() {
            self.parse_import_path()
        } else {
            Err(self.unexpected())
        }
    }

    fn parse_import_path(&mut self) -> PResult<(Symbol, Span)> {
        let lit = self.parse_lit()?;
        let s = match &lit.kind {
            LitKind::Str(_, bytes) => String::from_utf8_lossy(bytes).into_owned(),
            _ => String::new(),
        };
        if s.is_empty() {
            self.soft_err(lit.span, "import path cannot be empty");
        }
        Ok((Symbol::intern(&s), lit.span))
    }

    // ---- using ----
    fn parse_using(&mut self) -> PResult<ItemKind> {
        let list = if self.eat(OPEN_BRACE) {
            let v = self.parse_seq(CLOSE_BRACE, TokenKind::Comma, false, |p| {
                let path = p.parse_path()?;
                let op = if p.eat_keyword(kw::As) {
                    use TokenKind::*;
                    let ops: [TokenKind; 15] = [
                        BinOp(BinOpToken::And),
                        BinOp(BinOpToken::Or),
                        BinOp(BinOpToken::Caret),
                        Tilde,
                        BinOp(BinOpToken::Plus),
                        BinOp(BinOpToken::Minus),
                        BinOp(BinOpToken::Star),
                        BinOp(BinOpToken::Slash),
                        BinOp(BinOpToken::Percent),
                        EqEq,
                        Ne,
                        Lt,
                        Gt,
                        Le,
                        Ge,
                    ];
                    let mut found = None;
                    for op in ops {
                        if p.check(op) {
                            found = Some(op);
                            break;
                        }
                    }
                    match found {
                        Some(op) => {
                            let sp = p.token.span;
                            p.bump();
                            Some((Symbol::intern(&token_kind_str(&op)), sp))
                        }
                        None => {
                            for op in ops {
                                p.check(op);
                            }
                            return Err(p.unexpected());
                        }
                    }
                } else {
                    None
                };
                Ok((path, op))
            })?;
            self.eat(CLOSE_BRACE);
            UsingList::Multiple(v)
        } else {
            UsingList::Single(self.parse_path()?)
        };
        self.expect_keyword(kw::For)?;
        let ty = if self.check(TokenKind::BinOp(BinOpToken::Star)) {
            self.bump();
            None
        } else {
            Some(self.parse_type()?)
        };
        let global = self.eat_keyword(kw::Global);
        self.expect_semi()?;
        Ok(ItemKind::Using(Using { list, ty, global }))
    }

    // ---- contract ----
    fn parse_contract(&mut self) -> PResult<ItemKind> {
        let kind = if self.token.is_keyword(kw::Abstract) {
            self.bump();
            self.expect_keyword(kw::Contract)?;
            ContractKind::AbstractContract
        } else if self.token.is_keyword(kw::Contract) {
            self.bump();
            ContractKind::Contract
        } else if self.token.is_keyword(kw::Interface) {
            self.bump();
            ContractKind::Interface
        } else {
            self.bump();
            ContractKind::Library
        };
        let name = self.parse_ident()?;
        let mut bases: Vec<Modifier> = vec![];
        let mut bases_set = false;
        let mut layout = None;
        loop {
            if self.eat_keyword(kw::Is) {
                let is_span = self.prev_token.span;
                let mut list = vec![];
                loop {
                    let lo = self.token.span;
                    let path = self.parse_path()?;
                    let args = if self.token.kind == OPEN_PAREN { Some(self.parse_call_args()?) } else { None };
                    list.push(Modifier { name: path, args, span: lo.to(self.prev_token.span) });
                    if !self.eat(TokenKind::Comma) {
                        break;
                    }
                }
                if bases_set {
                    let sp = is_span.to(self.prev_token.span);
                    self.soft_err(sp, "base contracts already specified");
                } else {
                    bases = list;
                    bases_set = true;
                }
            } else if self.check_keyword(kw::Layout) {
                let lo = self.token.span;
                self.bump();
                self.expect_keyword(kw::At)?;
                let e = self.parse_expr()?;
                if layout.is_some() {
                    self.soft_err(lo.to(self.prev_token.span), "storage layout already specified");
                } else {
                    layout = Some(e);
                }
            } else {
                break;
            }
        }
        self.expect(OPEN_BRACE)?;
        let body = self.parse_contract_body()?;
        Ok(ItemKind::Contract(Contract { kind, name, layout, bases, body }))
    }

    // ---- struct / enum / udvt / error / event ----
    fn parse_struct(&mut self) -> PResult<ItemKind> {
        let name = self.parse_ident()?;
        self.expect(OPEN_BRACE)?;
        let mut fields = vec![];
        loop {
            if self.check(CLOSE_BRACE) {
                self.bump();
                break;
            }
            if self.token.is_eof() {
                break;
            }
            let f = self.parse_var_decl_with(VarFlags::struct_field(), false)?;
            fields.push(f);
            if !self.eat(TokenKind::Semi) {
                self.check(CLOSE_BRACE);
                return Err(self.expected_one_of_not_found(&[], &[]));
            }
        }
        Ok(ItemKind::Struct(Struct { name, fields }))
    }

    fn parse_enum(&mut self) -> PResult<ItemKind> {
        let name = self.parse_ident()?;
        let variants = self.parse_delim_seq(Delim::Brace, false, |p| p.parse_ident())?;
        Ok(ItemKind::Enum(Enum { name, variants }))
    }

    fn parse_udvt(&mut self) -> PResult<ItemKind> {
        let name = self.parse_ident()?;
        self.expect_keyword(kw::Is)?;
        let ty = self.parse_type()?;
        self.expect_semi()?;
        Ok(ItemKind::Udvt(Udvt { name, ty }))
    }

    fn parse_error_def(&mut self) -> PResult<ItemKind> {
        let name = self.parse_ident()?;
        let params = self.parse_param_list(VarFlags::error_param())?;
        self.expect_semi()?;
        Ok(ItemKind::Error(ErrorDef { name, params }))
    }

    fn parse_event(&mut self) -> PResult<ItemKind> {
        let name = self.parse_ident()?;
        let params = self.parse_param_list(VarFlags::event_param())?;
        let anonymous = self.eat_keyword(kw::Anonymous);
        self.expect_semi()?;
        Ok(ItemKind::Event(Event { name, params, anonymous }))
    }

    pub fn parse_param_list(&mut self, flags: VarFlags) -> PResult<Vec<VarDecl>> {
        self.parse_delim_seq(Delim::Paren, false, |p| p.parse_var_decl_with(flags, false))
    }

    // ---- functions ----
    fn parse_function(&mut self, kind: FunctionKind, in_contract: bool) -> PResult<ItemKind> {
        let lo = self.token.span;
        self.bump();
        let flags = match kind {
            FunctionKind::Function => FnFlags { name: true, visibility: true, state_mutability: true, modifiers: true, virtual_: true, override_: true, returns: true, semi: true, body: true },
            FunctionKind::Constructor => FnFlags { name: false, visibility: true, state_mutability: true, modifiers: true, virtual_: false, override_: false, returns: false, semi: false, body: true },
            FunctionKind::Fallback => FnFlags { name: false, visibility: true, state_mutability: true, modifiers: true, virtual_: true, override_: true, returns: true, semi: true, body: true },
            FunctionKind::Receive => FnFlags { name: false, visibility: true, state_mutability: true, modifiers: true, virtual_: true, override_: true, returns: false, semi: true, body: true },
            FunctionKind::Modifier => FnFlags { name: true, visibility: false, state_mutability: false, modifiers: false, virtual_: true, override_: true, returns: false, semi: true, body: true },
        };
        let name = if flags.name {
            let n = if kind == FunctionKind::Function && (self.token.is_keyword(kw::Fallback) || self.token.is_keyword(kw::Receive)) {
                let sym = self.token.ident().unwrap();
                let sp = self.token.span;
                self.bump();
                self.dcx.emit(
                    Diag::new(Level::Warning, format!("function named `{}`", sym))
                        .code("3445")
                        .span(sp)
                        .help(format!("remove the `function` keyword if you intend this to be a {} function", sym)),
                );
                Ident { name: sym, span: sp }
            } else {
                self.parse_ident()?
            };
            Some(n)
        } else {
            None
        };
        let mut header = self.parse_function_header_rest(flags, kind == FunctionKind::Modifier)?;
        header.name = name;
        header.span = lo.to(self.prev_token.span);
        let body_lo = self.token.span;
        let body = if kind == FunctionKind::Constructor {
            Some(self.parse_block()?)
        } else if self.check(TokenKind::Semi) {
            self.bump();
            None
        } else if self.check(OPEN_BRACE) {
            Some(self.parse_block()?)
        } else {
            return Err(self.unexpected());
        };
        let body_span = body_lo.to(self.prev_token.span);
        if !in_contract {
            match kind {
                FunctionKind::Function => {}
                k => {
                    let what = match k {
                        FunctionKind::Constructor => "constructors",
                        FunctionKind::Fallback => "fallbacks",
                        FunctionKind::Receive => "receives",
                        FunctionKind::Modifier => "modifiers",
                        _ => unreachable!(),
                    };
                    self.soft_err(lo.to(self.prev_token.span), format!("{what} are not allowed in the global scope"));
                }
            }
        }
        Ok(ItemKind::Function(Function { kind, header, body, name, body_span }))
    }

    /// Parses parameter list and attributes.
    pub fn parse_function_header_rest(&mut self, flags: FnFlags, is_modifier: bool) -> PResult<FunctionHeader> {
        let params_lo = self.token.span;
        let params = if is_modifier {
            if self.token.kind == OPEN_PAREN {
                self.parse_param_list(VarFlags::function_param())?
            } else {
                vec![]
            }
        } else {
            self.parse_param_list(VarFlags::function_param())?
        };
        let params_span = params_lo.to(self.prev_token.span);
        let mut h = FunctionHeader {
            span: Span::DUMMY,
            name: None,
            params,
            params_span,
            visibility: None,
            state_mutability: None,
            modifiers: vec![],
            virtual_: None,
            override_: None,
            returns: None,
            returns_span: Span::DUMMY,
        };
        loop {
            let sp = self.token.span;
            if let Some(vis) = self.parse_visibility() {
                if !flags.visibility {
                    self.soft_err(sp, "visibility is not allowed here");
                } else if h.visibility.is_some() {
                    self.soft_err(sp, "visibility already specified");
                } else {
                    h.visibility = Some((vis, sp));
                }
            } else if let Some(m) = self.parse_state_mutability() {
                if !flags.state_mutability {
                    self.soft_err(sp, "state mutability is not allowed here");
                } else if h.state_mutability.is_some() {
                    self.soft_err(sp, "state mutability already specified");
                } else {
                    h.state_mutability = Some((m, sp));
                }
            } else if self.eat_keyword(kw::Virtual) {
                if !flags.virtual_ {
                    self.soft_err(sp, "`virtual` is not allowed here");
                } else if h.virtual_.is_some() {
                    self.soft_err(sp, "virtual already specified");
                } else {
                    h.virtual_ = Some(sp);
                }
            } else if self.check_keyword(kw::Override) {
                let o = self.parse_override()?;
                if !flags.override_ {
                    self.soft_err(o.span, "`override` is not allowed here");
                } else if h.override_.is_some() {
                    self.soft_err(o.span, "override already specified");
                } else {
                    h.override_ = Some(o);
                }
            } else if flags.returns && self.check_keyword(kw::Returns) {
                let rlo = self.token.span;
                self.bump();
                let r = self.parse_param_list(VarFlags::function_param())?;
                if r.is_empty() {
                    // `returns ()`
                }
                h.returns_span = rlo.to(self.prev_token.span);
                h.returns = Some(r);
                break;
            } else if self.token.is_non_reserved_ident(false) && !self.token.is_keyword(kw::Returns) {
                let lo = self.token.span;
                let name = self.parse_path()?;
                let args = if self.token.kind == OPEN_PAREN { Some(self.parse_call_args()?) } else { None };
                let m = Modifier { name, args, span: lo.to(self.prev_token.span) };
                if !flags.modifiers {
                    self.soft_err(m.span, "modifiers are not allowed here");
                } else {
                    h.modifiers.push(m);
                }
            } else {
                break;
            }
        }
        Ok(h)
    }

    pub fn parse_visibility(&mut self) -> Option<Visibility> {
        let v = if self.check_keyword(kw::External) {
            Visibility::External
        } else if self.check_keyword(kw::Internal) {
            Visibility::Internal
        } else if self.check_keyword(kw::Private) {
            Visibility::Private
        } else if self.check_keyword(kw::Public) {
            Visibility::Public
        } else {
            return None;
        };
        self.bump();
        Some(v)
    }

    pub fn parse_state_mutability(&mut self) -> Option<StateMutability> {
        let m = if self.check_keyword(kw::Payable) {
            StateMutability::Payable
        } else if self.check_keyword(kw::Pure) {
            StateMutability::Pure
        } else if self.check_keyword(kw::View) {
            StateMutability::View
        } else {
            return None;
        };
        self.bump();
        Some(m)
    }

    fn parse_override(&mut self) -> PResult<Override> {
        let lo = self.token.span;
        self.bump();
        let mut paths = vec![];
        if self.token.kind == OPEN_PAREN {
            paths = self.parse_delim_seq(Delim::Paren, false, |p| p.parse_path())?;
        }
        Ok(Override { paths, span: lo.to(self.prev_token.span) })
    }

    // ---- variables ----
    pub fn parse_var_decl_with(&mut self, flags: VarFlags, is_item: bool) -> PResult<VarDecl> {
        let lo = self.token.span;
        let ty = self.parse_type()?;
        self.parse_var_decl_rest(ty, flags, is_item, lo)
    }

    pub fn parse_var_decl_rest(&mut self, ty: Type, flags: VarFlags, is_item: bool, lo: Span) -> PResult<VarDecl> {
        let mut v = VarDecl {
            span: Span::DUMMY,
            ty,
            visibility: None,
            mutability: None,
            data_location: None,
            override_: None,
            indexed: false,
            name: None,
            initializer: None,
        };
        loop {
            let sp = self.token.span;
            if let Some(dl) = self.parse_data_location(flags.transient) {
                if !flags.data_location {
                    self.soft_err(sp, "data locations are not allowed here");
                } else if v.data_location.is_some() {
                    self.soft_err(sp, "data location already specified");
                } else {
                    v.data_location = Some((dl, sp));
                }
            } else if let Some(vis) = self.parse_visibility() {
                if !flags.visibility {
                    self.soft_err(sp, "visibility is not allowed here");
                } else if v.visibility.is_some() {
                    self.soft_err(sp, "visibility already specified");
                } else {
                    v.visibility = Some((vis, sp));
                }
            } else if let Some(m) = self.parse_var_mutability() {
                if !flags.mutability {
                    self.soft_err(sp, "mutability is not allowed here");
                } else if v.mutability.is_some() {
                    self.soft_err(sp, "mutability already specified");
                } else {
                    v.mutability = Some((m, sp));
                }
            } else if self.eat_keyword(kw::Indexed) {
                if !flags.indexed {
                    self.soft_err(sp, "`indexed` is not allowed here");
                } else if v.indexed {
                    self.soft_err(sp, "`indexed` already specified");
                } else {
                    v.indexed = true;
                }
            } else if self.eat_keyword(kw::Virtual) {
                self.soft_err(sp, "`virtual` is not allowed here");
            } else if self.check_keyword(kw::Override) {
                let o = self.parse_override()?;
                if !flags.override_ {
                    self.soft_err(o.span, "`override` is not allowed here");
                } else if v.override_.is_some() {
                    self.soft_err(o.span, "override already specified");
                } else {
                    v.override_ = Some(o);
                }
            } else {
                break;
            }
        }
        if flags.name_required {
            if is_item && self.token.kind == OPEN_BRACE && matches!(v.ty.kind, TypeKind::Function(_)) {
                let sp = self.token.span;
                return Err(Diag::new(Level::Error, "expected a state variable declaration").span(sp).note(
                    "this style of fallback function has been removed; use the `fallback` or `receive` keywords instead",
                ));
            }
            v.name = Some(self.parse_ident()?);
        } else {
            v.name = self.parse_ident_opt();
        }
        if flags.initializer {
            if self.eat(TokenKind::Eq) {
                v.initializer = Some(self.parse_expr()?);
            }
        }
        if flags.semi {
            self.expect_semi()?;
        }
        v.span = lo.to(self.prev_token.span);
        Ok(v)
    }

    fn parse_data_location(&mut self, transient: bool) -> Option<DataLocation> {
        let d = if self.check_keyword(kw::Storage) {
            DataLocation::Storage
        } else if self.check_keyword(kw::Memory) {
            DataLocation::Memory
        } else if self.check_keyword(kw::Calldata) {
            DataLocation::Calldata
        } else if self.check_keyword(kw::Transient) {
            let _ = transient;
            // `transient` is contextual; only a data location if followed by something that is not `=`/`;`
            let next = self.look_ahead(1);
            if matches!(next.kind, TokenKind::Eq | TokenKind::Semi) {
                return None;
            }
            DataLocation::Transient
        } else {
            return None;
        };
        self.bump();
        Some(d)
    }

    fn parse_var_mutability(&mut self) -> Option<VarMut> {
        let m = if self.check_keyword(kw::Constant) {
            VarMut::Constant
        } else if self.check_keyword(kw::Immutable) {
            VarMut::Immutable
        } else {
            return None;
        };
        self.bump();
        Some(m)
    }
}

fn tok_text(t: &Token) -> String {
    match t.kind {
        TokenKind::Ident(s) => s.as_str().to_string(),
        TokenKind::Literal(_, s) => s.as_str().to_string(),
        k => token_kind_str(&k),
    }
}
EOF"}

