use super::*;
use super::item::FnFlags;

impl<'a> Parser<'a> {
    /// Parses a path: `a.b.c`.
    pub fn parse_path(&mut self) -> PResult<Path> {
        let first = self.parse_ident()?;
        let mut segments = vec![first];
        if self.token.kind != TokenKind::Dot {
            return Ok(Path { span: first.span, segments });
        }
        while self.eat(TokenKind::Dot) {
            segments.push(self.parse_ident()?);
        }
        let span = first.span.to(self.prev_token.span);
        Ok(Path { segments, span })
    }

    pub fn parse_type(&mut self) -> PResult<Type> {
        let ty = self.parse_basic_type()?;
        self.parse_array_type_suffix(ty)
    }

    pub fn parse_array_type_suffix(&mut self, mut ty: Type) -> PResult<Type> {
        while self.eat(OPEN_BRACKET) {
            let len = if self.check(CLOSE_BRACKET) { None } else { Some(Box::new(self.parse_expr()?)) };
            self.expect(CLOSE_BRACKET)?;
            let span = ty.span.to(self.prev_token.span);
            ty = Type { span, kind: TypeKind::Array(Box::new(ty), len) };
        }
        Ok(ty)
    }

    pub fn parse_basic_type(&mut self) -> PResult<Type> {
        let lo = self.token.span;
        if self.check_keyword(kw::Function) {
            self.bump();
            let flags = FnFlags { name: false, visibility: true, state_mutability: true, modifiers: false, virtual_: false, override_: false, returns: true, semi: false, body: false };
            let h = self.parse_function_type_header(flags)?;
            let span = lo.to(self.prev_token.span);
            return Ok(Type { span, kind: TypeKind::Function(Box::new(h)) });
        }
        if self.check_keyword(kw::Mapping) {
            self.bump();
            self.expect(OPEN_PAREN)?;
            let key = self.parse_type()?;
            let key_name = self.parse_ident_opt();
            self.expect(TokenKind::FatArrow)?;
            let value = self.parse_type()?;
            let value_name = self.parse_ident_opt();
            self.expect(CLOSE_PAREN)?;
            let span = lo.to(self.prev_token.span);
            return Ok(Type { span, kind: TypeKind::Mapping(Box::new(Mapping { key, key_name, value, value_name })) });
        }
        if self.check_elementary_type() {
            return self.parse_elementary_type();
        }
        if self.check_path() {
            let path = self.parse_path()?;
            return Ok(Type { span: path.span, kind: TypeKind::Custom(path) });
        }
        Err(self.unexpected())
    }

    /// Parses an elementary type (current token must be one), including `address payable`.
    pub fn parse_elementary_type(&mut self) -> PResult<Type> {
        let lo = self.token.span;
        let sym = self.token.ident().unwrap();
        let mut et = elementary_type_of(sym).unwrap();
        self.bump();
        let sp = self.token.span;
        if let Some(m) = self.parse_state_mutability() {
            if m == StateMutability::Payable && et == ElemTy::Address(false) {
                et = ElemTy::Address(true);
            } else {
                let _ = sp;
                self.soft_err(lo.to(sp), format!("`{}` cannot have state mutability", sym));
            }
        }
        Ok(Type { span: lo.to(self.prev_token.span), kind: TypeKind::Elementary(et) })
    }

    fn parse_function_type_header(&mut self, flags: FnFlags) -> PResult<FunctionHeader> {
        let params_lo = self.token.span;
        let params = self.parse_param_list(super::item::VarFlags::function_param())?;
        let params_span = params_lo.to(self.prev_token.span);
        let mut h = FunctionHeader {
            span: Span::DUMMY,
            name: None,
            params,
            params_span,
            visibility: None,
            state_mutability: None,
            modifiers: vec![],
            virtual_: None,
            override_: None,
            returns: None,
            returns_span: Span::DUMMY,
        };
        let _ = flags;
        loop {
            let sp = self.token.span;
            if let Some(vis) = self.parse_visibility() {
                if h.visibility.is_some() {
                    self.soft_err(sp, "visibility already specified");
                } else {
                    h.visibility = Some((vis, sp));
                }
            } else if let Some(m) = self.parse_state_mutability() {
                if h.state_mutability.is_some() {
                    self.soft_err(sp, "state mutability already specified");
                } else {
                    h.state_mutability = Some((m, sp));
                }
            } else if self.check_keyword(kw::Returns) {
                let rlo = self.token.span;
                self.bump();
                let r = self.parse_param_list(super::item::VarFlags::function_param())?;
                h.returns_span = rlo.to(self.prev_token.span);
                h.returns = Some(r);
                break;
            } else {
                break;
            }
        }
        Ok(h)
    }
}
