use super::*;
use crate::num::{BigInt, BigRational, BigUint};

fn binop_of(k: &TokenKind) -> Option<(BinOpKind, u8)> {
    use BinOpToken as B;
    use TokenKind::*;
    Some(match k {
        OrOr => (BinOpKind::Or, 4),
        AndAnd => (BinOpKind::And, 5),
        EqEq => (BinOpKind::Eq, 6),
        Ne => (BinOpKind::Ne, 6),
        Lt => (BinOpKind::Lt, 7),
        Gt => (BinOpKind::Gt, 7),
        Le => (BinOpKind::Le, 7),
        Ge => (BinOpKind::Ge, 7),
        BinOp(B::Or) => (BinOpKind::BitOr, 8),
        BinOp(B::Caret) => (BinOpKind::BitXor, 9),
        BinOp(B::And) => (BinOpKind::BitAnd, 10),
        BinOp(B::Shl) => (BinOpKind::Shl, 11),
        BinOp(B::Shr) => (BinOpKind::Shr, 11),
        BinOp(B::Sar) => (BinOpKind::Sar, 11),
        BinOp(B::Plus) => (BinOpKind::Add, 12),
        BinOp(B::Minus) => (BinOpKind::Sub, 12),
        BinOp(B::Star) => (BinOpKind::Mul, 13),
        BinOp(B::Slash) => (BinOpKind::Div, 13),
        BinOp(B::Percent) => (BinOpKind::Rem, 13),
        StarStar => (BinOpKind::Pow, 14),
        _ => return None,
    })
}

fn assign_op_of(k: &TokenKind) -> Option<Option<BinOpKind>> {
    use BinOpToken as B;
    use TokenKind::*;
    Some(match k {
        Eq => None,
        BinOpEq(b) => Some(match b {
            B::Plus => BinOpKind::Add,
            B::Minus => BinOpKind::Sub,
            B::Star => BinOpKind::Mul,
            B::Slash => BinOpKind::Div,
            B::Percent => BinOpKind::Rem,
            B::Caret => BinOpKind::BitXor,
            B::And => BinOpKind::BitAnd,
            B::Or => BinOpKind::BitOr,
            B::Shl => BinOpKind::Shl,
            B::Shr => BinOpKind::Shr,
            B::Sar => BinOpKind::Sar,
        }),
        _ => return None,
    })
}

pub fn subdenom_of(t: &Token) -> Option<SubDenom> {
    let s = t.ident()?;
    Some(match s {
        kw::Wei => SubDenom::Wei,
        kw::Gwei => SubDenom::Gwei,
        kw::Ether => SubDenom::Ether,
        kw::Seconds => SubDenom::Seconds,
        kw::Minutes => SubDenom::Minutes,
        kw::Hours => SubDenom::Hours,
        kw::Days => SubDenom::Days,
        kw::Weeks => SubDenom::Weeks,
        kw::Years => SubDenom::Years,
        _ => return None,
    })
}

impl<'a> Parser<'a> {
    pub fn parse_expr(&mut self) -> PResult<Expr> {
        let lhs = self.parse_binary_expr(4)?;
        self.parse_expr_rest(lhs)
    }

    /// Given a parsed unary/postfix expression, continues with binary, ternary, assignment.
    pub fn parse_expr_from_unary(&mut self, unary: Expr) -> PResult<Expr> {
        let lhs = self.parse_binary_expr_rest(unary, 4)?;
        self.parse_expr_rest(lhs)
    }

    fn parse_expr_rest(&mut self, lhs: Expr) -> PResult<Expr> {
        if self.eat(TokenKind::Question) {
            let then = self.parse_expr()?;
            self.expect(TokenKind::Colon)?;
            let els = self.parse_expr()?;
            let span = lhs.span.to(els.span);
            return Ok(Expr { span, kind: ExprKind::Ternary(Box::new(lhs), Box::new(then), Box::new(els)) });
        }
        if let Some(op) = assign_op_of(&self.token.kind) {
            self.bump();
            let rhs = self.parse_expr()?;
            let span = lhs.span.to(rhs.span);
            return Ok(Expr { span, kind: ExprKind::Assign(Box::new(lhs), op, Box::new(rhs)) });
        }
        Ok(lhs)
    }

    fn parse_binary_expr(&mut self, min_prec: u8) -> PResult<Expr> {
        let lhs = self.parse_unary_expr()?;
        self.parse_binary_expr_rest(lhs, min_prec)
    }

    fn parse_binary_expr_rest(&mut self, mut lhs: Expr, min_prec: u8) -> PResult<Expr> {
        loop {
            let Some((op, prec)) = binop_of(&self.token.kind) else { break };
            if prec < min_prec {
                break;
            }
            self.bump();
            let rhs = if op == BinOpKind::Pow {
                // right associative
                self.parse_binary_expr(prec)?
            } else {
                self.parse_binary_expr(prec + 1)?
            };
            let span = lhs.span.to(rhs.span);
            lhs = Expr { span, kind: ExprKind::Binary(Box::new(lhs), op, Box::new(rhs)) };
        }
        Ok(lhs)
    }

    pub fn parse_unary_expr(&mut self) -> PResult<Expr> {
        let lo = self.token.span;
        let op = match self.token.kind {
            TokenKind::Not => Some(UnOpKind::Not),
            TokenKind::Tilde => Some(UnOpKind::BitNot),
            TokenKind::BinOp(BinOpToken::Minus) => Some(UnOpKind::Neg),
            TokenKind::PlusPlus => Some(UnOpKind::PreInc),
            TokenKind::MinusMinus => Some(UnOpKind::PreDec),
            _ => None,
        };
        if let Some(op) = op {
            self.bump();
            let e = self.parse_unary_expr()?;
            let span = lo.to(e.span);
            return Ok(Expr { span, kind: ExprKind::Unary(op, Box::new(e)) });
        }
        if self.check(TokenKind::BinOp(BinOpToken::Plus)) {
            let sp = self.token.span;
            return Err(Diag::new(Level::Error, "unary plus is not supported").span(sp));
        }
        if self.eat_keyword(kw::Delete) {
            let e = self.parse_unary_expr()?;
            let span = lo.to(e.span);
            return Ok(Expr { span, kind: ExprKind::Delete(Box::new(e)) });
        }
        let prim = self.parse_primary_expr()?;
        let e = self.parse_postfix_expr(prim)?;
        self.parse_postfix_incdec(e)
    }

    pub fn parse_postfix_incdec(&mut self, e: Expr) -> PResult<Expr> {
        let op = match self.token.kind {
            TokenKind::PlusPlus => UnOpKind::PostInc,
            TokenKind::MinusMinus => UnOpKind::PostDec,
            _ => return Ok(e),
        };
        self.bump();
        let span = e.span.to(self.prev_token.span);
        Ok(Expr { span, kind: ExprKind::Unary(op, Box::new(e)) })
    }

    pub fn parse_postfix_expr(&mut self, mut e: Expr) -> PResult<Expr> {
        loop {
            if self.eat(TokenKind::Dot) {
                let name = self.parse_member_name()?;
                let span = e.span.to(name.span);
                e = Expr { span, kind: ExprKind::Member(Box::new(e), name) };
            } else if self.check(OPEN_PAREN) {
                let args = self.parse_call_args()?;
                let span = e.span.to(args.span);
                e = Expr { span, kind: ExprKind::Call(Box::new(e), args) };
            } else if self.eat(OPEN_BRACKET) {
                let kind = if self.check(CLOSE_BRACKET) {
                    IndexKind::Index(None)
                } else {
                    let start = if self.check(TokenKind::Colon) { None } else { Some(Box::new(self.parse_expr()?)) };
                    if self.eat(TokenKind::Colon) {
                        let end = if self.check(CLOSE_BRACKET) { None } else { Some(Box::new(self.parse_expr()?)) };
                        IndexKind::Range(start, end)
                    } else {
                        IndexKind::Index(start)
                    }
                };
                self.expect(CLOSE_BRACKET)?;
                let span = e.span.to(self.prev_token.span);
                e = Expr { span, kind: ExprKind::Index(Box::new(e), kind) };
            } else if self.check(OPEN_BRACE) {
                let next = self.look_ahead(1);
                let next2 = self.look_ahead(2);
                if !(next.is_non_reserved_ident(false) && next2.kind == TokenKind::Colon) {
                    break;
                }
                self.bump();
                let args = self.parse_seq(CLOSE_BRACE, TokenKind::Comma, false, |p| p.parse_named_arg())?;
                self.eat(CLOSE_BRACE);
                let span = e.span.to(self.prev_token.span);
                e = Expr { span, kind: ExprKind::CallOptions(Box::new(e), args) };
            } else {
                break;
            }
        }
        Ok(e)
    }

    fn parse_member_name(&mut self) -> PResult<Ident> {
        if let TokenKind::Ident(name) = self.token.kind {
            let span = self.token.span;
            self.bump();
            return Ok(Ident { name, span });
        }
        Err(self.expected_ident_found())
    }

    fn parse_named_arg(&mut self) -> PResult<NamedArg> {
        let name = self.parse_ident()?;
        self.expect(TokenKind::Colon)?;
        let value = self.parse_expr()?;
        Ok(NamedArg { name, value })
    }

    pub fn parse_call_args(&mut self) -> PResult<CallArgs> {
        let lo = self.token.span;
        self.expect(OPEN_PAREN)?;
        if self.check(OPEN_BRACE) {
            self.bump();
            let args = self.parse_seq(CLOSE_BRACE, TokenKind::Comma, false, |p| p.parse_named_arg())?;
            self.eat(CLOSE_BRACE);
            self.expect(CLOSE_PAREN)?;
            return Ok(CallArgs { span: lo.to(self.prev_token.span), kind: CallArgsKind::Named(args) });
        }
        let args = self.parse_seq(CLOSE_PAREN, TokenKind::Comma, false, |p| p.parse_expr())?;
        self.eat(CLOSE_PAREN);
        Ok(CallArgs { span: lo.to(self.prev_token.span), kind: CallArgsKind::Unnamed(args) })
    }

    fn parse_primary_expr(&mut self) -> PResult<Expr> {
        let lo = self.token.span;
        if self.check(OPEN_PAREN) {
            self.bump();
            let comps = self.parse_tuple_components(CLOSE_PAREN, false)?;
            self.expect(CLOSE_PAREN)?;
            let span = lo.to(self.prev_token.span);
            return Ok(Expr { span, kind: ExprKind::Tuple(comps) });
        }
        if self.check(OPEN_BRACKET) {
            self.bump();
            let comps = self.parse_tuple_components(CLOSE_BRACKET, true)?;
            self.expect(CLOSE_BRACKET)?;
            let span = lo.to(self.prev_token.span);
            let mut out = vec![];
            for c in comps {
                if let Some(c) = c {
                    out.push(c);
                }
            }
            return Ok(Expr { span, kind: ExprKind::Array(out) });
        }
        if self.check_keyword(kw::New) {
            self.bump();
            let ty = self.parse_type()?;
            let span = lo.to(self.prev_token.span);
            return Ok(Expr { span, kind: ExprKind::New(ty) });
        }
        if self.check_keyword(kw::Payable) {
            self.bump();
            if self.token.kind != OPEN_PAREN {
                return Err(self.expected_one_of_not_found(&[Expected::Token(OPEN_PAREN)], &[]));
            }
            let args = self.parse_call_args()?;
            let span = lo.to(self.prev_token.span);
            return Ok(Expr { span, kind: ExprKind::Payable(args) });
        }
        if self.check_keyword(kw::Type) {
            self.bump();
            self.expect(OPEN_PAREN)?;
            let ty = self.parse_type()?;
            self.expect(CLOSE_PAREN)?;
            let span = lo.to(self.prev_token.span);
            return Ok(Expr { span, kind: ExprKind::TypeCall(ty) });
        }
        if self.check_elementary_type() {
            let ty = self.parse_elementary_type()?;
            if let TypeKind::Elementary(ElemTy::Address(true)) = ty.kind {
                return Err(Diag::new(Level::Error, "`address payable` cannot be used in an expression").span(ty.span));
            }
            return Ok(Expr { span: ty.span, kind: ExprKind::Type(ty) });
        }
        if self.check_ident() {
            let name = self.token.ident().unwrap();
            let span = self.token.span;
            self.bump();
            return Ok(Expr { span, kind: ExprKind::Ident(Ident { name, span }) });
        }
        if self.check_lit() {
            let lit = self.parse_lit()?;
            let mut sub = None;
            if let Some(d) = subdenom_of(&self.token) {
                let sp = self.token.span;
                self.bump();
                if !matches!(lit.kind, LitKind::Number(_) | LitKind::Rational(_) | LitKind::Address(_) | LitKind::Err) {
                    self.soft_err(lit.span.to(sp), "sub-denominations are only allowed on number and rational literals");
                }
                sub = Some((d, sp));
            }
            let span = lo.to(self.prev_token.span);
            return Ok(Expr { span, kind: ExprKind::Lit(lit, sub) });
        }
        Err(self.unexpected())
    }

    fn parse_tuple_components(&mut self, close: TokenKind, is_array: bool) -> PResult<Vec<Option<Expr>>> {
        let mut comps: Vec<Option<Expr>> = vec![];
        let mut last_was_comma = false;
        loop {
            if self.check(close) {
                if last_was_comma {
                    comps.push(None);
                    if is_array {
                        return Err(self.array_empty_err());
                    }
                }
                break;
            }
            if self.check(TokenKind::Comma) {
                if is_array {
                    return Err(self.array_empty_err());
                }
                comps.push(None);
                self.bump();
                last_was_comma = true;
                continue;
            }
            if self.token.is_eof() {
                break;
            }
            comps.push(Some(self.parse_expr()?));
            last_was_comma = false;
            if self.check(close) {
                break;
            }
            if self.token.kind == TokenKind::Comma {
                self.bump();
                last_was_comma = true;
                continue;
            }
            return Err(self.expected_one_of_not_found(&[Expected::Token(TokenKind::Comma)], &[]));
        }
        Ok(comps)
    }

    fn array_empty_err(&self) -> Diag {
        Diag::new(Level::Error, "array expression components cannot be empty").span(self.token.span)
    }

    /// Parses a literal (with string concatenation).
    pub fn parse_lit(&mut self) -> PResult<Lit> {
        let t = self.token;
        let lo = t.span;
        match t.kind {
            TokenKind::Ident(kw::True) | TokenKind::Ident(kw::False) => {
                self.bump();
                let b = t.kind == TokenKind::Ident(kw::True);
                return Ok(Lit { span: lo, symbol: t.ident().unwrap(), kind: LitKind::Bool(b), parts: vec![] });
            }
            TokenKind::Literal(k, sym) => {
                self.bump();
                match k {
                    crate::token::LitKind::Integer | crate::token::LitKind::Rational => {
                        let kind = self.parse_number_lit(sym, t.span, k);
                        return Ok(Lit { span: lo, symbol: sym, kind, parts: vec![] });
                    }
                    crate::token::LitKind::Str | crate::token::LitKind::UnicodeStr | crate::token::LitKind::HexStr => {
                        let mut parts = vec![(k, sym, t.span)];
                        while let TokenKind::Literal(k2, s2) = self.token.kind {
                            if k2 != k {
                                break;
                            }
                            parts.push((k2, s2, self.token.span));
                            self.bump();
                        }
                        let mut bytes = vec![];
                        let mut ok = true;
                        for (k, s, sp) in &parts {
                            match crate::unescape::unescape_lit(self.dcx, *k, s.as_str(), sp.lo + if *k == crate::token::LitKind::Str { 1 } else if *k == crate::token::LitKind::HexStr { 4 } else { 8 }) {
                                Some(b) => bytes.extend(b),
                                None => ok = false,
                            }
                        }
                        let span = lo.to(self.prev_token.span);
                        let symbol = if parts.len() == 1 { sym } else { Symbol::intern(&parts.iter().map(|p| p.1.as_str()).collect::<String>()) };
                        let kind = if ok { LitKind::Str(k, bytes) } else { LitKind::Err };
                        let kind = match kind {
                            LitKind::Err => LitKind::Str(k, vec![]),
                            x => x,
                        };
                        return Ok(Lit { span, symbol, kind, parts });
                    }
                    crate::token::LitKind::Err => {
                        return Ok(Lit { span: lo, symbol: sym, kind: LitKind::Err, parts: vec![] });
                    }
                }
            }
            _ => Err(self.unexpected()),
        }
    }

    fn parse_number_lit(&mut self, sym: Symbol, _span: Span, k: crate::token::LitKind) -> LitKind {
        let s = sym.as_str();
        let clean: String = s.chars().filter(|&c| c != '_').collect();
        if let Some(hex) = clean.strip_prefix("0x") {
            if hex.len() == 40 && k == crate::token::LitKind::Integer {
                return LitKind::Address(sym);
            }
            return match BigUint::parse_radix(hex, 16) {
                Some(v) => LitKind::Number(BigInt::from_u(v)),
                None => LitKind::Err,
            };
        }
        if clean.starts_with("0b") || clean.starts_with("0o") {
            let radix = if clean.starts_with("0b") { 2 } else { 8 };
            return match BigUint::parse_radix(&clean[2..], radix) {
                Some(v) => LitKind::Number(BigInt::from_u(v)),
                None => LitKind::Err,
            };
        }
        // decimal with optional fraction and exponent
        let (mantissa, exp) = match clean.find(|c| c == 'e' || c == 'E') {
            Some(i) => (&clean[..i], Some(&clean[i + 1..])),
            None => (clean.as_str(), None),
        };
        let (int_part, frac_part) = match mantissa.find('.') {
            Some(i) => (&mantissa[..i], &mantissa[i + 1..]),
            None => (mantissa, ""),
        };
        let digits = format!("{}{}", int_part, frac_part);
        let digits = if digits.is_empty() { "0".to_string() } else { digits };
        let Some(mut num) = BigUint::parse_radix(&digits, 10) else { return LitKind::Err };
        let mut exp_val: i64 = -(frac_part.len() as i64);
        if let Some(e) = exp {
            let (neg, e) = if let Some(r) = e.strip_prefix('-') { (true, r) } else { (false, e) };
            let Ok(ev) = e.parse::<i64>() else { return LitKind::Err };
            exp_val += if neg { -ev } else { ev };
        }
        if exp_val >= 0 {
            if exp_val > 4096 {
                return LitKind::Err;
            }
            num = num.mul(&BigUint::from_u64(10).pow(exp_val as u64));
            LitKind::Number(BigInt::from_u(num))
        } else {
            if -exp_val > 4096 {
                return LitKind::Err;
            }
            let den = BigUint::from_u64(10).pow((-exp_val) as u64);
            let r = BigRational::new(BigInt::from_u(num), den);
            if r.is_integer() {
                LitKind::Number(r.num)
            } else {
                LitKind::Rational(r)
            }
        }
    }
}
