                    crate::token::LitKind::Integer | crate::token::LitKind::Rational => {
                        let kind = self.parse_number_lit(sym, t.span, k);
                        return Ok(Lit { span: lo, symbol: sym, kind, parts: vec![] });
                    }
                    crate::token::LitKind::Str | crate::token::LitKind::UnicodeStr | crate::token::LitKind::HexStr => {
                        let mut parts = vec![(k, sym, t.span)];
                        while let TokenKind::Literal(k2, s2) = self.token.kind {
                            if k2 != k {
