                                None => ok = false,
                            }
                        }
                        let span = lo.to(self.prev_token.span);
                        let symbol = if parts.len() == 1 { sym } else { Symbol::intern(&parts.iter().map(|p| p.1.as_str()).collect::<String>()) };
                        let kind = if ok { LitKind::Str(k, bytes) } else { LitKind::Err };
                        let kind = match kind {
                            LitKind::Err => LitKind::Str(k, vec![]),
                            x => x,
                        };
                        return Ok(Lit { span, symbol, kind, parts });
                    }
                    crate::token::LitKind::Err => {
                        return Ok(Lit { span: lo, symbol: sym, kind: LitKind::Err, parts: vec![] });
                    }
                }
            }
            _ => Err(self.unexpected()),
        }
    }

    fn parse_number_lit(&mut self, sym: Symbol, _span: Span, k: crate::token::LitKind) -> LitKind {
        let s = sym.as_str();
        let clean: String = s.chars().filter(|&c| c != '_').collect();
        if let Some(hex) = clean.strip_prefix("0x") {
            if hex.len() == 40 && k == crate::token::LitKind::Integer {
                return LitKind::Address(sym);
            }
            return match BigUint::parse_radix(hex, 16) {
                Some(v) => LitKind::Number(BigInt::from_u(v)),
                None => LitKind::Err,
            };
        }
        if clean.starts_with("0b") || clean.starts_with("0o") {
            let radix = if clean.starts_with("0b") { 2 } else { 8 };
            return match BigUint::parse_radix(&clean[2..], radix) {
