        } else {
            if -exp_val > 4096 {
                return LitKind::Err;
            }
            let den = BigUint::from_u64(10).pow((-exp_val) as u64);
            let r = BigRational::new(BigInt::from_u(num), den);
            if r.is_integer() {
                LitKind::Number(r.num)
            } else {
                LitKind::Rational(r)
            }
        }
    }
}
