use crate::diag::{Diag, DiagCtxt, Level};
use crate::source_map::Span;
use crate::token::LitKind;

fn err(dcx: &DiagCtxt, lo: u32, hi: u32, msg: &str) {
    dcx.emit(Diag::new(Level::Error, msg).span(Span::new(lo, hi)));
}

/// Unescapes a string literal's content. `base` is the absolute position of the content start.
pub fn unescape_lit(dcx: &DiagCtxt, kind: LitKind, s: &str, base: u32) -> Option<Vec<u8>> {
    match kind {
        LitKind::HexStr => unescape_hex(dcx, s, base),
        LitKind::Str | LitKind::UnicodeStr => unescape_str(dcx, s, base, kind == LitKind::UnicodeStr),
        _ => Some(s.as_bytes().to_vec()),
    }
}

fn unescape_hex(dcx: &DiagCtxt, s: &str, base: u32) -> Option<Vec<u8>> {
    let digits = s.chars().filter(|c| c.is_ascii_hexdigit()).count();
    if digits % 2 != 0 {
        err(dcx, base, base + s.len() as u32, "odd number of hex nibbles");
        return None;
    }
    let mut out = vec![];
    let mut ok = true;
    let mut pending: Option<u8> = None;
