            i += clen;
            continue;
        }
        out.extend_from_slice(&b[i..i + clen]);
        i += clen;
    }
    if ok {
        Some(out)
    } else {
        None
    }
}

fn encode_utf8_raw(v: u32, out: &mut Vec<u8>) {
    if v < 0x80 {
        out.push(v as u8);
    } else if v < 0x800 {
        out.push((0xC0 | (v >> 6)) as u8);
        out.push((0x80 | (v & 0x3F)) as u8);
