use super::item::VarFlags;
use super::*;

enum StmtLookahead {
    VarDecl,
    Expr,
    Iap,
}

struct Iap {
    base: IapBase,
    indices: Vec<(IndexKind, Span)>,
}

enum IapBase {
    Path(Path),
    Elem(Type),
}

impl<'a> Parser<'a> {
    pub fn parse_block(&mut self) -> PResult<Block> {
        let lo = self.token.span;
        self.expect(OPEN_BRACE)?;
        let mut stmts = vec![];
        loop {
            if self.eat(CLOSE_BRACE) {
                break;
            }
            if self.token.is_eof() {
                break;
            }
            stmts.push(self.parse_stmt()?);
        }
        Ok(Block { span: lo.to(self.prev_token.span), stmts })
    }

    pub fn parse_stmt(&mut self) -> PResult<Stmt> {
        let docs = self.take_docs();
        let lo = self.token.span;
        let kind = self.parse_stmt_kind()?;
        Ok(Stmt { docs, span: lo.to(self.prev_token.span), kind })
    }

    fn parse_stmt_kind(&mut self) -> PResult<StmtKind> {
        if self.check(OPEN_BRACE) {
            return Ok(StmtKind::Block(self.parse_block()?));
        }
        if self.eat_keyword(kw::Unchecked) {
            return Ok(StmtKind::UncheckedBlock(self.parse_block()?));
        }
        if self.eat_keyword(kw::If) {
            self.expect(OPEN_PAREN)?;
            let cond = self.parse_expr()?;
            self.expect(CLOSE_PAREN)?;
            let then = self.parse_stmt()?;
            let els = if self.eat_keyword(kw::Else) { Some(Box::new(self.parse_stmt()?)) } else { None };
            return Ok(StmtKind::If(cond, Box::new(then), els));
        }
        if self.eat_keyword(kw::While) {
            self.expect(OPEN_PAREN)?;
            let cond = self.parse_expr()?;
            self.expect(CLOSE_PAREN)?;
            let body = self.parse_stmt()?;
            return Ok(StmtKind::While(cond, Box::new(body)));
        }
        if self.eat_keyword(kw::Do) {
            let body = self.parse_stmt()?;
            self.expect_keyword(kw::While)?;
            self.expect(OPEN_PAREN)?;
            let cond = self.parse_expr()?;
            self.expect(CLOSE_PAREN)?;
            self.expect_semi()?;
            return Ok(StmtKind::DoWhile(Box::new(body), cond));
        }
        if self.eat_keyword(kw::For) {
            self.expect(OPEN_PAREN)?;
            let init = if self.eat(TokenKind::Semi) {
                None
            } else {
                let lo = self.token.span;
                let k = self.parse_simple_stmt_kind()?;
                self.expect_semi()?;
                Some(Box::new(Stmt { docs: vec![], span: lo.to(self.prev_token.span), kind: k }))
            };
            let cond = if self.check(TokenKind::Semi) { None } else { Some(self.parse_expr()?) };
            self.expect_semi()?;
            let next = if self.token.kind == CLOSE_PAREN { None } else { Some(self.parse_expr()?) };
            self.expect(CLOSE_PAREN)?;
            let body = self.parse_stmt()?;
            return Ok(StmtKind::For(init, cond, next, Box::new(body)));
        }
        if self.eat_keyword(kw::Continue) {
            self.expect_semi()?;
            return Ok(StmtKind::Continue);
        }
        if self.eat_keyword(kw::Break) {
            self.expect_semi()?;
            return Ok(StmtKind::Break);
        }
        if self.eat_keyword(kw::Return) {
            let e = if self.check(TokenKind::Semi) { None } else { Some(self.parse_expr()?) };
            self.expect_semi()?;
            return Ok(StmtKind::Return(e));
        }
        if self.check_keyword(kw::Throw) {
            let sp = self.token.span;
            return Err(Diag::new(Level::Error, "`throw` statements have been removed; use `revert`, `require`, or `assert` instead").span(sp));
        }
        if self.eat_keyword(kw::Try) {
            return self.parse_try();
        }
        if self.eat_keyword(kw::Assembly) {
            return self.parse_assembly();
        }
        if self.eat_keyword(kw::Emit) {
            let path = self.parse_path()?;
            let args = self.parse_call_args()?;
            self.expect_semi()?;
            return Ok(StmtKind::Emit(path, args));
        }
        if self.check_keyword(kw::Revert) && self.look_ahead(1).is_non_reserved_ident(false) {
            self.bump();
            let path = self.parse_path()?;
            let args = self.parse_call_args()?;
            self.expect_semi()?;
            return Ok(StmtKind::Revert(path, args));
        }
        if self.check_keyword(kw::Underscore) && self.look_ahead(1).kind == TokenKind::Semi {
            self.bump();
            self.bump();
            return Ok(StmtKind::Placeholder);
        }
        let k = self.parse_simple_stmt_kind()?;
        self.expect_semi()?;
        Ok(k)
    }

    fn parse_try(&mut self) -> PResult<StmtKind> {
        let expr = self.parse_expr()?;
        let returns = if self.eat_keyword(kw::Returns) { self.parse_param_list(VarFlags::function_param())? } else { vec![] };
        let block = self.parse_block()?;
        let mut catch = vec![];
        self.expect_keyword(kw::Catch)?;
        loop {
            let lo = self.prev_token.span;
            let name = self.parse_ident_opt();
            let args = if self.check(OPEN_PAREN) { self.parse_param_list(VarFlags::function_param())? } else { vec![] };
            let block = self.parse_block()?;
            catch.push(CatchClause { name, args, block, span: lo.to(self.prev_token.span) });
            if !self.eat_keyword(kw::Catch) {
                break;
            }
        }
        Ok(StmtKind::Try(Box::new(TryStmt { expr, returns, block, catch })))
    }

    fn parse_assembly(&mut self) -> PResult<StmtKind> {
        let dialect = if self.check_plain_str_lit() {
            let t = self.token;
            self.bump();
            let sym = match t.kind {
                TokenKind::Literal(_, s) => s,
                _ => unreachable!(),
            };
            Some((sym, t.span))
        } else {
            None
        };
        let mut flags = vec![];
        if self.check(OPEN_PAREN) {
            self.bump();
            flags = self.parse_seq(CLOSE_PAREN, TokenKind::Comma, false, |p| {
                if p.check_plain_str_lit() {
                    let t = p.token;
                    p.bump();
                    match t.kind {
                        TokenKind::Literal(_, s) => Ok((s, t.span)),
                        _ => unreachable!(),
                    }
                } else {
                    Err(p.unexpected())
                }
            })?;
            self.eat(CLOSE_PAREN);
        }
        let block = self.parse_yul_block()?;
        Ok(StmtKind::Assembly(Assembly { dialect, flags, block }))
    }

    fn peek_stmt_type(&self) -> StmtLookahead {
        let t = self.token;
        if t.is_keyword(kw::Mapping) || t.is_keyword(kw::Function) {
            return StmtLookahead::VarDecl;
        }
        let is_elem = t.is_elementary_type();
        let might_be_type = is_elem || t.is_non_reserved_ident(false);
        if might_be_type {
            let next = self.look_ahead(1);
            if is_elem && (next.is_keyword(kw::Payable) || next.is_keyword(kw::Pure) || next.is_keyword(kw::View)) {
                return StmtLookahead::VarDecl;
            }
            if next.is_non_reserved_ident(false) || is_location(&next) {
                return StmtLookahead::VarDecl;
            }
            if next.kind == OPEN_BRACKET || next.kind == TokenKind::Dot {
                return StmtLookahead::Iap;
            }
        }
        StmtLookahead::Expr
    }

    fn parse_iap(&mut self) -> PResult<Iap> {
        let base = if self.token.is_elementary_type() {
            IapBase::Elem(self.parse_elementary_type()?)
        } else {
            IapBase::Path(self.parse_path()?)
        };
        let mut indices = vec![];
        while self.eat(OPEN_BRACKET) {
            let kind = if self.check(CLOSE_BRACKET) {
                IndexKind::Index(None)
            } else {
                let start = if self.check(TokenKind::Colon) { None } else { Some(Box::new(self.parse_expr()?)) };
                if self.eat(TokenKind::Colon) {
                    let end = if self.check(CLOSE_BRACKET) { None } else { Some(Box::new(self.parse_expr()?)) };
                    IndexKind::Range(start, end)
                } else {
                    IndexKind::Index(start)
                }
            };
            self.expect(CLOSE_BRACKET)?;
            indices.push((kind, self.prev_token.span));
        }
        Ok(Iap { base, indices })
    }

    fn iap_to_type(&mut self, iap: Iap) -> PResult<Type> {
        let mut ty = match iap.base {
            IapBase::Path(p) => Type { span: p.span, kind: TypeKind::Custom(p) },
            IapBase::Elem(t) => t,
        };
        for (k, end) in iap.indices {
            let len = match k {
                IndexKind::Index(e) => e,
                IndexKind::Range(s, e) => {
                    let sp = match (&s, &e) {
                        (Some(s), Some(e)) => s.span.to(e.span),
                        (Some(s), None) => s.span,
                        (None, Some(e)) => e.span,
                        (None, None) => end,
                    };
                    let _ = sp;
                    return Err(Diag::new(Level::Error, "expected array length, got range expression").span(ty.span.to(end)));
                }
            };
            ty = Type { span: ty.span.to(end), kind: TypeKind::Array(Box::new(ty), len) };
        }
        Ok(ty)
    }

    fn iap_to_expr(&mut self, iap: Iap) -> Expr {
        let mut e = match iap.base {
            IapBase::Path(p) => {
                let first = p.segments[0];
                let mut e = Expr { span: first.span, kind: ExprKind::Ident(first) };
                for seg in &p.segments[1..] {
                    let span = e.span.to(seg.span);
                    e = Expr { span, kind: ExprKind::Member(Box::new(e), *seg) };
                }
                e
            }
            IapBase::Elem(t) => Expr { span: t.span, kind: ExprKind::Type(t) },
        };
        for (k, end) in iap.indices {
            let span = e.span.to(end);
            e = Expr { span, kind: ExprKind::Index(Box::new(e), k) };
        }
        e
    }

    pub fn parse_simple_stmt_kind(&mut self) -> PResult<StmtKind> {
        if self.token.kind == OPEN_PAREN {
            return self.parse_tuple_stmt();
        }
        let lo = self.token.span;
        match self.peek_stmt_type() {
            StmtLookahead::VarDecl => {
                let ty = self.parse_type()?;
                let v = self.parse_var_decl_rest(ty, VarFlags::local_var(), false, lo)?;
                Ok(StmtKind::DeclSingle(v))
            }
            StmtLookahead::Expr => {
                let e = self.parse_expr()?;
                Ok(StmtKind::Expr(e))
            }
            StmtLookahead::Iap => {
                let iap = self.parse_iap()?;
                if self.token.is_non_reserved_ident(false) || is_location(&self.token) {
                    let ty = self.iap_to_type(iap)?;
                    let ty = self.parse_array_type_suffix(ty)?;
                    let v = self.parse_var_decl_rest(ty, VarFlags::local_var(), false, lo)?;
                    Ok(StmtKind::DeclSingle(v))
                } else {
                    let e = self.iap_to_expr(iap);
                    let e = self.parse_postfix_expr(e)?;
                    let e = self.parse_postfix_incdec(e)?;
                    let e = self.parse_expr_from_unary(e)?;
                    Ok(StmtKind::Expr(e))
                }
            }
        }
    }

    fn parse_tuple_stmt(&mut self) -> PResult<StmtKind> {
        let lo = self.token.span;
        self.bump();
        let mut empty = 0;
        while self.token.kind == TokenKind::Comma {
            self.bump();
            empty += 1;
        }
        let la = self.peek_stmt_type();
        let (is_decl, iap) = match la {
            StmtLookahead::VarDecl => (true, None),
            StmtLookahead::Expr => (false, None),
            StmtLookahead::Iap => {
                let iap = self.parse_iap()?;
                let d = self.token.is_non_reserved_ident(false) || is_location(&self.token);
                (d, Some(iap))
            }
        };
        if is_decl {
            let mut vars: Vec<Option<VarDecl>> = (0..empty).map(|_| None).collect();
            let vlo = self.token.span;
            let first = match iap {
                Some(iap) => {
                    let ty = self.iap_to_type(iap)?;
                    let ty = self.parse_array_type_suffix(ty)?;
                    let tlo = ty.span;
                    self.parse_var_decl_rest(ty, VarFlags::function_param(), false, tlo)?
                }
                None => self.parse_var_decl_with(VarFlags::function_param(), false)?,
            };
            let _ = vlo;
            vars.push(Some(first));
            loop {
                if self.check(CLOSE_PAREN) {
                    break;
                }
                self.expect(TokenKind::Comma)?;
                if self.token.kind == TokenKind::Comma || self.token.kind == CLOSE_PAREN {
                    vars.push(None);
                } else {
                    vars.push(Some(self.parse_var_decl_with(VarFlags::function_param(), false)?));
                }
            }
            self.expect(CLOSE_PAREN)?;
            self.expect(TokenKind::Eq)?;
            let e = self.parse_expr()?;
            return Ok(StmtKind::DeclMulti(vars, e));
        }
        let mut comps: Vec<Option<Expr>> = (0..empty).map(|_| None).collect();
        if self.token.kind == CLOSE_PAREN && iap.is_none() {
            // `(,,)` or `()`
            if empty > 0 {
                comps.push(None);
            }
        } else {
            let first = match iap {
                Some(iap) => {
                    let e = self.iap_to_expr(iap);
                    let e = self.parse_postfix_expr(e)?;
                    let e = self.parse_postfix_incdec(e)?;
                    self.parse_expr_from_unary(e)?
                }
                None => self.parse_expr()?,
            };
            comps.push(Some(first));
            loop {
                if self.check(CLOSE_PAREN) {
                    break;
                }
                self.expect(TokenKind::Comma)?;
                if self.token.kind == TokenKind::Comma || self.token.kind == CLOSE_PAREN {
                    comps.push(None);
                } else {
                    comps.push(Some(self.parse_expr()?));
                }
            }
        }
        self.expect(CLOSE_PAREN)?;
        let tuple = Expr { span: lo.to(self.prev_token.span), kind: ExprKind::Tuple(comps) };
        let e = self.parse_postfix_expr(tuple)?;
        let e = self.parse_postfix_incdec(e)?;
        let e = self.parse_expr_from_unary(e)?;
        Ok(StmtKind::Expr(e))
    }
}

pub fn is_location(t: &Token) -> bool {
    t.is_keyword(kw::Memory) || t.is_keyword(kw::Storage) || t.is_keyword(kw::Calldata)
}
