    "difficulty", "prevrandao", "gaslimit", "codesize", "codecopy",
];

pub fn is_evm_builtin(s: Symbol) -> bool {
    EVM_BUILTINS.contains(&s.as_str())
}

pub fn is_yul_kw(s: Symbol) -> bool {
    matches!(
        s,
        kw::Function | kw::Let | kw::If | kw::Switch | kw::Case | kw::Default | kw::For | kw::Break | kw::Continue | kw::Leave | kw::True | kw::False
    )
}

impl<'a> Parser<'a> {
    pub fn yul_token_descr(&self, t: &Token) -> String {
        match t.kind {
            TokenKind::Ident(s) => {
                if is_used_keyword_like(s) {
                    format!("keyword `{}`", s)
                } else if s.is_reserved_keyword() {
                    format!("reserved keyword `{}`", s)
                } else if is_yul_kw(s) {
                    format!("Yul keyword `{}`", s)
                } else if is_evm_builtin(s) {
                    format!("Yul EVM builtin keyword `{}`", s)
                } else {
                    format!("`{}`", s)
                }
            }
            _ => t.full_description(),
        }
    }

    fn yul_is_ident(&self, t: &Token) -> bool {
        match t.kind {
            TokenKind::Ident(s) => !is_yul_kw(s) || matches!(s, kw::True | kw::False),
            _ => false,
        }
    }

    fn yul_is_decl_ident(&self, t: &Token) -> bool {
        match t.kind {
            TokenKind::Ident(s) => !is_yul_kw(s) && !is_evm_builtin(s),
            _ => false,
        }
    }

    fn yul_check_ident(&mut self) -> bool {
        let p = self.yul_is_ident(&self.token.clone());
        if !p {
            self.push_expected(Expected::Ident);
        }
        p
    }

    fn yul_expected_ident(&mut self) -> Diag {
        let msg = format!("expected identifier, found {}", self.yul_token_descr(&self.token.clone()));
        Diag::new(Level::Error, msg).span(self.token_err_span())
    }

    fn yul_parse_decl_ident(&mut self) -> PResult<Ident> {
        if self.yul_is_decl_ident(&self.token.clone()) {
            let name = self.token.ident().unwrap();
            let span = self.token.span;
            self.bump();
            return Ok(Ident { name, span });
        }
        Err(self.yul_expected_ident())
    }

    pub fn parse_yul_block(&mut self) -> PResult<yul::Block> {
        let old = self.in_yul;
        self.in_yul = true;
        let r = self.parse_yul_block_inner();
        self.in_yul = old;
        r
    }

    fn parse_yul_block_inner(&mut self) -> PResult<yul::Block> {
        let lo = self.token.span;
        self.expect(OPEN_BRACE)?;
        let mut stmts = vec![];
        loop {
            if self.eat(CLOSE_BRACE) {
                break;
            }
            if self.token.is_eof() {
                break;
            }
            stmts.push(self.parse_yul_stmt()?);
        }
        Ok(yul::Block { span: lo.to(self.prev_token.span), stmts })
    }

    fn parse_yul_stmt(&mut self) -> PResult<yul::Stmt> {
        let lo = self.token.span;
        let kind = self.parse_yul_stmt_kind()?;
        Ok(yul::Stmt { span: lo.to(self.prev_token.span), kind })
    }

    fn parse_yul_stmt_kind(&mut self) -> PResult<yul::StmtKind> {
        use yul::StmtKind as K;
        if self.check(OPEN_BRACE) {
            return Ok(K::Block(self.parse_yul_block_inner()?));
        }
        if self.eat_keyword(kw::Function) {
            let name = self.yul_parse_decl_ident()?;
            let params = self.parse_delim_seq(Delim::Paren, false, |p| p.yul_parse_decl_ident())?;
            let mut returns = vec![];
            if self.eat(TokenKind::Arrow) {
                returns.push(self.yul_parse_decl_ident()?);
                while self.eat(TokenKind::Comma) {
                    returns.push(self.yul_parse_decl_ident()?);
                }
            }
            let body = self.parse_yul_block_inner()?;
            return Ok(K::FunctionDef(yul::Function { name, params, returns, body }));
        }
        if self.eat_keyword(kw::Let) {
            let mut names = vec![self.yul_parse_decl_ident()?];
            while self.eat(TokenKind::Comma) {
                names.push(self.yul_parse_decl_ident()?);
            }
            let init = if self.eat(TokenKind::Walrus) { Some(self.parse_yul_expr()?) } else { None };
            return Ok(K::VarDecl(names, init));
        }
        if self.eat_keyword(kw::If) {
            let cond = self.parse_yul_expr()?;
            let body = self.parse_yul_block_inner()?;
            return Ok(K::If(cond, body));
        }
        if self.check_keyword(kw::Switch) {
            let sw_span = self.token.span;
            self.bump();
            let selector = self.parse_yul_expr()?;
            let mut cases = vec![];
            while self.token.is_keyword(kw::Case) {
                let clo = self.token.span;
                self.bump();
                let lit = self.parse_yul_case_lit()?;
                let body = self.parse_yul_block_inner()?;
                cases.push(yul::Case { span: clo.to(self.prev_token.span), constant: Some(lit), body });
            }
            if self.token.is_keyword(kw::Default) {
                let clo = self.token.span;
                self.bump();
                let body = self.parse_yul_block_inner()?;
                cases.push(yul::Case { span: clo.to(self.prev_token.span), constant: None, body });
            }
            let sp = sw_span.to(self.prev_token.span);
            if cases.is_empty() {
                self.soft_err(sp, "`switch` statement has no cases");
            } else if cases.len() == 1 && cases[0].constant.is_none() {
                self.dcx.emit(Diag::new(Level::Warning, "`switch` statement has only a default case").code("9592").span(sp));
            }
            return Ok(K::Switch { selector, cases });
        }
        if self.eat_keyword(kw::For) {
            let init = self.parse_yul_block_inner()?;
            let cond = self.parse_yul_expr()?;
            let step = self.parse_yul_block_inner()?;
            let body = self.parse_yul_block_inner()?;
            return Ok(K::For { init, cond, step, body });
        }
        if self.eat_keyword(kw::Break) {
            return Ok(K::Break);
        }
        if self.eat_keyword(kw::Continue) {
            return Ok(K::Continue);
        }
        if self.eat_keyword(kw::Leave) {
            return Ok(K::Leave);
        }
        if self.check_keyword(kw::Switch) {}
        if self.yul_check_ident() {
            let path = self.parse_yul_path()?;
            if self.check(OPEN_PAREN) {
                let call = self.parse_yul_call(path)?;
                return Ok(K::Expr(call));
            }
            if self.check(TokenKind::Comma) {
                let mut paths = vec![path];
                while self.eat(TokenKind::Comma) {
                    paths.push(self.parse_yul_path()?);
                }
                self.expect(TokenKind::Walrus)?;
                let e = self.parse_yul_expr()?;
                if !matches!(e.kind, yul::ExprKind::Call(..)) {
                    self.soft_err(e.span, "only function calls are allowed in multi-assignment");
                }
                return Ok(K::AssignMulti(paths, e));
            }
            if self.check(TokenKind::Walrus) {
                self.bump();
                let e = self.parse_yul_expr()?;
                return Ok(K::AssignSingle(path, e));
            }
            return Err(self.unexpected());
        }
        Err(self.unexpected())
    }

    fn parse_yul_case_lit(&mut self) -> PResult<Lit> {
        if self.token.is_lit() {
            return self.parse_lit();
        }
        let msg = format!("expected literal, found {}", self.yul_token_descr(&self.token.clone()));
        Err(Diag::new(Level::Error, msg).span(self.token_err_span()))
    }

    fn parse_yul_path(&mut self) -> PResult<yul::Path> {
        let first = self.parse_yul_path_segment()?;
        let mut segments = vec![first];
        if self.token.kind == TokenKind::Dot {
            while self.eat(TokenKind::Dot) {
                segments.push(self.parse_yul_path_segment()?);
            }
        }
        let span = first.span.to(self.prev_token.span);
        Ok(yul::Path { segments, span })
    }

    fn parse_yul_path_segment(&mut self) -> PResult<Ident> {
        if let TokenKind::Ident(name) = self.token.kind {
            if !is_yul_kw(name) || matches!(name, kw::True | kw::False) {
                let span = self.token.span;
                self.bump();
                return Ok(Ident { name, span });
            }
        }
        Err(self.yul_expected_ident())
    }

    fn parse_yul_call(&mut self, path: yul::Path) -> PResult<yul::Expr> {
        if path.segments.len() > 1 {
            return Err(Diag::new(Level::Error, "fully-qualified paths aren't allowed here").span(path.span));
        }
        let name = path.segments[0];
        let args = self.parse_delim_seq(Delim::Paren, false, |p| p.parse_yul_expr())?;
        let span = path.span.to(self.prev_token.span);
        Ok(yul::Expr { span, kind: yul::ExprKind::Call(name, args) })
    }

    pub fn parse_yul_expr(&mut self) -> PResult<yul::Expr> {
        if self.check_lit() {
            let lit = self.parse_lit()?;
            return Ok(yul::Expr { span: lit.span, kind: yul::ExprKind::Lit(lit) });
        }
        if self.check_path() {
            let path = self.parse_yul_path()?;
            if self.check(OPEN_PAREN) {
                return self.parse_yul_call(path);
            }
            if path.segments.len() == 1 && is_evm_builtin(path.segments[0].name) {
                let msg = format!("expected identifier, found {}", self.yul_token_descr(&self.prev_token.clone()));
                return Err(Diag::new(Level::Error, msg).span(path.span));
            }
            return Ok(yul::Expr { span: path.span, kind: yul::ExprKind::Path(path) });
        }
        Err(self.unexpected())
    }
}
