use crate::ast::DocComment;
use crate::diag::{Diag, DiagCtxt, Level};

pub fn check_doc_comment(dcx: &DiagCtxt, dc: &DocComment) {
    let s = dc.symbol.as_str();
    for line in s.split('\n') {
        let mut l = line.trim_start();
        if dc.is_block {
            if let Some(r) = l.strip_prefix('*') {
                l = r.trim_start();
            }
        }
        let Some(rest) = l.strip_prefix('@') else { continue };
        let tag: String = rest.chars().take_while(|c| !c.is_whitespace()).collect();
        let valid = matches!(tag.as_str(), "title" | "author" | "notice" | "dev" | "param" | "return" | "inheritdoc") || tag.starts_with("custom:");
        if !valid {
            dcx.emit(Diag::new(Level::Warning, format!("invalid natspec tag '@{}', custom tags must use format '@custom:name'", tag)).span(dc.span));
        }
    }
}
