use crate::cli::Args;
use crate::diag::{Diag, DiagConfig, DiagCtxt, ErrorFormat, HumanStyle, Level};
use crate::source_map::{FileName, SourceMap};
use std::io::Read;
use std::rc::Rc;

pub fn run(args: Args) -> i32 {
    let sm = Rc::new(SourceMap::new());
    let color = match args.color.as_deref() {
        Some("always") => true,
        _ => false,
    };
    let cfg = DiagConfig {
        format: match args.error_format.as_deref() {
            Some("json") => ErrorFormat::Json,
            Some("rustc-json") => ErrorFormat::RustcJson,
            _ => ErrorFormat::Human,
        },
        human: match args.error_format_human.as_deref() {
            Some("ascii") => HumanStyle::Ascii,
            Some("short") => HumanStyle::Short,
            _ => HumanStyle::Unicode,
        },
        color,
        ui_testing: args.ui_testing,
        width: args.diagnostic_width,
        no_warnings: args.no_warnings,
        pretty_json_err: args.pretty_json_err,
    };
    let dcx = DiagCtxt::new(sm.clone(), cfg);
    let cwd = std::env::current_dir().unwrap_or_default();
    for input in &args.inputs {
        let (name, display, src) = if input == "-" {
            let mut s = String::new();
            let _ = std::io::stdin().read_to_string(&mut s);
            (FileName::Stdin, "<stdin>".to_string(), s)
        } else {
            let p = std::path::Path::new(input);
            match std::fs::read_to_string(p) {
                Ok(s) => {
                    let abs = if p.is_absolute() { p.to_path_buf() } else { cwd.join(p) };
                    let display = if args.ui_testing { abs.display().to_string() } else { input.clone() };
                    (FileName::Real(abs), display, s)
                }
                Err(_) => {
                    dcx.emit(Diag::new(Level::Error, format!("file {} not found", input)));
                    continue;
                }
            }
        };
        let f = sm.add_file(name, display, src);
        let src = f.src.clone();
        let _ = crate::parser::parse_file(&dcx, &sm, &src, f.start_pos);
    }
    if dcx.has_errors() {
        dcx.print_summary();
        return 1;
    }
    0
}
