    function() external returns (uint) fp;

    receive() external payable {}
    fallback(bytes calldata input) external returns (bytes memory) { return input; }

    function f() public pure override returns (uint) {
        uint a = 1 ether + 2 gwei - 3 wei;
        uint b = 1 days + 2 hours + 30 minutes + 10 seconds + 1 weeks;
        int c = -5;
        uint d = a.max(b);
        (uint e, bool ok) = (d, a > b);
        if (!ok) { return e; }
        for (uint i = 0; i < 10; i++) { if (i == 5) continue; if (i == 7) break; }
        do { a--; } while (a > 0);
        uint[] memory arr = new uint[](5);
        arr[0] = c < 0 ? uint(-c) : uint(c);
        bytes memory bs = abi.encodePacked(a, b, "x", hex"00ff");
        string memory s = string(abi.encode(unicode"héllo"));
        assembly {
            let x := add(1, 2)
            if lt(x, 3) { x := 0 }
            switch x
            case 0 { x := 1 }
            default { x := 2 }
            for { let i := 0 } lt(i, 3) { i := add(i, 1) } { pop(i) }
            function inner(p) -> r { r := mul(p, 2) }
            mstore(0, inner(x))
        }
        return bs.length + bytes(s).length + arr[1:3].length;
    }

    function tryIt(address t) external returns (uint) {
        try IThing(t).thing{value: 0, gas: 10000}(1) returns (uint v) {
            return v;
        } catch Error(string memory reason) {
            revert(reason);
        } catch Panic(uint code) {
            return code;
        } catch (bytes memory) {
            revert Unauthorized(msg.sender);
        }
    }

