        }
        let name = if path.starts_with("./") || path.starts_with("../") {
            let dir = match importer.rfind('/') {
                Some(i) => &importer[..i],
                None => "",
            };
            if dir.is_empty() {
                normalize(&path)
            } else {
                normalize(&format!("{}/{}", dir, path))
            }
        } else {
            normalize(&path)
        };
        self.resolve_name(&name)
    }

    pub fn display(&self, full: &Path, ui_testing: bool) -> String {
        let s = full.to_string_lossy().to_string();
        if ui_testing {
            return s;
        }
        let base = normalize(&self.base.to_string_lossy());
        let base_slash = if base.ends_with('/') { base.clone() } else { format!("{base}/") };
        if let Some(rest) = s.strip_prefix(&base_slash) {
            return rest.to_string();
        }
        s
    }
}

/// Emulates the observed (parallel) processing order for a batch of n items.
fn batch_order(n: usize) -> Vec<usize> {
    if n <= 1 {
        return (0..n).collect();
    }
    let mut v = vec![n - 1];
    v.extend(0..n - 1);
    v
}

pub struct Session {
    pub sm: Rc<SourceMap>,
    pub dcx: DiagCtxt,
    pub sources: Vec<Source>,
    pub args: Args,
}

pub fn run(args: Args) -> i32 {
    let sm = Rc::new(SourceMap::new());
    let color = matches!(args.color.as_deref(), Some("always"));
    let cfg = DiagConfig {
        format: match args.error_format.as_deref() {
            Some("json") => ErrorFormat::Json,
            Some("rustc-json") => ErrorFormat::RustcJson,
            _ => ErrorFormat::Human,
        },
        human: match args.error_format_human.as_deref() {
            Some("ascii") => HumanStyle::Ascii,
            Some("short") => HumanStyle::Short,
            _ => HumanStyle::Unicode,
        },
        color,
        ui_testing: args.ui_testing,
        width: args.diagnostic_width,
        no_warnings: args.no_warnings,
        pretty_json_err: args.pretty_json_err,
    };
    let dcx = DiagCtxt::new(sm.clone(), cfg);
    let cwd = std::env::current_dir().unwrap_or_default();
    let base = match &args.base_path {
        Some(b) => {
            let p = Path::new(b);
            PathBuf::from(normalize(&(if p.is_absolute() { p.to_path_buf() } else { cwd.join(p) }).to_string_lossy()))
        }
        None => cwd.clone(),
    };
    let mut resolver = Resolver { cwd: cwd.clone(), base, include: vec![], remappings: vec![] };
    for inc in &args.include_paths {
        let p = resolver.abs(inc);
        resolver.include.push(PathBuf::from(normalize(&p.to_string_lossy())));
    }
    let mut inputs = vec![];
    for input in &args.inputs {
        if input != "-" && input.contains('=') {
            let (lhs, target) = input.split_once('=').unwrap();
            let (context, prefix) = match lhs.split_once(':') {
                Some((c, p)) => (c.to_string(), p.to_string()),
                None => (String::new(), lhs.to_string()),
            };
            resolver.remappings.push(Remapping { context, prefix, target: target.to_string() });
        } else {
            inputs.push(input.clone());
        }
    }

    let mut sess = Session { sm: sm.clone(), dcx, sources: vec![], args: args.clone() };

    // Load CLI inputs.
    let mut batch: Vec<usize> = vec![];
    for input in &inputs {
        if input == "-" {
            let mut s = String::new();
            let _ = std::io::stdin().read_to_string(&mut s);
            if sess.sources.iter().any(|s| s.file.name == FileName::Stdin) {
                continue;
            }
            let f = sm.add_file(FileName::Stdin, "<stdin>".to_string(), s);
            sess.sources.push(Source { file: f, name: "<stdin>".to_string(), ast: None, imports: vec![] });
            batch.push(sess.sources.len() - 1);
            continue;
        }
        match resolver.resolve_cli(input) {
            Some((name, full)) => {
                if let Some(_) = sess.sources.iter().position(|s| s.file.name == FileName::Real(full.clone())) {
                    continue;
                }
                let Ok(src) = std::fs::read_to_string(&full) else {
                    sess.dcx.emit(Diag::new(Level::Error, format!("file {} not found", input)));
                    continue;
                };
                let display = resolver.display(&full, args.ui_testing);
                let f = sm.add_file(FileName::Real(full), display, src);
                sess.sources.push(Source { file: f, name, ast: None, imports: vec![] });
                batch.push(sess.sources.len() - 1);
            }
            None => {
                sess.dcx.emit(Diag::new(Level::Error, format!("file {} not found", input)));
            }
        }
    }

    // Parse and resolve imports in batches.
    let mut pending_resolve: Vec<usize> = vec![];
    loop {
        for &i in batch_order(batch.len()).iter() {
            let id = batch[i];
            let f = sess.sources[id].file.clone();
            let ast = crate::parser::parse_file(&sess.dcx, &sm, &f.src, f.start_pos);
            sess.sources[id].ast = ast;
        }
        pending_resolve.extend(batch.iter().copied());
        batch.clear();
        let to_resolve: Vec<usize> = std::mem::take(&mut pending_resolve);
        for id in to_resolve {
            let Some(su) = &sess.sources[id].ast else { continue };
            let mut imports: Vec<(usize, Symbol, Span)> = vec![];
            for (idx, item) in su.items.iter().enumerate() {
                if let ast::ItemKind::Import(imp) = &item.kind {
                    imports.push((idx, imp.path, imp.path_span));
                }
            }
            let importer = sess.sources[id].name.clone();
            for (idx, path, sp) in imports {
                let pstr = path.as_str();
                if pstr.is_empty() {
                    continue;
                }
                match resolver.resolve_import(&importer, pstr) {
                    Some((name, full)) => {
                        let existing = sess.sources.iter().position(|s| s.file.name == FileName::Real(full.clone()));
                        let sid = match existing {
                            Some(e) => e,
                            None => match std::fs::read_to_string(&full) {
                                Ok(src) => {
                                    let display = resolver.display(&full, args.ui_testing);
                                    let f = sm.add_file(FileName::Real(full), display, src);
                                    sess.sources.push(Source { file: f, name, ast: None, imports: vec![] });
                                    let nid = sess.sources.len() - 1;
                                    batch.push(nid);
                                    nid
                                }
                                Err(_) => {
                                    sess.dcx.emit(Diag::new(Level::Error, format!("file {} not found", pstr)).span(sp));
                                    continue;
                                }
                            },
                        };
                        sess.sources[id].imports.push((idx, sid));
                    }
                    None => {
                        sess.dcx.emit(Diag::new(Level::Error, format!("file {} not found", pstr)).span(sp));
                    }
                }
            }
        }
        if batch.is_empty() {
            break;
        }
    }

    if sess.dcx.has_errors() || args.stop_after.is_some() {
        sess.dcx.print_summary();
        return if sess.dcx.has_errors() { 1 } else { 0 };
    }

    crate::sema::run(&mut sess)
}

