{"command":"mkdir -p /workspace/src/sema; cd /workspace/src; git mv sema.rs sema/mod.rs 2>/dev/null || mv sema.rs sema/mod.rs; cat > sema/hir.rs <<'EOF'
use crate::ast;
use crate::source_map::Span;
use crate::symbol::Symbol;
use crate::token::ElemTy;
use crate::num::BigUint;
use std::collections::HashMap;

pub type Id = usize;

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum ItemId {
    Contract(Id),
    Function(Id),
    Var(Id),
    Struct(Id),
    Enum(Id),
    Udvt(Id),
    Event(Id),
    Error(Id),
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Decl {
    Item(ItemId),
    Namespace(Id),
    Builtin(Symbol),
}

#[derive(Clone, Debug, PartialEq)]
pub enum Ty {
    Elem(ElemTy),
    Array(Box<Ty>, Option<BigUint>),
    Mapping(Box<Ty>, Box<Ty>),
    Function(Box<FnTy>),
    Contract(Id),
    Struct(Id),
    Enum(Id),
    Udvt(Id),
    Err,
}

#[derive(Clone, Debug, PartialEq)]
pub struct FnTy {
    pub params: Vec<Ty>,
    pub returns: Vec<Ty>,
    pub visibility: ast::Visibility,
    pub mutability: ast::StateMutability,
}

#[derive(Default, Clone)]
pub struct Scope {
    pub names: HashMap<Symbol, Vec<(Decl, Span)>>,
    pub order: Vec<Symbol>,
}

impl Scope {
    pub fn get(&self, s: Symbol) -> Option<&Vec<(Decl, Span)>> {
        self.names.get(&s)
    }
    pub fn insert_raw(&mut self, s: Symbol, d: Decl, sp: Span) {
        let e = self.names.entry(s).or_insert_with(|| {
            vec![]
        });
        if e.is_empty() {
            self.order.push(s);
        }
        e.push((d, sp));
    }
}

pub struct SourceH<'a> {
    pub sid: Id,
    pub ast: &'a ast::SourceUnit,
    pub scope: Scope,
    pub items: Vec<ItemId>,
}

pub struct ContractH<'a> {
    pub source: Id,
    pub ast: &'a ast::Contract,
    pub item: &'a ast::Item,
    pub name: Symbol,
    pub name_span: Span,
    pub kind: ast::ContractKind,
    pub bases: Vec<Id>,
    pub linearized: Vec<Id>,
    pub items: Vec<ItemId>,
    pub scope: Scope,
    pub ctor: Option<Id>,
    pub fallback: Option<Id>,
    pub receive: Option<Id>,
}

pub struct FunctionH<'a> {
    pub source: Id,
    pub contract: Option<Id>,
    pub ast: &'a ast::Function,
    pub item: &'a ast::Item,
    pub kind: ast::FunctionKind,
    pub name: Option<Symbol>,
    pub name_span: Span,
    pub params: Vec<Id>,
    pub returns: Vec<Id>,
    pub visibility: ast::Visibility,
    pub mutability: ast::StateMutability,
    pub is_virtual: bool,
    pub overrides: bool,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum VarKind {
    State,
    Global,
    Param,
    Return,
    Local,
    StructField,
    EventParam,
    ErrorParam,
    FnTypeParam,
}

pub struct VarH<'a> {
    pub source: Id,
    pub contract: Option<Id>,
    pub ast: &'a ast::VarDecl,
    pub name: Option<Symbol>,
    pub name_span: Span,
    pub kind: VarKind,
    pub ty: Ty,
    pub visibility: ast::Visibility,
    pub is_constant: bool,
    pub is_immutable: bool,
}

pub struct StructH<'a> {
    pub source: Id,
    pub contract: Option<Id>,
    pub ast: &'a ast::Struct,
    pub name: Symbol,
    pub name_span: Span,
    pub fields: Vec<Id>,
}

pub struct EnumH<'a> {
    pub source: Id,
    pub contract: Option<Id>,
    pub ast: &'a ast::Enum,
    pub name: Symbol,
    pub name_span: Span,
}

pub struct UdvtH<'a> {
    pub source: Id,
    pub contract: Option<Id>,
    pub ast: &'a ast::Udvt,
    pub name: Symbol,
    pub name_span: Span,
    pub ty: Ty,
}

pub struct EventH<'a> {
    pub source: Id,
    pub contract: Option<Id>,
    pub ast: &'a ast::Event,
    pub name: Symbol,
    pub name_span: Span,
    pub params: Vec<Id>,
    pub anonymous: bool,
}

pub struct ErrorH<'a> {
    pub source: Id,
    pub contract: Option<Id>,
    pub ast: &'a ast::ErrorDef,
    pub name: Symbol,
    pub name_span: Span,
    pub params: Vec<Id>,
}

#[derive(Default)]
pub struct Hir<'a> {
    pub sources: Vec<SourceH<'a>>,
    pub contracts: Vec<ContractH<'a>>,
    pub functions: Vec<FunctionH<'a>>,
    pub vars: Vec<VarH<'a>>,
    pub structs: Vec<StructH<'a>>,
    pub enums: Vec<EnumH<'a>>,
    pub udvts: Vec<UdvtH<'a>>,
    pub events: Vec<EventH<'a>>,
    pub errors: Vec<ErrorH<'a>>,
    /// source index (in session) -> hir source index
    pub source_map: HashMap<Id, Id>,
}

impl<'a> Hir<'a> {
    pub fn item_name(&self, id: ItemId) -> Option<Symbol> {
        match id {
            ItemId::Contract(i) => Some(self.contracts[i].name),
            ItemId::Function(i) => self.functions[i].name,
            ItemId::Var(i) => self.vars[i].name,
            ItemId::Struct(i) => Some(self.structs[i].name),
            ItemId::Enum(i) => Some(self.enums[i].name),
            ItemId::Udvt(i) => Some(self.udvts[i].name),
            ItemId::Event(i) => Some(self.events[i].name),
            ItemId::Error(i) => Some(self.errors[i].name),
        }
    }
    pub fn item_span(&self, id: ItemId) -> Span {
