    pub returns: Vec<Ty>,
    pub visibility: ast::Visibility,
    pub mutability: ast::StateMutability,
}

#[derive(Default, Clone)]
pub struct Scope {
    pub names: HashMap<Symbol, Vec<(Decl, Span)>>,
    pub order: Vec<Symbol>,
}

impl Scope {
    pub fn get(&self, s: Symbol) -> Option<&Vec<(Decl, Span)>> {
        self.names.get(&s)
    }
    pub fn insert_raw(&mut self, s: Symbol, d: Decl, sp: Span) {
        let e = self.names.entry(s).or_insert_with(|| {
            vec![]
        });
        if e.is_empty() {
            self.order.push(s);
        }
        e.push((d, sp));
    }
