{"command":"cd /workspace/src/sema; cat > lower.rs <<'EOF'
use super::hir::*;
use crate::ast;
use crate::diag::{Diag, DiagCtxt, Level};
use crate::driver::Session;
use crate::source_map::Span;
use crate::symbol::{kw, Symbol};
use crate::token::ElemTy;

pub struct Lowerer<'a> {
    pub sess: &'a Session,
    pub dcx: &'a DiagCtxt,
    pub hir: Hir<'a>,
}

pub fn topo_order(sess: &Session) -> Vec<usize> {
    let n = sess.sources.len();
    let mut visited = vec![false; n];
    let mut order = vec![];
    fn visit(sess: &Session, i: usize, visited: &mut Vec<bool>, order: &mut Vec<usize>) {
        if visited[i] {
            return;
        }
        visited[i] = true;
        let mut imps: Vec<(usize, usize)> = sess.sources[i].imports.clone();
        imps.sort_by_key(|x| x.0);
        for (_, dep) in imps {
            visit(sess, dep, visited, order);
        }
        order.push(i);
    }
    for i in 0..n {
        visit(sess, i, &mut visited, &mut order);
    }
    order
}

fn is_overloadable(a: Decl, b: Decl, hir: &Hir) -> bool {
    match (a, b) {
        (Decl::Item(ItemId::Function(x)), Decl::Item(ItemId::Function(y))) => {
            hir.functions[x].kind != ast::FunctionKind::Modifier && hir.functions[y].kind != ast::FunctionKind::Modifier
        }
        (Decl::Item(ItemId::Event(_)), Decl::Item(ItemId::Event(_))) => true,
        _ => false,
    }
}

impl<'a> Lowerer<'a> {
    pub fn new(sess: &'a Session) -> Self {
        Lowerer { sess, dcx: &sess.dcx, hir: Hir::default() }
    }

    pub fn err(&self, sp: Span, msg: impl Into<String>) {
        self.dcx.emit(Diag::new(Level::Error, msg).span(sp));
    }

    // ------------------------------------------------------------------
    // Collection
    // ------------------------------------------------------------------
    pub fn collect(&mut self, order: &[usize]) {
        for &sid in order {
            let Some(ast) = &self.sess.sources[sid].ast else { continue };
            let hid = self.hir.sources.len();
            self.hir.source_map.insert(sid, hid);
            self.hir.sources.push(SourceH { sid, ast, scope: Scope::default(), items: vec![] });
            for item in &ast.items {
                if let Some(id) = self.collect_item(hid, None, item) {
                    self.hir.sources[hid].items.push(id);
                }
            }
        }
    }

    fn new_var(&mut self, source: Id, contract: Option<Id>, v: &'a ast::VarDecl, kind: VarKind) -> Id {
        let visibility = v.visibility.map(|x| x.0).unwrap_or(if kind == VarKind::State { ast::Visibility::Internal } else { ast::Visibility::Internal });
        let id = self.hir.vars.len();
        self.hir.vars.push(VarH {
            source,
            contract,
            ast: v,
            name: v.name.map(|n| n.name),
            name_span: v.name.map(|n| n.span).unwrap_or(v.ty.span),
            kind,
            ty: Ty::Err,
            visibility,
            is_constant: matches!(v.mutability, Some((ast::VarMut::Constant, _))),
            is_immutable: matches!(v.mutability, Some((ast::VarMut::Immutable, _))),
        });
        id
    }

    fn collect_item(&mut self, source: Id, contract: Option<Id>, item: &'a ast::Item) -> Option<ItemId> {
        match &item.kind {
            ast::ItemKind::Contract(c) => {
                let cid = self.hir.contracts.len();
                self.hir.contracts.push(ContractH {
                    source,
                    ast: c,
                    item,
                    name: c.name.name,
                    name_span: c.name.span,
                    kind: c.kind,
                    bases: vec![],
                    linearized: vec![cid],
                    items: vec![],
                    scope: Scope::default(),
                    ctor: None,
                    fallback: None,
                    receive: None,
                });
                for sub in &c.body {
                    if let Some(id) = self.collect_item(source, Some(cid), sub) {
                        self.hir.contracts[cid].items.push(id);
                    }
                }
                Some(ItemId::Contract(cid))
            }
            ast::ItemKind::Function(f) => {
                let fid = self.hir.functions.len();
                let default_vis = match (f.kind, contract.map(|c| self.hir.contracts[c].kind)) {
                    (_, None) => ast::Visibility::Internal,
                    (ast::FunctionKind::Constructor, _) => ast::Visibility::Public,
                    (ast::FunctionKind::Fallback | ast::FunctionKind::Receive, _) => ast::Visibility::External,
                    (_, Some(ast::ContractKind::Interface)) => ast::Visibility::External,
                    _ => ast::Visibility::Public,
                };
                let visibility = f.header.visibility.map(|v| v.0).unwrap_or(default_vis);
                let mutability = f.header.state_mutability.map(|m| m.0).unwrap_or(ast::StateMutability::NonPayable);
                let is_virtual = f.header.virtual_.is_some() || contract.map_or(false, |c| self.hir.contracts[c].kind == ast::ContractKind::Interface);
                self.hir.functions.push(FunctionH {
                    source,
                    contract,
                    ast: f,
                    item,
                    kind: f.kind,
                    name: f.name.map(|n| n.name),
                    name_span: f.name.map(|n| n.span).unwrap_or(item.span),
                    params: vec![],
                    returns: vec![],
                    visibility,
                    mutability,
                    is_virtual,
                    overrides: f.header.override_.is_some(),
                });
                let mut params = vec![];
                for p in &f.header.params {
                    params.push(self.new_var(source, contract, p, VarKind::Param));
                }
                let mut returns = vec![];
                if let Some(r) = &f.header.returns {
                    for p in r {
                        returns.push(self.new_var(source, contract, p, VarKind::Return));
                    }
                }
                self.hir.functions[fid].params = params;
                self.hir.functions[fid].returns = returns;
                if let Some(c) = contract {
                    match f.kind {
                        ast::FunctionKind::Constructor => {
                            if self.hir.contracts[c].ctor.is_none() {
                                self.hir.contracts[c].ctor = Some(fid)
                            }
                        }
                        ast::FunctionKind::Fallback => {
                            if self.hir.contracts[c].fallback.is_none() {
                                self.hir.contracts[c].fallback = Some(fid)
                            }
                        }
                        ast::FunctionKind::Receive => {
                            if self.hir.contracts[c].receive.is_none() {
                                self.hir.contracts[c].receive = Some(fid)
                            }
                        }
                        _ => {}
                    }
                }
                Some(ItemId::Function(fid))
            }
            ast::ItemKind::Variable(v) => {
                let kind = if contract.is_some() { VarKind::State } else { VarKind::Global };
                Some(ItemId::Var(self.new_var(source, contract, v, kind)))
            }
            ast::ItemKind::Struct(s) => {
                let id = self.hir.structs.len();
                self.hir.structs.push(StructH { source, contract, ast: s, name: s.name.name, name_span: s.name.span, fields: vec![] });
                let mut fields = vec![];
                for f in &s.fields {
                    fields.push(self.new_var(source, contract, f, VarKind::StructField));
                }
                self.hir.structs[id].fields = fields;
                Some(ItemId::Struct(id))
            }
            ast::ItemKind::Enum(e) => {
                let id = self.hir.enums.len();
                self.hir.enums.push(EnumH { source, contract, ast: e, name: e.name.name, name_span: e.name.span });
                Some(ItemId::Enum(id))
            }
            ast::ItemKind::Udvt(u) => {
                let id = self.hir.udvts.len();
                self.hir.udvts.push(UdvtH { source, contract, ast: u, name: u.name.name, name_span: u.name.span, ty: Ty::Err });
                Some(ItemId::Udvt(id))
            }
            ast::ItemKind::Event(e) => {
                let id = self.hir.events.len();
                self.hir.events.push(EventH { source, contract, ast: e, name: e.name.name, name_span: e.name.span, params: vec![], anonymous: e.anonymous });
                let mut params = vec![];
                for p in &e.params {
                    params.push(self.new_var(source, contract, p, VarKind::EventParam));
                }
                self.hir.events[id].params = params;
                Some(ItemId::Event(id))
            }
            ast::ItemKind::Error(e) => {
                let id = self.hir.errors.len();
                self.hir.errors.push(ErrorH { source, contract, ast: e, name: e.name.name, name_span: e.name.span, params: vec![] });
                let mut params = vec![];
                for p in &e.params {
                    params.push(self.new_var(source, contract, p, VarKind::ErrorParam));
                }
                self.hir.errors[id].params = params;
                Some(ItemId::Error(id))
            }
            _ => None,
        }
    }

    // ------------------------------------------------------------------
    // Scopes
    // ------------------------------------------------------------------
    fn declare(&self, scope: &mut Scope, name: Symbol, decl: Decl, sp: Span) {
        if let Some(existing) = scope.get(name) {
            let (first, fsp) = existing[0];
            if first == decl {
                return;
            }
            if !existing.iter().all(|(e, _)| is_overloadable(*e, decl, &self.hir)) {
                self.dcx.emit(
                    Diag::new(Level::Error, format!("identifier `{}` already declared", name))
                        .span(sp)
                        .span_note(fsp, "previous declaration declared here"),
                );
                return;
            }
        }
        scope.insert_raw(name, decl, sp);
    }

    pub fn build_scopes(&mut self) {
        for hid in 0..self.hir.sources.len() {
            let mut scope = Scope::default();
            let items = self.hir.sources[hid].items.clone();
            for id in items {
                if let Some(name) = self.hir.item_name(id) {
                    let sp = self.hir.item_span(id);
                    self.declare(&mut scope, name, Decl::Item(id), sp);
                }
            }
            // imports
            let sid = self.hir.sources[hid].sid;
            let ast = self.hir.sources[hid].ast;
            for (idx, item) in ast.items.iter().enumerate() {
                let ast::ItemKind::Import(imp) = &item.kind else { continue };
                let Some(&(_, dep_sid)) = self.sess.sources[sid].imports.iter().find(|(i, _)| *i == idx) else { continue };
                let Some(&dep) = self.hir.source_map.get(&dep_sid) else { continue };
                match &imp.items {
                    ast::ImportItems::Plain(None) => {
                        if dep == hid {
                            continue;
                        }
                        let dep_scope = self.hir.sources[dep].scope.clone();
                        for name in &dep_scope.order {
                            for (d, _) in &dep_scope.names[name] {
                                self.declare(&mut scope, *name, *d, item.span);
                            }
                        }
                    }
                    ast::ImportItems::Plain(Some(alias)) | ast::ImportItems::Glob(alias) => {
                        self.declare(&mut scope, alias.name, Decl::Namespace(dep), item.span);
                    }
                    ast::ImportItems::Aliases(list) => {
                        for (name, alias) in list {
                            let found = if dep == hid { scope.get(name.name).cloned() } else { self.hir.sources[dep].scope.get(name.name).cloned() };
                            match found {
                                Some(decls) => {
                                    let n = alias.map(|a| a.name).unwrap_or(name.name);
                                    for (d, _) in decls {
                                        self.declare(&mut scope, n, d, item.span);
                                    }
                                }
                                None => {
                                    let fname = self.sess.sources[sid].file.display.clone();
                                    self.err(name.span, format!("declaration `{}` not found in {}", name.name, fname));
                                }
                            }
                        }
                    }
                }
            }
            self.hir.sources[hid].scope = scope;
            // contract scopes
            let items = self.hir.sources[hid].items.clone();
            for id in items {
                if let ItemId::Contract(cid) = id {
                    let mut cscope = Scope::default();
                    let citems = self.hir.contracts[cid].items.clone();
                    for cid2 in citems {
                        if let Some(name) = self.hir.item_name(cid2) {
                            let sp = self.hir.item_span(cid2);
                            self.declare(&mut cscope, name, Decl::Item(cid2), sp);
                        }
                    }
                    self.hir.contracts[cid].scope = cscope;
                }
            }
        }
    }

    // ------------------------------------------------------------------
    // Lookup
    // ------------------------------------------------------------------
    /// Looks up a name starting from a contract (with inheritance) then the source scope.
    pub fn lookup(&self, source: Id, contract: Option<Id>, name: Symbol) -> Option<Vec<Decl>> {
        if let Some(c) = contract {
            for &base in &self.hir.contracts[c].linearized {
                if let Some(d) = self.hir.contracts[base].scope.get(name) {
                    return Some(d.iter().map(|x| x.0).collect());
                }
            }
        }
        if let Some(d) = self.hir.sources[source].scope.get(name) {
            return Some(d.iter().map(|x| x.0).collect());
        }
        None
    }

    pub fn lookup_member(&self, decl: Decl, name: Symbol) -> Option<Vec<Decl>> {
        match decl {
            Decl::Namespace(s) => self.hir.sources[s].scope.get(name).map(|d| d.iter().map(|x| x.0).collect()),
            Decl::Item(ItemId::Contract(c)) => self.hir.contracts[c].scope.get(name).map(|d| d.iter().map(|x| x.0).collect()),
            _ => None,
        }
    }

    /// Resolves a path; emits "unresolved symbol" for the failing segment.
    pub fn resolve_path(&self, source: Id, contract: Option<Id>, path: &ast::Path) -> Option<Vec<Decl>> {
        let first = path.segments[0];
        let mut cur = match self.lookup(source, contract, first.name) {
            Some(d) => d,
            None => {
                if path.segments.len() == 1 && is_builtin_type_name(first.name) {
                    return Some(vec![Decl::Builtin(first.name)]);
                }
                self.err(first.span, format!("unresolved symbol `{}`", first.name));
                return None;
            }
        };
        for seg in &path.segments[1..] {
            let d = cur[0];
            match self.lookup_member(d, seg.name) {
                Some(n) => cur = n,
                None => {
                    self.err(seg.span, format!("unresolved symbol `{}`", seg.name));
                    return None;
                }
            }
        }
        Some(cur)
    }

    // ------------------------------------------------------------------
    // Inheritance
    // ------------------------------------------------------------------
    pub fn resolve_bases(&mut self) {
        for cid in 0..self.hir.contracts.len() {
            let c = &self.hir.contracts[cid];
            let source = c.source;
            let bases_ast = &c.ast.bases;
            let mut bases = vec![];
            for b in bases_ast {
                let Some(decls) = self.resolve_path(source, None, &b.name) else { continue };
                match decls[0] {
                    Decl::Item(ItemId::Contract(bid)) => {
                        if bid == cid {
                            self.err(b.name.span, "contracts cannot inherit from themselves");
                            continue;
                        }
                        bases.push(bid);
                    }
                    d => {
                        let found = self.decl_kind_str(d);
                        self.err(b.name.span, format!("expected contract, found {found}"));
                    }
                }
            }
            self.hir.contracts[cid].bases = bases;
        }
        // linearize in order
        let n = self.hir.contracts.len();
        let mut done = vec![false; n];
        for cid in 0..n {
            self.linearize(cid, &mut done, &mut vec![]);
        }
    }

    fn decl_kind_str(&self, d: Decl) -> &'static str {
        match d {
            Decl::Item(id) => self.hir.item_kind_str(id),
            Decl::Namespace(_) => "namespace",
            Decl::Builtin(_) => "builtin",
        }
    }

    fn linearize(&mut self, cid: Id, done: &mut Vec<bool>, stack: &mut Vec<Id>) {
        if done[cid] {
            return;
        }
        if stack.contains(&cid) {
            return;
        }
        stack.push(cid);
        let bases = self.hir.contracts[cid].bases.clone();
        for &b in &bases {
            if b >= cid && !done[b] {
                // base defined after derived
                let sp = self.hir.contracts[cid].ast.bases.iter().find(|x| true && self.path_is(&x.name, b)).map(|x| x.name.span);
                if let Some(sp) = sp {
                    self.err(sp, "definition of base has to precede definition of derived contract");
                }
            }
            self.linearize(b, done, stack);
        }
        stack.pop();
        // C3 linearization: merge(L(Bn), ..., L(B1), [Bn..B1])
        let mut seqs: Vec<Vec<Id>> = vec![];
        for &b in bases.iter().rev() {
            seqs.push(self.hir.contracts[b].linearized.clone());
        }
        seqs.push(bases.iter().rev().copied().collect());
        let mut result = vec![cid];
        loop {
            seqs.retain(|s| !s.is_empty());
            if seqs.is_empty() {
                break;
            }
            let mut found = None;
            for s in &seqs {
                let cand = s[0];
                if seqs.iter().all(|t| !t[1..].contains(&cand)) {
                    found = Some(cand);
                    break;
                }
            }
            match found {
                Some(c) => {
                    result.push(c);
                    for s in seqs.iter_mut() {
                        if s[0] == c {
                            s.remove(0);
                        }
                    }
                }
                None => {
                    let sp = self.hir.contracts[cid].name_span;
                    self.err(sp, "linearization of inheritance graph impossible");
                    result = vec![cid];
                    break;
                }
            }
        }
        self.hir.contracts[cid].linearized = result;
        done[cid] = true;
    }

    fn path_is(&self, p: &ast::Path, target: Id) -> bool {
        self.hir.contracts[target].name == p.last().name
    }

    pub fn check_inherited_conflicts(&mut self) {
        for cid in 0..self.hir.contracts.len() {
            let lin = self.hir.contracts[cid].linearized.clone();
            let mut merged: Scope = self.hir.contracts[cid].scope.clone();
            for &base in lin.iter().skip(1) {
                let bscope = self.hir.contracts[base].scope.clone();
                for name in &bscope.order {
                    for (d, sp) in &bscope.names[name] {
                        if let Some(existing) = merged.get(*name) {
                            if existing.iter().any(|(e, _)| e == d) {
                                continue;
                            }
                            if !existing.iter().all(|(e, _)| is_overloadable(*e, *d, &self.hir)) {
                                let esp = existing[0].1;
                                self.dcx.emit(
                                    Diag::new(Level::Error, format!("identifier `{}` already declared", name))
                                        .span(esp)
                                        .span_note(*sp, "previous declaration declared here"),
                                );
                                continue;
                            }
                        }
                        merged.insert_raw(*name, *d, *sp);
                    }
                }
            }
        }
    }
}

pub fn is_builtin_type_name(_s: Symbol) -> bool {
    false
}

pub fn elem_ty_of_sym(s: Symbol) -> Option<ElemTy> {
    crate::token::elementary_type_of(s)
}

