use std::collections::HashMap;

const BUILTINS: &[&str] = &[
    "msg", "block", "tx", "abi", "require", "assert", "revert", "keccak256", "sha256", "ripemd160", "ecrecover", "addmod", "mulmod", "gasleft",
    "blockhash", "blobhash", "selfdestruct",
];

pub struct LocalScopes {
    pub scopes: Vec<HashMap<Symbol, (Id, Span)>>,
}

impl LocalScopes {
    fn lookup(&self, s: Symbol) -> Option<Id> {
        for sc in self.scopes.iter().rev() {
            if let Some(&(id, _)) = sc.get(&s) {
                return Some(id);
            }
        }
        None
    }
}

pub enum EvalErr {
    Msg(&'static str, Span),
}

pub struct Ctx {
    pub source: Id,
    pub contract: Option<Id>,
    pub locals: LocalScopes,
}

impl<'a> Lowerer<'a> {
    // ------------------------------------------------------------------
    // Types
    // ------------------------------------------------------------------
    pub fn resolve_type(&mut self, source: Id, contract: Option<Id>, ty: &'a ast::Type) -> Ty {
        match &ty.kind {
            ast::TypeKind::Elementary(e) => Ty::Elem(*e),
            ast::TypeKind::Array(elem, len) => {
                let et = self.resolve_type(source, contract, elem);
                let l = match len {
                    None => None,
                    Some(e) => self.eval_array_len(source, contract, e),
                };
                if let Ty::Err = et {
                    return Ty::Err;
                }
                Ty::Array(Box::new(et), l)
            }
            ast::TypeKind::Mapping(m) => {
                let k = self.resolve_type(source, contract, &m.key);
                let v = self.resolve_type(source, contract, &m.value);
                Ty::Mapping(Box::new(k), Box::new(v))
            }
            ast::TypeKind::Function(h) => {
                let mut params = vec![];
                for p in &h.params {
                    params.push(self.resolve_type(source, contract, &p.ty));
                }
                let mut returns = vec![];
                if let Some(r) = &h.returns {
                    for p in r {
                        returns.push(self.resolve_type(source, contract, &p.ty));
                    }
                }
                Ty::Function(Box::new(FnTy {
                    params,
                    returns,
                    visibility: h.visibility.map(|v| v.0).unwrap_or(ast::Visibility::Internal),
                    mutability: h.state_mutability.map(|v| v.0).unwrap_or(ast::StateMutability::NonPayable),
                }))
            }
            ast::TypeKind::Custom(path) => {
                let Some(decls) = self.resolve_path(source, contract, path) else { return Ty::Err };
                match decls[0] {
                    Decl::Item(ItemId::Struct(s)) => Ty::Struct(s),
                    Decl::Item(ItemId::Enum(s)) => Ty::Enum(s),
                    Decl::Item(ItemId::Udvt(s)) => Ty::Udvt(s),
                    Decl::Item(ItemId::Contract(s)) => Ty::Contract(s),
                    _ => {
                        self.err(path.span, "name has to refer to a valid user-defined type");
                        Ty::Err
                    }
                }
            }
        }
    }

    fn eval_array_len(&mut self, source: Id, contract: Option<Id>, e: &'a ast::Expr) -> Option<BigUint> {
        // resolve identifiers first (unresolved symbol errors)
        let mut ctx = Ctx { source, contract, locals: LocalScopes { scopes: vec![] } };
        let before = self.dcx.err_count.get();
        self.resolve_expr(&mut ctx, e);
        if self.dcx.err_count.get() != before {
            return None;
        }
        match self.eval_const(source, contract, e, 0) {
            Ok(v) => {
                if v.is_zero() {
                    self.err(e.span, "array length must be greater than zero");
                    return None;
                }
                Some(v)
            }
            Err(EvalErr::Msg(m, sp)) => {
                if m == "rational part too large" {
                    self.err(sp, m);
                    return None;
                }
                let mut d = Diag::new(Level::Error, format!("failed to evaluate constant: {m}")).span(e.span);
                d = d.span_label(sp, "evaluation of constant value failed here");
                self.dcx.emit(d);
                None
            }
        }
    }

    pub fn eval_const(&self, source: Id, contract: Option<Id>, e: &'a ast::Expr, depth: usize) -> Result<BigUint, EvalErr> {
        let max = BigUint::one().shl(256);
        let check = |v: BigUint, sp: Span| -> Result<BigUint, EvalErr> {
            if v >= max {
                Err(EvalErr::Msg("arithmetic overflow", sp))
            } else {
                Ok(v)
            }
        };
        if depth > 64 {
            return Err(EvalErr::Msg("recursion limit reached", e.span));
        }
        match &e.kind {
            ast::ExprKind::Lit(lit, sub) => {
                let v = match &lit.kind {
                    ast::LitValue::Number(n) => n.mag.clone(),
                    ast::LitValue::Address(sym) => BigUint::parse_radix(&sym.as_str()[2..].replace('_', ""), 16).unwrap_or_default(),
                    ast::LitValue::Bool(b) => {
                        if *b {
                            BigUint::one()
                        } else {
                            BigUint::zero()
                        }
                    }
                    _ => return Err(EvalErr::Msg("unsupported literal", e.span)),
                };
                if v >= max {
                    return Err(EvalErr::Msg("rational part too large", lit.span));
                }
                let v = match sub {
                    Some((d, _)) => v.mul(&BigUint::from_u64(d.value())),
                    None => v,
                };
                check(v, e.span)
            }
            ast::ExprKind::Tuple(c) if c.len() == 1 && c[0].is_some() => self.eval_const(source, contract, c[0].as_ref().unwrap(), depth),
            ast::ExprKind::Unary(op, inner) => {
                let v = self.eval_const(source, contract, inner, depth)?;
                let mask = max.sub(&BigUint::one());
                match op {
                    ast::UnOpKind::Neg => {
                        if v.is_zero() {
                            Ok(v)
                        } else {
                            Ok(max.sub(&v))
                        }
                    }
                    ast::UnOpKind::BitNot => Ok(mask.bitxor(&v)),
                    ast::UnOpKind::Not => Ok(if v.is_zero() { BigUint::one() } else { BigUint::zero() }),
                    _ => Err(EvalErr::Msg("unsupported expression", e.span)),
                }
            }
            ast::ExprKind::Binary(l, op, r) => {
                let a = self.eval_const(source, contract, l, depth)?;
                let b = self.eval_const(source, contract, r, depth)?;
                use ast::BinOpKind::*;
                match op {
                    Add => check(a.add(&b), e.span),
                    Sub => {
                        if a < b {
                            Err(EvalErr::Msg("arithmetic overflow", e.span))
                        } else {
                            Ok(a.sub(&b))
                        }
                    }
                    Mul => check(a.mul(&b), e.span),
                    Div => {
                        if b.is_zero() {
                            Err(EvalErr::Msg("attempted to divide by zero", e.span))
                        } else {
                            Ok(a.divrem(&b).0)
                        }
                    }
                    Rem => {
                        if b.is_zero() {
                            Err(EvalErr::Msg("attempted to divide by zero", e.span))
                        } else {
                            Ok(a.divrem(&b).1)
                        }
                    }
                    Pow => {
                        if a.is_zero() || a == BigUint::one() {
                            return Ok(if b.is_zero() { BigUint::one() } else { a });
                        }
                        match b.to_u64() {
                            Some(x) if x <= 256 => check(a.pow(x), e.span),
                            _ => Err(EvalErr::Msg("arithmetic overflow", e.span)),
                        }
                    }
                    Shl => match b.to_u64() {
                        Some(x) if x < 256 => Ok(a.shl(x).bitand(&max.sub(&BigUint::one()))),
                        _ => Ok(BigUint::zero()),
                    },
                    Shr | Sar => match b.to_u64() {
                        Some(x) if x < 256 => Ok(a.shr(x)),
                        _ => Ok(BigUint::zero()),
                    },
                    BitAnd => Ok(a.bitand(&b)),
                    BitOr => Ok(a.bitor(&b)),
                    BitXor => Ok(a.bitxor(&b)),
                    _ => Err(EvalErr::Msg("unsupported expression", e.span)),
                }
            }
            ast::ExprKind::Ident(id) => {
                let Some(decls) = self.lookup(source, contract, id.name) else {
                    return Err(EvalErr::Msg("unsupported expression", e.span));
                };
                match decls[0] {
                    Decl::Item(ItemId::Var(v)) => {
                        let var = &self.hir.vars[v];
                        if !var.is_constant {
                            return Err(EvalErr::Msg("only constant variables are allowed", e.span));
                        }
                        let Some(init) = &var.ast.initializer else {
                            return Err(EvalErr::Msg("unsupported expression", e.span));
                        };
                        self.eval_const(var.source, var.contract, init, depth + 1)
                    }
                    _ => Err(EvalErr::Msg("unsupported expression", e.span)),
                }
            }
            _ => Err(EvalErr::Msg("unsupported expression", e.span)),
        }
    }

    // ------------------------------------------------------------------
    // Expressions & statements
    // ------------------------------------------------------------------
    fn lookup_ident(&self, ctx: &Ctx, name: Symbol) -> bool {
        if ctx.locals.lookup(name).is_some() {
            return true;
        }
        if self.lookup(ctx.source, ctx.contract, name).is_some() {
            return true;
        }
        if (name == kw::This || name == kw::Super) && ctx.contract.is_some() {
            return true;
        }
        BUILTINS.contains(&name.as_str())
    }

    pub fn resolve_expr(&mut self, ctx: &mut Ctx, e: &'a ast::Expr) {
        use ast::ExprKind::*;
        match &e.kind {
            Ident(id) => {
                if !self.lookup_ident(ctx, id.name) {
                    self.err(id.span, format!("unresolved symbol `{}`", id.name));
                }
            }
            Array(v) => {
                for x in v {
                    self.resolve_expr(ctx, x);
                }
            }
            Assign(l, _, r) | Binary(l, _, r) => {
                self.resolve_expr(ctx, l);
                self.resolve_expr(ctx, r);
            }
            Call(c, args) => {
                self.resolve_expr(ctx, c);
                self.resolve_call_args(ctx, args);
            }
            CallOptions(c, opts) => {
                self.resolve_expr(ctx, c);
                for o in opts {
                    self.resolve_expr(ctx, &o.value);
                }
            }
            Delete(x) | Unary(_, x) => self.resolve_expr(ctx, x),
            Index(b, k) => {
                self.resolve_expr(ctx, b);
                match k {
                    ast::IndexKind::Index(Some(i)) => self.resolve_expr(ctx, i),
                    ast::IndexKind::Index(None) => {}
                    ast::IndexKind::Range(s, t) => {
                        if let Some(s) = s {
                            self.resolve_expr(ctx, s);
                        }
                        if let Some(t) = t {
                            self.resolve_expr(ctx, t);
                        }
                    }
                }
            }
            Lit(..) => {}
            Member(b, _) => self.resolve_expr(ctx, b),
            New(t) | TypeCall(t) | Type(t) => {
                let _ = self.resolve_type(ctx.source, ctx.contract, t);
            }
            Payable(args) => self.resolve_call_args(ctx, args),
            Ternary(a, b, c) => {
                self.resolve_expr(ctx, a);
                self.resolve_expr(ctx, b);
                self.resolve_expr(ctx, c);
            }
            Tuple(v) => {
                for x in v.iter().flatten() {
                    self.resolve_expr(ctx, x);
                }
            }
        }
    }

    fn resolve_call_args(&mut self, ctx: &mut Ctx, args: &'a ast::CallArgs) {
        for a in args.exprs() {
            self.resolve_expr(ctx, a);
        }
    }

    fn declare_local(&mut self, ctx: &mut Ctx, v: Id) {
        let var = &self.hir.vars[v];
        let Some(name) = var.name else { return };
        let sp = var.name_span;
        let scope = ctx.locals.scopes.last_mut().unwrap();
        if let Some(&(_, prev)) = scope.get(&name) {
            self.dcx.emit(Diag::new(Level::Error, format!("identifier `{}` already declared", name)).span(sp).span_note(prev, "previous declaration declared here"));
            return;
        }
        scope.insert(name, (v, sp));
    }

    fn new_local(&mut self, ctx: &mut Ctx, v: &'a ast::VarDecl) -> Id {
        let id = self.new_var_pub(ctx.source, ctx.contract, v, VarKind::Local);
        let ty = self.resolve_type(ctx.source, ctx.contract, &v.ty);
        self.hir.vars[id].ty = ty;
        id
    }

    pub fn resolve_block(&mut self, ctx: &mut Ctx, b: &'a ast::Block) {
        ctx.locals.scopes.push(HashMap::new());
        for s in &b.stmts {
            self.resolve_stmt(ctx, s);
        }
        ctx.locals.scopes.pop();
    }

    fn resolve_scoped_stmt(&mut self, ctx: &mut Ctx, s: &'a ast::Stmt) {
        ctx.locals.scopes.push(HashMap::new());
        self.resolve_stmt(ctx, s);
        ctx.locals.scopes.pop();
    }

    pub fn resolve_stmt(&mut self, ctx: &mut Ctx, s: &'a ast::Stmt) {
        use ast::StmtKind::*;
        match &s.kind {
            Assembly(_) => {}
            DeclSingle(v) => {
                let id = self.new_local(ctx, v);
                if let Some(init) = &v.initializer {
                    self.resolve_expr(ctx, init);
                }
                self.declare_local(ctx, id);
            }
            DeclMulti(vars, e) => {
                let mut ids = vec![];
                for v in vars.iter().flatten() {
                    ids.push(self.new_local(ctx, v));
                }
                self.resolve_expr(ctx, e);
                for id in ids {
                    self.declare_local(ctx, id);
                }
            }
            Block(b) | UncheckedBlock(b) => self.resolve_block(ctx, b),
            Break | Continue | Placeholder => {}
            DoWhile(body, cond) => {
                self.resolve_scoped_stmt(ctx, body);
                self.resolve_expr(ctx, cond);
            }
            Emit(path, args) | Revert(path, args) => {
                if self.resolve_path_expr(ctx, path) {
                    self.resolve_call_args(ctx, args);
                }
            }
            Expr(e) => self.resolve_expr(ctx, e),
            For(init, cond, next, body) => {
                ctx.locals.scopes.push(HashMap::new());
                if let Some(i) = init {
                    self.resolve_stmt(ctx, i);
                }
                if let Some(c) = cond {
                    self.resolve_expr(ctx, c);
                }
                self.resolve_scoped_stmt(ctx, body);
                if let Some(n) = next {
                    self.resolve_expr(ctx, n);
                }
                ctx.locals.scopes.pop();
            }
            If(c, t, e) => {
                self.resolve_expr(ctx, c);
                self.resolve_scoped_stmt(ctx, t);
                if let Some(e) = e {
                    self.resolve_scoped_stmt(ctx, e);
                }
            }
            Return(e) => {
                if let Some(e) = e {
                    self.resolve_expr(ctx, e);
                }
            }
            Try(t) => {
                self.resolve_expr(ctx, &t.expr);
                ctx.locals.scopes.push(HashMap::new());
                for v in &t.returns {
                    let id = self.new_local(ctx, v);
                    self.declare_local(ctx, id);
                }
                self.resolve_block(ctx, &t.block);
                ctx.locals.scopes.pop();
                for c in &t.catch {
                    ctx.locals.scopes.push(HashMap::new());
                    for v in &c.args {
                        let id = self.new_local(ctx, v);
                        self.declare_local(ctx, id);
                    }
                    self.resolve_block(ctx, &c.block);
                    ctx.locals.scopes.pop();
                }
            }
            While(c, b) => {
                self.resolve_expr(ctx, c);
                self.resolve_scoped_stmt(ctx, b);
            }
        }
    }

    /// Resolves a path used in expression position (emit/revert/modifiers). Returns success.
    fn resolve_path_expr(&mut self, ctx: &Ctx, path: &ast::Path) -> bool {
        let first = path.segments[0];
        if path.segments.len() == 1 && ctx.locals.lookup(first.name).is_some() {
            return true;
        }
        if ctx.locals.lookup(first.name).is_some() {
            return true;
        }
        if self.lookup(ctx.source, ctx.contract, first.name).is_none() && BUILTINS.contains(&first.name.as_str()) {
            return true;
        }
        self.resolve_path(ctx.source, ctx.contract, path).is_some()
    }

    // ------------------------------------------------------------------
    // Driver for resolution of all items
    // ------------------------------------------------------------------
    pub fn resolve_all(&mut self) {
        // UDVTs
        for i in 0..self.hir.udvts.len() {
            let u = &self.hir.udvts[i];
            let (s, c, ast) = (u.source, u.contract, u.ast);
            let ty = self.resolve_type(s, c, &ast.ty);
            self.hir.udvts[i].ty = ty;
        }
        // structs
        for i in 0..self.hir.structs.len() {
            let fields = self.hir.structs[i].fields.clone();
            self.resolve_var_types(&fields);
        }
        for i in 0..self.hir.errors.len() {
            let p = self.hir.errors[i].params.clone();
            self.resolve_var_types(&p);
        }
        for i in 0..self.hir.events.len() {
            let p = self.hir.events[i].params.clone();
            self.resolve_var_types(&p);
        }
        // state and global variables
        let nvars = self.hir.vars.len();
        for i in 0..nvars {
            let v = &self.hir.vars[i];
            if !matches!(v.kind, VarKind::State | VarKind::Global) {
                continue;
            }
            let (s, c, ast) = (v.source, v.contract, v.ast);
            if let Some(init) = &ast.initializer {
                let mut ctx = Ctx { source: s, contract: c, locals: LocalScopes { scopes: vec![] } };
                self.resolve_expr(&mut ctx, init);
            }
            let ty = self.resolve_type(s, c, &ast.ty);
            self.hir.vars[i].ty = ty;
        }
        // functions
        for i in 0..self.hir.functions.len() {
            self.resolve_function(i);
        }
        // base constructor arguments in inheritance specifiers
        for cid in 0..self.hir.contracts.len() {
            let c = &self.hir.contracts[cid];
            let (s, ast) = (c.source, c.ast);
            let mut ctx = Ctx { source: s, contract: Some(cid), locals: LocalScopes { scopes: vec![] } };
            for b in &ast.bases {
                if let Some(args) = &b.args {
                    self.resolve_call_args(&mut ctx, args);
                }
            }
        }
        // UDVT underlying type check
        for i in 0..self.hir.udvts.len() {
            let ok = match &self.hir.udvts[i].ty {
                Ty::Elem(e) => !matches!(e, crate::token::ElemTy::String | crate::token::ElemTy::Bytes),
                _ => false,
            };
            if !ok {
                let sp = self.hir.udvts[i].ast.ty.span;
                self.err(sp, "the underlying type of UDVTs must be an elementary value type");
            }
        }
    }

    fn resolve_var_types(&mut self, vars: &[Id]) {
        for &v in vars {
            let var = &self.hir.vars[v];
            let (s, c, ast) = (var.source, var.contract, var.ast);
            let ty = self.resolve_type(s, c, &ast.ty);
            self.hir.vars[v].ty = ty;
        }
    }

    fn resolve_function(&mut self, fid: Id) {
        let f = &self.hir.functions[fid];
        let (s, c, ast) = (f.source, f.contract, f.ast);
        let params = f.params.clone();
        let returns = f.returns.clone();
        let mut ctx = Ctx { source: s, contract: c, locals: LocalScopes { scopes: vec![HashMap::new()] } };
        for &p in &params {
            let var = &self.hir.vars[p];
            let ty = self.resolve_type(s, c, &var.ast.ty);
            self.hir.vars[p].ty = ty;
            self.declare_local(&mut ctx, p);
        }
        for m in &ast.header.modifiers {
            if self.resolve_path_expr(&ctx, &m.name) {
                if let Some(args) = &m.args {
                    self.resolve_call_args(&mut ctx, args);
                }
            }
        }
        for &p in &returns {
            let var = &self.hir.vars[p];
            let ty = self.resolve_type(s, c, &var.ast.ty);
            self.hir.vars[p].ty = ty;
            self.declare_local(&mut ctx, p);
        }
        if let Some(body) = &ast.body {
            self.resolve_block(&mut ctx, body);
        }
    }

    pub fn new_var_pub(&mut self, source: Id, contract: Option<Id>, v: &'a ast::VarDecl, kind: VarKind) -> Id {
        let id = self.hir.vars.len();
        self.hir.vars.push(VarH {
            source,
            contract,
            ast: v,
            name: v.name.map(|n| n.name),
            name_span: v.name.map(|n| n.span).unwrap_or(v.ty.span),
            kind,
            ty: Ty::Err,
            visibility: ast::Visibility::Internal,
            is_constant: false,
            is_immutable: false,
        });
        id
    }
}

