use super::hir::*;
use crate::ast;
use crate::json::Json;
use crate::token::ElemTy;

pub fn elem_abi(e: &ElemTy) -> String {
    match e {
        ElemTy::Address(_) => "address".into(),
        ElemTy::Bool => "bool".into(),
        ElemTy::String => "string".into(),
        ElemTy::Bytes => "bytes".into(),
        ElemTy::Fixed(m, n) => format!("fixed{m}x{n}"),
        ElemTy::UFixed(m, n) => format!("ufixed{m}x{n}"),
        ElemTy::Int(n) => format!("int{n}"),
        ElemTy::UInt(n) => format!("uint{n}"),
        ElemTy::FixedBytes(n) => format!("bytes{n}"),
    }
}

pub fn elem_internal(e: &ElemTy) -> String {
    match e {
        ElemTy::Address(true) => "address payable".into(),
        _ => elem_abi(e),
    }
}

impl<'a> Hir<'a> {
    pub fn canonical_name(&self, contract: Option<Id>, name: crate::symbol::Symbol) -> String {
        match contract {
            Some(c) => format!("{}.{}", self.contracts[c].name, name),
            None => name.to_string(),
        }
    }

    pub fn contains_mapping(&self, t: &Ty) -> bool {
        self.contains_mapping_rec(t, &mut vec![])
    }

    fn contains_mapping_rec(&self, t: &Ty, seen: &mut Vec<Id>) -> bool {
        match t {
            Ty::Mapping(..) => true,
            Ty::Array(e, _) => self.contains_mapping_rec(e, seen),
            Ty::Struct(s) => {
                if seen.contains(s) {
                    return false;
                }
                seen.push(*s);
                let r = self.structs[*s].fields.iter().any(|&f| self.contains_mapping_rec(&self.vars[f].ty.clone(), seen));
                seen.pop();
                r
            }
            _ => false,
        }
    }

    /// ABI "type" string (with tuple for structs).
    pub fn abi_type(&self, t: &Ty) -> String {
        match t {
            Ty::Elem(e) => elem_abi(e),
            Ty::Array(e, n) => {
                let inner = self.abi_type(e);
                match n {
                    Some(n) => format!("{inner}[{}]", n.to_string_radix(10)),
                    None => format!("{inner}[]"),
                }
            }
            Ty::Struct(_) => "tuple".into(),
            Ty::Enum(_) => "uint8".into(),
            Ty::Udvt(u) => self.abi_type(&self.udvts[*u].ty),
            Ty::Contract(_) => "address".into(),
            Ty::Function(_) => "function".into(),
            Ty::Mapping(..) | Ty::Err => "".into(),
        }
    }

    /// Signature type (tuples expanded).
    pub fn sig_type(&self, t: &Ty) -> String {
        match t {
            Ty::Array(e, n) => {
                let inner = self.sig_type(e);
                match n {
                    Some(n) => format!("{inner}[{}]", n.to_string_radix(10)),
                    None => format!("{inner}[]"),
                }
            }
            Ty::Struct(s) => {
                let parts: Vec<String> = self.structs[*s].fields.iter().map(|&f| self.sig_type(&self.vars[f].ty)).collect();
                format!("({})", parts.join(","))
            }
            _ => self.abi_type(t),
        }
    }

    pub fn internal_type(&self, t: &Ty) -> String {
        match t {
            Ty::Elem(e) => elem_internal(e),
            Ty::Array(e, n) => {
                let inner = self.internal_type(e);
                match n {
                    Some(n) => format!("{inner}[{}]", n.to_string_radix(10)),
                    None => format!("{inner}[]"),
                }
            }
            Ty::Struct(s) => format!("struct {}", self.canonical_name(self.structs[*s].contract, self.structs[*s].name)),
            Ty::Enum(s) => format!("enum {}", self.canonical_name(self.enums[*s].contract, self.enums[*s].name)),
            Ty::Udvt(s) => self.canonical_name(self.udvts[*s].contract, self.udvts[*s].name),
            Ty::Contract(c) => format!("contract {}", self.contracts[*c].name),
            Ty::Function(f) => {
                let ps: Vec<String> = f.params.iter().map(|p| self.internal_type_plain(p)).collect();
                let mut s = format!("function ({})", ps.join(","));
                if f.mutability != ast::StateMutability::NonPayable {
                    s.push(' ');
                    s.push_str(f.mutability.as_str());
                }
                s.push(' ');
                s.push_str(f.visibility.as_str());
                if !f.returns.is_empty() {
                    let rs: Vec<String> = f.returns.iter().map(|p| self.internal_type_plain(p)).collect();
                    s.push_str(&format!(" returns ({})", rs.join(",")));
                }
                s
            }
            Ty::Mapping(k, v) => format!("mapping({} => {})", self.internal_type(k), self.internal_type(v)),
            Ty::Err => "".into(),
        }
    }

    fn internal_type_plain(&self, t: &Ty) -> String {
        self.internal_type(t)
    }

    pub fn abi_param(&self, name: &str, t: &Ty, indexed: Option<bool>) -> Json {
        let mut obj = vec![("name".to_string(), Json::Str(name.to_string())), ("type".to_string(), Json::Str(self.abi_type(t)))];
        if let Some(i) = indexed {
            obj.push(("indexed".into(), Json::Bool(i)));
        }
        obj.push(("internalType".into(), Json::Str(self.internal_type(t))));
        if let Some(sid) = struct_of(t) {
            let comps: Vec<Json> = self.structs[sid]
                .fields
                .iter()
                .map(|&f| {
                    let v = &self.vars[f];
                    self.abi_param(v.name.map(|n| n.as_str()).unwrap_or(""), &v.ty, None)
                })
                .collect();
            obj.push(("components".into(), Json::Arr(comps)));
        }
        Json::Obj(obj)
    }

    fn params_json(&self, vars: &[Id], indexed: bool) -> Json {
        Json::Arr(
            vars.iter()
                .map(|&v| {
                    let var = &self.vars[v];
                    self.abi_param(var.name.map(|n| n.as_str()).unwrap_or(""), &var.ty, if indexed { Some(var.ast.indexed) } else { None })
                })
                .collect(),
        )
    }

    pub fn fn_selector_sig(&self, fid: Id) -> String {
        let f = &self.functions[fid];
        let ps: Vec<String> = f.params.iter().map(|&p| self.sig_type(&self.vars[p].ty)).collect();
        format!("{}({})", f.name.map(|n| n.as_str()).unwrap_or(""), ps.join(","))
    }

    /// Getter (inputs, outputs) for a public state variable.
    pub fn getter_types(&self, vid: Id) -> (Vec<Ty>, Vec<(String, Ty)>) {
        let mut inputs = vec![];
        let mut t = self.vars[vid].ty.clone();
        loop {
            match t {
                Ty::Mapping(k, v) => {
                    inputs.push(*k);
                    t = *v;
                }
                Ty::Array(e, _) => {
                    inputs.push(Ty::Elem(ElemTy::UInt(256)));
                    t = *e;
                }
                _ => break,
            }
        }
        let outputs = match &t {
            Ty::Struct(s) => self.structs[*s]
                .fields
                .iter()
                .filter(|&&f| !matches!(self.vars[f].ty, Ty::Mapping(..) | Ty::Array(..)))
                .map(|&f| (self.vars[f].name.map(|n| n.to_string()).unwrap_or_default(), self.vars[f].ty.clone()))
                .collect(),
            _ => vec![(String::new(), t.clone())],
        };
        (inputs, outputs)
    }

    pub fn getter_sig(&self, vid: Id) -> String {
        let (inputs, _) = self.getter_types(vid);
        let ps: Vec<String> = inputs.iter().map(|t| self.sig_type(t)).collect();
        format!("{}({})", self.vars[vid].name.map(|n| n.as_str()).unwrap_or(""), ps.join(","))
    }

    fn fn_has_mapping_params(&self, fid: Id) -> bool {
        let f = &self.functions[fid];
        f.params.iter().chain(f.returns.iter()).any(|&p| self.contains_mapping(&self.vars[p].ty))
    }

    /// Externally visible functions: (signature, kind) in ABI order (derived first).
    pub fn interface_functions(&self, cid: Id) -> Vec<(String, Result<Id, Id>)> {
        let mut out: Vec<(String, Result<Id, Id>)> = vec![];
        let mut seen: Vec<String> = vec![];
        for &c in &self.contracts[cid].linearized {
            for &item in &self.contracts[c].items {
                match item {
                    ItemId::Function(f) => {
                        let fh = &self.functions[f];
                        if fh.kind != ast::FunctionKind::Function {
                            continue;
                        }
                        if !matches!(fh.visibility, ast::Visibility::Public | ast::Visibility::External) {
                            continue;
                        }
                        if self.fn_has_mapping_params(f) {
                            continue;
                        }
                        let sig = self.fn_selector_sig(f);
                        if seen.contains(&sig) {
                            continue;
                        }
                        seen.push(sig.clone());
                        out.push((sig, Ok(f)));
                    }
                    ItemId::Var(v) => {
                        let vh = &self.vars[v];
                        if vh.kind != VarKind::State || vh.visibility != ast::Visibility::Public {
                            continue;
                        }
                        let sig = self.getter_sig(v);
                        if seen.contains(&sig) {
                            continue;
                        }
                        seen.push(sig.clone());
                        out.push((sig, Err(v)));
                    }
                    _ => {}
                }
            }
        }
        out
    }

    pub fn contract_abi(&self, cid: Id) -> Json {
        let c = &self.contracts[cid];
        let mut items: Vec<(&'static str, String, Json)> = vec![];
        // constructor
        if c.kind == ast::ContractKind::Contract {
            if let Some(ctor) = c.ctor {
                let f = &self.functions[ctor];
                let sm = if f.mutability == ast::StateMutability::Payable { "payable" } else { "nonpayable" };
                items.push((
                    "constructor",
                    String::new(),
                    Json::Obj(vec![
                        ("type".into(), Json::Str("constructor".into())),
                        ("inputs".into(), self.params_json(&f.params, false)),
                        ("stateMutability".into(), Json::Str(sm.into())),
                    ]),
                ));
            }
        }
        // functions and getters
        for (_, f) in self.interface_functions(cid) {
            match f {
                Ok(fid) => {
                    let fh = &self.functions[fid];
                    items.push((
                        "function",
                        fh.name.map(|n| n.to_string()).unwrap_or_default(),
                        Json::Obj(vec![
                            ("type".into(), Json::Str("function".into())),
                            ("name".into(), Json::Str(fh.name.map(|n| n.to_string()).unwrap_or_default())),
                            ("inputs".into(), self.params_json(&fh.params, false)),
                            ("outputs".into(), self.params_json(&fh.returns, false)),
                            ("stateMutability".into(), Json::Str(fh.mutability.as_str().into())),
                        ]),
                    ));
                }
                Err(vid) => {
                    let (ins, outs) = self.getter_types(vid);
                    let name = self.vars[vid].name.map(|n| n.to_string()).unwrap_or_default();
                    items.push((
                        "function",
                        name.clone(),
                        Json::Obj(vec![
                            ("type".into(), Json::Str("function".into())),
                            ("name".into(), Json::Str(name)),
                            ("inputs".into(), Json::Arr(ins.iter().map(|t| self.abi_param("", t, None)).collect())),
                            ("outputs".into(), Json::Arr(outs.iter().map(|(n, t)| self.abi_param(n, t, None)).collect())),
                            ("stateMutability".into(), Json::Str("view".into())),
                        ]),
                    ));
                }
            }
        }
        // fallback / receive
        for &b in &c.linearized {
            if let Some(f) = self.contracts[b].fallback {
                let fh = &self.functions[f];
                let sm = if fh.mutability == ast::StateMutability::Payable { "payable" } else { "nonpayable" };
                items.push(("fallback", String::new(), Json::Obj(vec![("type".into(), Json::Str("fallback".into())), ("stateMutability".into(), Json::Str(sm.into()))])));
                break;
            }
        }
        for &b in &c.linearized {
            if let Some(_) = self.contracts[b].receive {
                items.push(("receive", String::new(), Json::Obj(vec![("type".into(), Json::Str("receive".into())), ("stateMutability".into(), Json::Str("payable".into()))])));
                break;
            }
        }
        // events and errors
        let mut seen_ev: Vec<Id> = vec![];
        let mut seen_er: Vec<Id> = vec![];
        for &b in &c.linearized {
            for &item in &self.contracts[b].items {
                match item {
                    ItemId::Event(e) => {
                        if seen_ev.contains(&e) {
                            continue;
                        }
                        seen_ev.push(e);
                        let eh = &self.events[e];
                        items.push((
                            "event",
                            eh.name.to_string(),
                            Json::Obj(vec![
                                ("type".into(), Json::Str("event".into())),
                                ("name".into(), Json::Str(eh.name.to_string())),
                                ("inputs".into(), self.params_json(&eh.params, true)),
                                ("anonymous".into(), Json::Bool(eh.anonymous)),
                            ]),
                        ));
                    }
                    ItemId::Error(e) => {
                        if seen_er.contains(&e) {
                            continue;
                        }
                        seen_er.push(e);
                        let eh = &self.errors[e];
                        items.push((
                            "error",
                            eh.name.to_string(),
                            Json::Obj(vec![
                                ("type".into(), Json::Str("error".into())),
                                ("name".into(), Json::Str(eh.name.to_string())),
                                ("inputs".into(), self.params_json(&eh.params, false)),
                            ]),
                        ));
                    }
                    _ => {}
                }
            }
        }
        items.sort_by(|a, b| (a.0, &a.1).cmp(&(b.0, &b.1)));
        Json::Arr(items.into_iter().map(|x| x.2).collect())
    }

    pub fn contract_hashes(&self, cid: Id) -> Json {
        let mut v: Vec<(String, String)> = vec![];
        for (sig, _) in self.interface_functions(cid) {
            let h = crate::keccak::keccak256(sig.as_bytes());
            v.push((sig, crate::keccak::hex(&h[..4])));
        }
        v.sort();
        Json::Obj(v.into_iter().map(|(k, h)| (k, Json::Str(h))).collect())
    }
}

fn struct_of(t: &Ty) -> Option<Id> {
    match t {
        Ty::Struct(s) => Some(*s),
        Ty::Array(e, _) => struct_of(e),
        _ => None,
    }
}
