                        ("type".into(), Json::Str("constructor".into())),
                        ("inputs".into(), self.params_json(&f.params, false)),
                        ("stateMutability".into(), Json::Str(sm.into())),
                    ]),
                ));
            }
        }
        // functions and getters
        for (_, f) in self.interface_functions(cid) {
            match f {
                Ok(fid) => {
                    let fh = &self.functions[fid];
                    items.push((
                        "function",
                        fh.name.map(|n| n.to_string()).unwrap_or_default(),
                        Json::Obj(vec![
                            ("type".into(), Json::Str("function".into())),
                            ("name".into(), Json::Str(fh.name.map(|n| n.to_string()).unwrap_or_default())),
                            ("inputs".into(), self.params_json(&fh.params, false)),
                            ("outputs".into(), self.params_json(&fh.returns, false)),
                            ("stateMutability".into(), Json::Str(fh.mutability.as_str().into())),
                        ]),
                    ));
                }
                Err(vid) => {
                    let (ins, outs) = self.getter_types(vid);
                    let name = self.vars[vid].name.map(|n| n.to_string()).unwrap_or_default();
                    items.push((
                        "function",
                        name.clone(),
                        Json::Obj(vec![
                            ("type".into(), Json::Str("function".into())),
                            ("name".into(), Json::Str(name)),
                            ("inputs".into(), Json::Arr(ins.iter().map(|t| self.abi_param("", t, None)).collect())),
                            ("outputs".into(), Json::Arr(outs.iter().map(|(n, t)| self.abi_param(n, t, None)).collect())),
                            ("stateMutability".into(), Json::Str("view".into())),
                        ]),
                    ));
                }
            }
        }
        // fallback / receive
        for &b in &c.linearized {
            if let Some(f) = self.contracts[b].fallback {
                let fh = &self.functions[f];
                let sm = if fh.mutability == ast::StateMutability::Payable { "payable" } else { "nonpayable" };
                items.push(("fallback", String::new(), Json::Obj(vec![("type".into(), Json::Str("fallback".into())), ("stateMutability".into(), Json::Str(sm.into()))])));
                break;
            }
        }
        for &b in &c.linearized {
            if let Some(_) = self.contracts[b].receive {
                items.push(("receive", String::new(), Json::Obj(vec![("type".into(), Json::Str("receive".into())), ("stateMutability".into(), Json::Str("payable".into()))])));
                break;
            }
        }
        // events and errors
        let mut seen_ev: Vec<Id> = vec![];
        let mut seen_er: Vec<Id> = vec![];
        for &b in &c.linearized {
            for &item in &self.contracts[b].items {
                match item {
                    ItemId::Event(e) => {
                        if seen_ev.contains(&e) {
                            continue;
                        }
                        seen_ev.push(e);
                        let eh = &self.events[e];
                        items.push((
                            "event",
                            eh.name.to_string(),
                            Json::Obj(vec![
                                ("type".into(), Json::Str("event".into())),
                                ("name".into(), Json::Str(eh.name.to_string())),
                                ("inputs".into(), self.params_json(&eh.params, true)),
                                ("anonymous".into(), Json::Bool(eh.anonymous)),
                            ]),
                        ));
                    }
                    ItemId::Error(e) => {
                        if seen_er.contains(&e) {
                            continue;
                        }
                        seen_er.push(e);
                        let eh = &self.errors[e];
                        items.push((
                            "error",
                            eh.name.to_string(),
                            Json::Obj(vec![
                                ("type".into(), Json::Str("error".into())),
                                ("name".into(), Json::Str(eh.name.to_string())),
                                ("inputs".into(), self.params_json(&eh.params, false)),
                            ]),
                        ));
                    }
                    _ => {}
                }
            }
        }
        items.sort_by(|a, b| (a.0, &a.1).cmp(&(b.0, &b.1)));
        Json::Arr(items.into_iter().map(|x| x.2).collect())
    }

    pub fn contract_hashes(&self, cid: Id) -> Json {
        let mut v: Vec<(String, String)> = vec![];
        for (sig, _) in self.interface_functions(cid) {
            let h = crate::keccak::keccak256(sig.as_bytes());
            v.push((sig, crate::keccak::hex(&h[..4])));
        }
        v.sort();
        Json::Obj(v.into_iter().map(|(k, h)| (k, Json::Str(h))).collect())
    }
}

fn struct_of(t: &Ty) -> Option<Id> {
    match t {
        Ty::Struct(s) => Some(*s),
        Ty::Array(e, _) => struct_of(e),
        _ => None,
    }
}
