cat > mod.rs <<'EOF'
pub mod abi;
pub mod hir;
pub mod lower;
pub mod resolve;

use crate::driver::Session;
use crate::json::Json;
use std::io::Write;

pub fn run(sess: &mut Session) -> i32 {
    let order = lower::topo_order(sess);
    let sess: &Session = sess;
    let mut lw = lower::Lowerer::new(sess);
    lw.collect(&order);
    lw.build_scopes();
    lw.resolve_bases();
    lw.check_inherited_conflicts();
    lw.resolve_all();
    if sess.dcx.has_errors() {
        sess.dcx.print_summary();
        return 1;
    }
    let hir = lw.hir;
    // emit
    if !sess.args.emit.is_empty() {
        let mut contracts: Vec<(String, Json)> = vec![];
        for cid in 0..hir.contracts.len() {
            let c = &hir.contracts[cid];
            let sid = hir.sources[c.source].sid;
            let key = format!("{}:{}", sess.sources[sid].file.display, c.name);
            let mut obj = vec![];
            if sess.args.emit.iter().any(|e| e == "abi") {
                obj.push(("abi".to_string(), hir.contract_abi(cid)));
            }
            if sess.args.emit.iter().any(|e| e == "hashes") {
                obj.push(("hashes".to_string(), hir.contract_hashes(cid)));
            }
            contracts.push((key, Json::Obj(obj)));
        }
        contracts.sort_by(|a, b| a.0.cmp(&b.0));
        let mut top = vec![];
        if !contracts.is_empty() {
            top.push(("contracts".to_string(), Json::Obj(contracts)));
        }
        top.push(("version".to_string(), Json::Str("0.1.8".into())));
        let j = Json::Obj(top);
        let s = if sess.args.pretty_json { j.to_pretty() } else { j.to_compact() };
        if let Some(dir) = &sess.args.out_dir {
            let path = std::path::Path::new(dir).join("combined.json");
            if let Err(e) = std::fs::write(&path, s.as_bytes()) {
                let msg = format!("failed to write to output: {}", io_err_str(&e));
                sess.dcx.emit(crate::diag::Diag::new(crate::diag::Level::Error, msg));
                sess.dcx.print_summary();
                return 1;
            }
        } else {
            let mut out = std::io::stdout();
            let _ = out.write_all(s.as_bytes());
            let _ = out.flush();
        }
    }
    if sess.dcx.has_errors() {
        sess.dcx.print_summary();
        return 1;
    }
    0
}

pub fn io_err_str(e: &std::io::Error) -> String {
    let code = e.raw_os_error();
    let desc = match e.kind() {
        std::io::ErrorKind::NotFound => "No such file or directory".to_string(),
        std::io::ErrorKind::PermissionDenied => "Permission denied".to_string(),
        _ => e.to_string(),
    };
    match code {
        Some(c) => format!("{} (os error {})", desc, c),
        None => desc,
    }
}
