// AST validation pass.
use crate::ast::*;
use crate::diag::{Diag, DiagCtxt, Level};
use crate::num::{BigInt, BigUint};
use crate::source_map::{SourceMap, Span};
use crate::symbol::kw;

pub struct Validator<'a> {
    pub dcx: &'a DiagCtxt,
    pub sm: &'a SourceMap,
    in_loop: usize,
    in_unchecked: bool,
    in_modifier: bool,
    found_placeholder: bool,
    contract: Option<&'a Contract>,
}

impl<'a> Validator<'a> {
    pub fn new(dcx: &'a DiagCtxt, sm: &'a SourceMap) -> Self {
        Validator { dcx, sm, in_loop: 0, in_unchecked: false, in_modifier: false, found_placeholder: false, contract: None }
    }

    fn err(&self, sp: Span, msg: impl Into<String>) {
        self.dcx.emit(Diag::new(Level::Error, msg).span(sp));
    }

    pub fn visit_source(&mut self, su: &'a SourceUnit) {
        for item in &su.items {
            self.visit_item(item);
        }
    }

    fn visit_item(&mut self, item: &'a Item) {
        match &item.kind {
            ItemKind::Pragma(p) => self.check_pragma(item, p),
            ItemKind::Import(_) => {}
            ItemKind::Using(u) => {
                if self.contract.is_none() {
                    if u.ty.is_none() {
                        self.err(item.span, "the type has to be specified explicitly at file level (cannot use `*`)");
                    }
                } else if u.global {
                    self.err(item.span, "`global` can only be used at file level");
                }
            }
            ItemKind::Contract(c) => {
                if c.kind == ContractKind::Library && !c.bases.is_empty() {
                    self.err(c.name.span, "library is not allowed to inherit");
                }
                if let Some(l) = &c.layout {
                    if c.kind != ContractKind::Contract && c.kind != ContractKind::AbstractContract {
                        let _ = l;
                        self.err(layout_span(c), "storage layout is only allowed for contracts");
                    }
                }
                for b in &c.bases {
                    if let Some(args) = &b.args {
                        for e in args.exprs() {
                            self.visit_expr(e);
                        }
                    }
                }
                if let Some(l) = &c.layout {
                    self.visit_expr(l);
                }
                let old = self.contract.replace(c);
                for sub in &c.body {
                    self.visit_item(sub);
                }
                self.contract = old;
            }
            ItemKind::Function(f) => self.visit_function(item, f),
            ItemKind::Variable(v) => {
                if let Some(c) = self.contract {
                    if c.kind == ContractKind::Library && !matches!(v.mutability, Some((VarMut::Constant, _))) {
                        self.err(v.span, "library cannot have non-constant state variable");
                    }
                }
                self.visit_var(v);
            }
            ItemKind::Struct(s) => {
                for f in &s.fields {
                    self.visit_var(f);
                }
                if s.fields.is_empty() {
                    self.err(s.name.span, "structs must have at least one field");
                }
            }
            ItemKind::Enum(e) => {
                if e.variants.is_empty() {
                    self.err(e.name.span, "enum must have at least one variant");
                }
            }
            ItemKind::Udvt(_) => {}
            ItemKind::Error(e) => {
                for p in &e.params {
                    self.visit_var(p);
                }
            }
            ItemKind::Event(e) => {
                for p in &e.params {
                    self.visit_var(p);
                }
            }
        }
    }

    fn check_pragma(&self, item: &Item, p: &Pragma) {
        match &p.tokens {
            PragmaTokens::Version(name, _) => {
                if name.name != kw::Solidity {
                    self.err(name.span, "only `solidity` is supported as a version pragma");
                }
            }
            PragmaTokens::Custom(name, value) => {
                let ok = match (name.as_str(), value.as_deref()) {
                    ("abicoder", Some("v1" | "v2")) => true,
                    ("experimental", Some("ABIEncoderV2" | "SMTChecker")) => true,
                    _ => false,
                };
                if !ok {
                    self.err(item.span, "unknown pragma");
                }
            }
            PragmaTokens::Verbatim(_) => {
                self.err(item.span, "unknown pragma");
            }
        }
    }

    fn visit_function(&mut self, item: &'a Item, f: &'a Function) {
        if let (Some(c), Some(name)) = (self.contract, f.name) {
            if f.kind == FunctionKind::Function && name.name == c.name.name {
                self.dcx.emit(
                    Diag::new(Level::Error, "functions are not allowed to have the same name as the contract")
                        .span(name.span)
                        .note("if you intend this to be a constructor, use `constructor(...) { ... }` to define it"),
                );
            }
        }
        if self.contract.is_none() && f.kind == FunctionKind::Function {
            if f.body.is_none() {
                self.err(item.span, "free functions must be implemented");
            }
            if let Some((vis, _)) = f.header.visibility {
                self.dcx.emit(
                    Diag::new(Level::Error, "free functions cannot have visibility")
                        .span(item.span)
                        .help(format!("remove `{}` from the declaration", vis.as_str())),
                );
            }
        }
        if f.kind == FunctionKind::Receive {
            if !matches!(f.header.state_mutability, Some((StateMutability::Payable, _))) {
                self.dcx.emit(Diag::new(Level::Error, "receive ether function must be payable").span(item.span).help("add `payable` state mutability"));
            }
            if !f.header.params.is_empty() {
                self.err(item.span, "receive ether function cannot take parameters");
            }
            if let Some(c) = self.contract {
                if c.kind == ContractKind::Library {
                    self.err(item.span, "libraries cannot have receive ether functions");
                }
            }
        }
        for p in &f.header.params {
            self.visit_var(p);
        }
        for m in &f.header.modifiers {
            if let Some(args) = &m.args {
                for e in args.exprs() {
                    self.visit_expr(e);
                }
            }
        }
        if let Some(r) = &f.header.returns {
            for p in r {
                self.visit_var(p);
            }
        }
        if let Some(body) = &f.body {
            let old_mod = self.in_modifier;
            let old_found = self.found_placeholder;
            self.in_modifier = f.kind == FunctionKind::Modifier;
            self.found_placeholder = false;
            let old_loop = self.in_loop;
            self.in_loop = 0;
            self.visit_block(body);
            if f.kind == FunctionKind::Modifier && !self.found_placeholder {
                if let Some(n) = f.name {
                    self.err(n.span, "modifier must have a `_;` placeholder statement");
                }
            }
            self.in_loop = old_loop;
            self.in_modifier = old_mod;
            self.found_placeholder = old_found;
        }
    }

    fn visit_var(&mut self, v: &'a VarDecl) {
        self.visit_type(&v.ty);
        if let Some(init) = &v.initializer {
            self.visit_expr(init);
        }
    }

    fn visit_type(&mut self, t: &'a Type) {
        match &t.kind {
            TypeKind::Array(e, len) => {
                self.visit_type(e);
                if let Some(l) = len {
                    self.visit_expr(l);
                }
            }
            TypeKind::Mapping(m) => {
                self.visit_type(&m.key);
                self.visit_type(&m.value);
            }
            TypeKind::Function(h) => {
                for p in &h.params {
                    self.visit_var(p);
                }
                if let Some(r) = &h.returns {
                    for p in r {
                        self.visit_var(p);
                    }
                }
            }
            _ => {}
        }
    }

    fn visit_block(&mut self, b: &'a Block) {
        for s in &b.stmts {
            self.visit_stmt(s);
        }
    }

    fn visit_stmt(&mut self, s: &'a Stmt) {
        match &s.kind {
            StmtKind::Assembly(a) => {
                let mut memsafe = 0;
                for (f, sp) in &a.flags {
                    if f.as_str() == "memory-safe" {
                        memsafe += 1;
                        if memsafe > 1 {
                            self.err(*sp, "inline assembly marked memory-safe multiple times");
                        }
                    } else {
                        self.dcx.emit(Diag::new(Level::Warning, "unknown inline assembly flag").span(*sp));
                    }
                }
            }
            StmtKind::DeclSingle(v) => self.visit_var(v),
            StmtKind::DeclMulti(vs, e) => {
                for v in vs.iter().flatten() {
                    self.visit_var(v);
                }
                self.visit_expr(e);
            }
            StmtKind::Block(b) => self.visit_block(b),
            StmtKind::UncheckedBlock(b) => {
                if self.in_unchecked {
                    self.err(s.span, "`unchecked` blocks cannot be nested");
                }
                let old = self.in_unchecked;
                self.in_unchecked = true;
                self.visit_block(b);
                self.in_unchecked = old;
            }
            StmtKind::Break => {
                if self.in_loop == 0 {
                    self.err(s.span, "`break` outside of a loop");
                }
            }
            StmtKind::Continue => {
                if self.in_loop == 0 {
                    self.err(s.span, "`continue` outside of a loop");
                }
            }
            StmtKind::Placeholder => {
                if !self.in_modifier {
                    self.err(s.span, "placeholder statements can only be used in modifiers");
                } else if self.in_unchecked {
                    self.err(s.span, "placeholder statements cannot be used inside unchecked blocks");
                }
                self.found_placeholder = true;
            }
            StmtKind::DoWhile(body, cond) => {
                self.in_loop += 1;
                self.visit_stmt(body);
                self.in_loop -= 1;
                self.visit_expr(cond);
            }
            StmtKind::While(cond, body) => {
                self.visit_expr(cond);
                self.in_loop += 1;
                self.visit_stmt(body);
                self.in_loop -= 1;
            }
            StmtKind::For(init, cond, next, body) => {
                if let Some(i) = init {
                    self.visit_stmt(i);
                }
                if let Some(c) = cond {
                    self.visit_expr(c);
                }
                if let Some(n) = next {
                    self.visit_expr(n);
                }
                self.in_loop += 1;
                self.visit_stmt(body);
                self.in_loop -= 1;
            }
            StmtKind::Emit(_, args) | StmtKind::Revert(_, args) => {
                for e in args.exprs() {
                    self.visit_expr(e);
                }
            }
            StmtKind::Expr(e) => self.visit_expr(e),
            StmtKind::If(c, t, e) => {
                self.visit_expr(c);
                self.visit_stmt(t);
                if let Some(e) = e {
                    self.visit_stmt(e);
                }
            }
            StmtKind::Return(e) => {
                if let Some(e) = e {
                    self.visit_expr(e);
                }
            }
            StmtKind::Try(t) => {
                self.visit_expr(&t.expr);
                for v in &t.returns {
                    self.visit_var(v);
                }
                self.visit_block(&t.block);
                for c in &t.catch {
                    for v in &c.args {
                        self.visit_var(v);
                    }
                    self.visit_block(&c.block);
                }
            }
        }
    }

    fn visit_expr(&mut self, e: &'a Expr) {
        use ExprKind::*;
        match &e.kind {
            Array(v) => {
                for x in v {
                    self.visit_expr(x);
                }
            }
            Assign(l, _, r) | Binary(l, _, r) => {
                self.visit_expr(l);
                self.visit_expr(r);
            }
            Call(c, args) => {
                self.visit_expr(c);
                for a in args.exprs() {
                    self.visit_expr(a);
                }
            }
            CallOptions(c, opts) => {
                self.visit_expr(c);
                for o in opts {
                    self.visit_expr(&o.value);
                }
            }
            Delete(x) | Unary(_, x) => self.visit_expr(x),
            Index(b, k) => {
                self.visit_expr(b);
                match k {
                    IndexKind::Index(Some(i)) => self.visit_expr(i),
                    IndexKind::Index(None) => {}
                    IndexKind::Range(s, t) => {
                        if let Some(s) = s {
                            self.visit_expr(s);
                        }
                        if let Some(t) = t {
                            self.visit_expr(t);
                        }
                    }
                }
            }
            Lit(lit, sub) => self.check_lit(e, lit, sub),
            Member(b, _) => self.visit_expr(b),
            New(t) | TypeCall(t) | Type(t) => self.visit_type(t),
            Payable(args) => {
                for a in args.exprs() {
                    self.visit_expr(a);
                }
            }
            Ternary(a, b, c) => {
                self.visit_expr(a);
                self.visit_expr(b);
                self.visit_expr(c);
            }
            Tuple(v) => {
                for x in v.iter().flatten() {
                    self.visit_expr(x);
                }
            }
            Ident(_) => {}
        }
    }

    fn check_lit(&self, e: &Expr, lit: &Lit, sub: &Option<(SubDenom, Span)>) {
        let s = lit.symbol.as_str();
        let is_num = matches!(lit.kind, LitValue::Number(_) | LitValue::Rational(_) | LitValue::Address(_)) || (matches!(lit.kind, LitValue::Err) && s.starts_with(|c: char| c.is_ascii_digit() || c == '.'));
        if !is_num {
            return;
        }
        // underscores
        if s.contains('_') {
            let help = if s.ends_with('_') {
                Some("remove trailing underscores")
            } else if s.contains("__") {
                Some("only 1 consecutive underscore `_` is allowed between digits")
            } else if s.contains("_.") || s.contains("._") {
                Some("remove underscores in front of the fraction part")
            } else if !s.starts_with("0x") && (s.contains("_e") || s.contains("_E")) {
                Some("remove underscores at the end of the mantissa")
            } else if !s.starts_with("0x") && (s.contains("e_") || s.contains("E_")) {
                Some("remove underscores in front of the exponent")
            } else {
                None
            };
            if let Some(h) = help {
                self.dcx.emit(Diag::new(Level::Error, "invalid use of underscores in number literal").span(lit.span).help(h));
                return;
            }
        }
        let max = BigUint::one().shl(256);
        match &lit.kind {
            LitValue::Number(n) => {
                let is_rational_syntax = !s.starts_with("0x") && (s.contains('.') || s.contains('e') || s.contains('E'));
                if n.mag >= max {
                    let msg = if is_rational_syntax { "rational part too large" } else { "integer part too large" };
                    self.err(lit.span, msg);
                    return;
                }
            }
            LitValue::Rational(r) => {
                if r.num.mag.bits() > 256 || r.den.bits() > 256 {
                    self.err(lit.span, "rational part too large");
                    return;
                }
            }
            LitValue::Address(_) => {}
            _ => {}
        }
        if s.starts_with("0x") {
            if sub.is_some() {
                self.dcx.emit(
                    Diag::new(Level::Error, "hexadecimal numbers cannot be used with unit denominations")
                        .span(e.span)
                        .help("you can use an expression of the form \"0x1234 * 1 days\" instead"),
                );
                return;
            }
            if let LitValue::Address(_) = lit.kind {
                let hex = &s[2..];
                let cs = checksum(hex);
                if cs != hex {
                    self.dcx.emit(
                        Diag::new(Level::Error, "invalid checksummed address")
                            .span(lit.span)
                            .help(format!("correct checksummed address: \"0x{}\"", cs))
                            .note("if this is not used as an address, please prepend \"00\""),
                    );
                }
            }
        }
    }
}

fn layout_span(c: &Contract) -> Span {
    // `layout at <expr>`: approximate from the expression span; the keyword precedes by "layout at ".
    match &c.layout {
        Some(e) => Span::new(e.span.lo.saturating_sub(10), e.span.hi),
        None => c.name.span,
    }
}

pub fn checksum(hex: &str) -> String {
    let lower = hex.to_ascii_lowercase();
    let h = crate::keccak::keccak256(lower.as_bytes());
    let mut out = String::new();
    for (i, c) in lower.chars().enumerate() {
        let nibble = (h[i / 2] >> (if i % 2 == 0 { 4 } else { 0 })) & 0xf;
        if c.is_ascii_alphabetic() && nibble >= 8 {
            out.push(c.to_ascii_uppercase());
        } else {
            out.push(c);
        }
    }
    out
}

