use super::hir::*;
use super::lower::Lowerer;
use crate::ast;
use crate::diag::{Diag, Level};
use crate::source_map::Span;
use crate::token::ElemTy;

fn is_ref(t: &Ty) -> bool {
    matches!(t, Ty::Array(..) | Ty::Struct(_) | Ty::Mapping(..) | Ty::Elem(ElemTy::String) | Ty::Elem(ElemTy::Bytes))
}

fn list(locs: &[&str]) -> String {
    let q: Vec<String> = locs.iter().map(|l| format!("`{}`", l)).collect();
    match q.len() {
        1 => q[0].clone(),
        2 => format!("{} or {}", q[0], q[1]),
        _ => format!("{}, or {}", q[..q.len() - 1].join(", "), q[q.len() - 1]),
    }
}

impl<'a> Lowerer<'a> {
    pub fn check_var_locations(&mut self) {
        let nf = self.hir.functions.len();
        let is_pub = |h: &Hir, f: Id| {
            let fh = &h.functions[f];
            fh.kind == ast::FunctionKind::Function && matches!(fh.visibility, ast::Visibility::Public | ast::Visibility::External)
        };
        for f in 0..nf {
            if is_pub(&self.hir, f) {
                self.check_fn_vars(f);
            }
        }
        for f in 0..nf {
            if !is_pub(&self.hir, f) {
                self.check_fn_vars(f);
            }
        }
        for v in 0..self.hir.vars.len() {
            if self.hir.vars[v].kind == VarKind::State {
                self.check_state_var(v);
            }
        }
        for v in 0..self.hir.vars.len() {
            if self.hir.vars[v].kind == VarKind::Local {
                self.check_loc(v, &["memory", "storage", "calldata"], "variable".to_string());
            }
        }
    }

    fn check_fn_vars(&mut self, f: Id) {
        let fh = &self.hir.functions[f];
        let in_library = fh.contract.map_or(false, |c| self.hir.contracts[c].kind == ast::ContractKind::Library);
        let (locs, ctx): (&[&str], String) = match fh.kind {
            ast::FunctionKind::Constructor => (&["memory", "storage"], "function".to_string()),
            ast::FunctionKind::Modifier => (&["memory", "storage", "calldata"], "internal function".to_string()),
            ast::FunctionKind::Fallback | ast::FunctionKind::Receive => return,
            ast::FunctionKind::Function => {
                let vis = fh.visibility;
                if fh.contract.is_none() {
                    (&["memory", "storage", "calldata"], "internal function".to_string())
                } else if matches!(vis, ast::Visibility::Public | ast::Visibility::External) && !in_library {
                    (&["memory", "calldata"], format!("{} function", vis.as_str()))
                } else {
                    (&["memory", "storage", "calldata"], format!("{} function", vis.as_str()))
                }
            }
        };
        let public = fh.kind == ast::FunctionKind::Function && matches!(fh.visibility, ast::Visibility::Public | ast::Visibility::External) && !in_library && fh.contract.is_some();
        let params = fh.params.clone();
        let returns = fh.returns.clone();
        for p in params {
            self.check_loc(p, locs, format!("{ctx} parameter"));
            if public {
                self.check_public_mapping(p);
            }
        }
        for p in returns {
            self.check_loc(p, locs, format!("{ctx} return parameter"));
            if public {
                self.check_public_mapping(p);
            }
        }
    }

    fn check_public_mapping(&mut self, v: Id) {
        let var = &self.hir.vars[v];
        if self.hir.contains_mapping(&var.ty) {
            let sp = var.ast.ty.span;
            self.err(sp, "types containing mappings cannot be parameter or return types of public functions");
        }
    }

    fn check_loc(&mut self, v: Id, allowed: &[&str], ctx: String) {
        let var = &self.hir.vars[v];
        if var.ty == Ty::Err {
            return;
        }
        let loc = var.ast.data_location.map(|l| l.0.as_str());
        let sp = var.ast.span;
        if !is_ref(&var.ty) {
            if loc.is_some() && loc != Some("transient") {
                self.err(sp, "data location can only be specified for array, struct or mapping types");
            }
            return;
        }
        match loc {
            None => {
                self.dcx.emit(Diag::new(Level::Error, "expected data location").span(sp).note(format!("data location must be {} for {}", list(allowed), ctx)));
            }
            Some(l) if !allowed.contains(&l) => {
                self.dcx.emit(
                    Diag::new(Level::Error, format!("invalid data location `{l}`"))
                        .span(sp)
                        .note(format!("data location must be {} for {}, but got `{l}`", list(allowed), ctx)),
                );
            }
            _ => {}
        }
    }

    fn check_state_var(&mut self, v: Id) {
        let var = &self.hir.vars[v];
        let ast = var.ast;
        let loc = ast.data_location.map(|l| l.0.as_str());
        let end = ast.initializer.as_ref().map(|e| e.span.hi).or(ast.name.map(|n| n.span.hi)).unwrap_or(ast.span.hi);
        let tsp = Span::new(ast.ty.span.lo, end);
        if loc == Some("transient") {
            if var.is_constant || var.is_immutable {
                self.err(tsp, "transient cannot be used as data location for constant or immutable variables");
            }
            if ast.initializer.is_some() {
                self.err(tsp, "initialization of transient storage state variables is not supported");
            }
            return;
        }
        if var.ty == Ty::Err {
            return;
        }
        let sp = ast.span;
        if let Some(l) = loc {
            if !is_ref(&var.ty) {
                self.err(sp, "data location can only be specified for array, struct or mapping types");
            } else {
                self.dcx.emit(
                    Diag::new(Level::Error, format!("invalid data location `{l}`"))
                        .span(sp)
                        .note(format!("data location must be `none` or `transient` for state variable, but got `{l}`")),
                );
            }
        }
    }
}
