    fn check_contract(&self, cid: Id) {
        let c = &self.hir.contracts[cid];
        let fns: Vec<Id> = c.items.iter().filter_map(|i| if let ItemId::Function(f) = i { Some(*f) } else { None }).collect();
        for &f in &fns {
            let fh = &self.hir.functions[f];
            if fh.ast.header.virtual_.is_some() && fh.visibility == ast::Visibility::Private {
                self.dcx.emit(err_code("3942", "`virtual` and `private` cannot be used together").span(fh.item.span));
            }
            if fh.ast.body.is_none() && !fh.is_virtual && c.kind != ast::ContractKind::Interface && matches!(fh.kind, ast::FunctionKind::Function | ast::FunctionKind::Modifier) {
                self.dcx.emit(err_code("5424", "functions without implementation must be marked virtual").span(fh.item.span));
            }
        }
        self.check_declared_twice(&fns);
        // override checks
        for &f in &fns {
            self.check_override(cid, f);
        }
        for &it in &c.items {
            if let ItemId::Var(v) = it {
                self.check_var_override(cid, v);
            }
        }
        self.check_multiple_bases(cid);
        if c.kind == ast::ContractKind::Contract {
            self.check_unimplemented(cid);
        }
    }

    /// Base functions (most derived per chain) overridden by `f` in contract `cid`.
    fn overridden(&self, cid: Id, f: Id) -> Vec<(Id, Id)> {
        let lin = &self.hir.contracts[cid].linearized;
        let mut found: Vec<(Id, Id)> = vec![];
        for &b in lin.iter().skip(1) {
            for &it in &self.hir.contracts[b].items {
                if let ItemId::Function(g) = it {
                    let gh = &self.hir.functions[g];
                    if !matches!(gh.kind, ast::FunctionKind::Function | ast::FunctionKind::Modifier) {
                        continue;
                    }
                    if self.same_sig(f, g) {
                        found.push((b, g));
                    }
                }
            }
        }
        // keep only the most derived: drop g in base B if another found function's contract derives from B
        let keep: Vec<(Id, Id)> = found
            .iter()
            .filter(|(b, _)| !found.iter().any(|(b2, _)| b2 != b && self.hir.contracts[*b2].linearized.contains(b)))
            .copied()
            .collect();
        keep
    }

    fn check_override(&self, cid: Id, f: Id) {
        let fh = &self.hir.functions[f];
        if !matches!(fh.kind, ast::FunctionKind::Function | ast::FunctionKind::Modifier) {
            return;
        }
        let bases = self.overridden(cid, f);
        let what = if fh.kind == ast::FunctionKind::Modifier { "modifier" } else { "function" };
        if bases.is_empty() {
            if fh.overrides {
                self.dcx.emit(err_code("7792", format!("{} has override specified but does not override anything", cap(what))).span(fh.item.span));
            }
            return;
        }
        if !fh.overrides {
            let (_, g) = bases[0];
            self.dcx.emit(
                err_code("9456", format!("overriding {what} is missing `override` specifier"))
                    .span(fh.item.span)
                    .span_note(self.item_span(g), format!("overridden {what} is here"))
                    .help("add `override` to the function signature"),
            );
        } else if bases.len() > 1 && fh.ast.header.override_.as_ref().map_or(true, |o| o.paths.is_empty()) {
            let names: Vec<String> = bases.iter().map(|(b, _)| format!("`{}`", self.hir.contracts[*b].name)).collect();
            let list = if names.len() == 2 { format!("{} and {}", names[0], names[1]) } else { format!("{} and {}", names[..names.len() - 1].join(", "), names[names.len() - 1]) };
            self.dcx.emit(err_code("4327", format!("{} needs to specify overridden contracts {}", cap(what), list)).span(fh.item.span));
        }
        for &(_, g) in &bases {
            let gh = &self.hir.functions[g];
            if !gh.is_virtual {
                self.dcx.emit(
                    err_code("4334", format!("cannot override non-virtual {what}"))
                        .span(self.item_span(g))
                        .span_note(fh.item.span, format!("overriding {what} is here"))
                        .help("add `virtual` to the base function to allow overriding"),
                );
            }
            if fh.kind == ast::FunctionKind::Modifier {
                continue;
            }
            if fh.visibility != gh.visibility && !(gh.visibility == ast::Visibility::External && fh.visibility == ast::Visibility::Public) {
                self.dcx.emit(
                    err_code("9098", format!("overriding function changes visibility from `{}` to `{}`", gh.visibility.as_str(), fh.visibility.as_str()))
                        .span(fh.item.span)
                        .span_note(self.item_span(g), "overridden function is here"),
                );
            }
            if !mutability_ok(gh.mutability, fh.mutability) {
                self.dcx.emit(
                    err_code("6959", format!("overriding function changes state mutability from `{}` to `{}`", gh.mutability.as_str(), fh.mutability.as_str()))
                        .span(fh.item.span),
                );
            }
            if self.ret_tys(f) != self.ret_tys(g) {
                self.dcx.emit(err_code("4822", "overriding function has different return types").span(fh.item.span).span_note(self.item_span(g), "overridden function is here"));
            }
        }
    }

    fn check_var_override(&self, cid: Id, v: Id) {
        let vh = &self.hir.vars[v];
        if vh.visibility != ast::Visibility::Public || vh.ast.override_.is_none() {
            return;
        }
        let (ins, outs) = self.hir.getter_types(v);
        let lin = &self.hir.contracts[cid].linearized;
        for &b in lin.iter().skip(1) {
            for &it in &self.hir.contracts[b].items {
                if let ItemId::Function(g) = it {
                    let gh = &self.hir.functions[g];
                    if gh.name != vh.name || self.param_tys(g) != ins {
                        continue;
                    }
                    let outs_t: Vec<Ty> = outs.iter().map(|(_, t)| t.clone()).collect();
                    if self.ret_tys(g) != outs_t {
                        self.dcx.emit(
                            err_code("4822", "overriding public state variable has different return types").span(vh.ast.span).span_note(gh.item.span, "overridden function is here"),
                        );
                    }
                    return;
                }
            }
        }
    }

    fn check_multiple_bases(&self, cid: Id) {
        let c = &self.hir.contracts[cid];
        let lin = &c.linearized;
        let mut done: Vec<Id> = vec![];
        for &b in lin.iter().skip(1) {
            for &it in &self.hir.contracts[b].items {
                let ItemId::Function(g) = it else { continue };
                let gh = &self.hir.functions[g];
                if gh.kind != ast::FunctionKind::Function {
                    continue;
                }
                if done.iter().any(|&d| self.same_sig(d, g)) {
                    continue;
                }
                // declared in cid?
                let declared = c.items.iter().any(|&i| matches!(i, ItemId::Function(f) if self.same_sig(f, g)));
                if declared {
                    done.push(g);
                    continue;
                }
                // find most-derived definitions across bases
                let mut defs: Vec<(Id, Id)> = vec![];
                for &b2 in lin.iter().skip(1) {
                    for &it2 in &self.hir.contracts[b2].items {
                        if let ItemId::Function(g2) = it2 {
                            if self.same_sig(g, g2) {
                                defs.push((b2, g2));
                            }
                        }
                    }
                }
                let keep: Vec<(Id, Id)> = defs
                    .iter()
                    .filter(|(bb, _)| !defs.iter().any(|(b2, _)| b2 != bb && self.hir.contracts[*b2].linearized.contains(bb)))
                    .copied()
                    .collect();
                done.push(g);
                if keep.len() > 1 {
                    let mut names: Vec<String> = keep.iter().map(|(bb, _)| format!("`{}`", self.hir.contracts[*bb].name)).collect();
                    names.reverse();
                    self.dcx.emit(
                        err_code("6480", format!("derived contract must override function `{}`", gh.name.unwrap()))
                            .span(c.name_span)
                            .note("two or more base classes define function with same name and parameter types")
                            .note(format!("defined in: {}", names.join(", "))),
                    );
                }
            }
        }
    }

    fn check_unimplemented(&self, cid: Id) {
        let c = &self.hir.contracts[cid];
        let lin = &c.linearized;
        let mut seen: Vec<Id> = vec![];
        let mut unimpl: Vec<Id> = vec![];
        for &b in lin.iter() {
            for &it in &self.hir.contracts[b].items {
                let ItemId::Function(g) = it else { continue };
                let gh = &self.hir.functions[g];
                if !matches!(gh.kind, ast::FunctionKind::Function | ast::FunctionKind::Modifier) {
                    continue;
                }
                if seen.iter().any(|&s| self.same_sig(s, g)) {
                    continue;
                }
                seen.push(g);
                if gh.ast.body.is_none() {
                    unimpl.push(g);
                }
            }
        }
        // report in declaration order of the base-most contracts first
        let mut ordered = unimpl.clone();
        ordered.sort_by_key(|&g| g);
        for g in ordered {
            let gh = &self.hir.functions[g];
            let what = if gh.kind == ast::FunctionKind::Modifier { "modifier" } else { "function" };
            let def_in = self.hir.contracts[gh.contract.unwrap()].name;
            let kw_span = Span::new(c.item.span.lo, c.item.span.lo + 8);
            self.dcx.emit(
                err_code("3656", format!("contract `{}` has unimplemented functions", c.name))
                    .span(c.name_span)
                    .span_label(kw_span, "help: mark the contract as abstract: `abstract contract`")
                    .span_note(gh.item.span, format!("unimplemented {what} `{}` defined in `{}`", gh.name.unwrap(), def_in)),
            );
        }
    }
}

fn cap(s: &str) -> String {
    let mut c = s.chars();
    match c.next() {
        Some(f) => f.to_uppercase().collect::<String>() + c.as_str(),
        None => String::new(),
    }
}

fn mutability_ok(base: ast::StateMutability, over: ast::StateMutability) -> bool {
    use ast::StateMutability::*;
    if base == over {
        return true;
    }
    match base {
        Payable => false,
        NonPayable => matches!(over, View | Pure),
        View => over == Pure,
        Pure => false,
    }
}
