// SPDX-License-Identifier: UNLICENSED
pragma solidity >=0.8.4;
import {Vault as V} from "./oz.sol";
import "./oz.sol" as OZ;

type Amount is uint256;
using {plus as +, lt as <} for Amount global;
function plus(Amount a, Amount b) pure returns (Amount) { return Amount.wrap(Amount.unwrap(a) + Amount.unwrap(b)); }
function lt(Amount a, Amount b) pure returns (bool) { return Amount.unwrap(a) < Amount.unwrap(b); }

interface IFactory {
    event Created(address indexed instance, bytes32 salt);
    function create(bytes32 salt) external returns (address);
}

contract Factory is IFactory {
    address[] public instances;
    mapping(bytes32 => address) public bySalt;
    function create(bytes32 salt) external override returns (address) {
        V v = new V{salt: salt}(salt);
        instances.push(address(v));
        bySalt[salt] = address(v);
        emit Created(address(v), salt);
        return address(v);
    }
    function count() external view returns (uint) { return instances.length; }
    function sum(Amount[] calldata xs) external pure returns (Amount total) {
        for (uint i = 0; i < xs.length; ++i) { total = total + xs[i]; }
    }
    function cmp(Amount a, Amount b) external pure returns (bool) { return a < b; }
    function sel() external pure returns (bytes4, bytes4) { return (this.create.selector, IFactory.create.selector); }
    function multi() external pure returns (uint a, uint b, uint c) { (a, b, c) = (1, 2, 3); (, b, ) = (4, 5, 6); }
    function fn(function(uint) external pure returns (uint) f, uint x) external pure returns (uint) { return f(x); }
    function tryCall(address t) external returns (bool) {
        try OZ.Vault(payable(t)).withdraw(1) { return true; } catch Error(string memory) { return false; } catch Panic(uint) { return false; } catch { return false; }
    }
}

contract Ballot {
    struct Voter { uint weight; bool voted; address delegate; uint vote; }
    struct Proposal { bytes32 name; uint voteCount; }
    address public chairperson;
    mapping(address => Voter) public voters;
    Proposal[] public proposals;
    constructor(bytes32[] memory proposalNames) {
        chairperson = msg.sender;
        voters[chairperson].weight = 1;
        for (uint i = 0; i < proposalNames.length; i++) {
            proposals.push(Proposal({name: proposalNames[i], voteCount: 0}));
        }
    }
    function giveRightToVote(address voter) external {
        require(msg.sender == chairperson, "Only chairperson can give right to vote.");
        require(!voters[voter].voted, "The voter already voted.");
        require(voters[voter].weight == 0);
        voters[voter].weight = 1;
    }
    function delegate(address to) external {
        Voter storage sender = voters[msg.sender];
        require(sender.weight != 0, "You have no right to vote");
        while (voters[to].delegate != address(0)) {
            to = voters[to].delegate;
            require(to != msg.sender, "Found loop in delegation.");
        }
        Voter storage delegate_ = voters[to];
        require(delegate_.weight >= 1);
        sender.voted = true;
        sender.delegate = to;
        if (delegate_.voted) { proposals[delegate_.vote].voteCount += sender.weight; } else { delegate_.weight += sender.weight; }
    }
    function winningProposal() public view returns (uint winningProposal_) {
        uint winningVoteCount = 0;
        for (uint p = 0; p < proposals.length; p++) {
            if (proposals[p].voteCount > winningVoteCount) { winningVoteCount = proposals[p].voteCount; winningProposal_ = p; }
        }
    }
    function winnerName() external view returns (bytes32 winnerName_) { winnerName_ = proposals[winningProposal()].name; }
}
