// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

abstract contract Context {
    function _msgSender() internal view virtual returns (address) { return msg.sender; }
    function _msgData() internal view virtual returns (bytes calldata) { return msg.data; }
}

abstract contract Ownable is Context {
    address private _owner;
    error OwnableUnauthorizedAccount(address account);
    error OwnableInvalidOwner(address owner);
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);
    constructor(address initialOwner) {
        if (initialOwner == address(0)) { revert OwnableInvalidOwner(address(0)); }
        _transferOwnership(initialOwner);
    }
    modifier onlyOwner() { _checkOwner(); _; }
    function owner() public view virtual returns (address) { return _owner; }
    function _checkOwner() internal view virtual {
        if (owner() != _msgSender()) { revert OwnableUnauthorizedAccount(_msgSender()); }
    }
    function renounceOwnership() public virtual onlyOwner { _transferOwnership(address(0)); }
    function transferOwnership(address newOwner) public virtual onlyOwner {
        if (newOwner == address(0)) { revert OwnableInvalidOwner(address(0)); }
        _transferOwnership(newOwner);
    }
    function _transferOwnership(address newOwner) internal virtual {
        address oldOwner = _owner;
        _owner = newOwner;
        emit OwnershipTransferred(oldOwner, newOwner);
    }
}

interface IERC165 { function supportsInterface(bytes4 interfaceId) external view returns (bool); }
abstract contract ERC165 is IERC165 {
    function supportsInterface(bytes4 interfaceId) public view virtual returns (bool) {
        return interfaceId == type(IERC165).interfaceId;
    }
}

library SafeMath {
    function tryAdd(uint256 a, uint256 b) internal pure returns (bool, uint256) {
        unchecked { uint256 c = a + b; if (c < a) return (false, 0); return (true, c); }
    }
    function add(uint256 a, uint256 b) internal pure returns (uint256) { return a + b; }
}

library Strings {
    bytes16 private constant HEX_DIGITS = "0123456789abcdef";
    function toString(uint256 value) internal pure returns (string memory) {
        unchecked {
            uint256 length = 1;
            uint256 tmp = value;
            while (tmp >= 10) { tmp /= 10; length++; }
            string memory buffer = new string(length);
            uint256 ptr;
            assembly ("memory-safe") { ptr := add(add(buffer, 0x20), length) }
            while (true) {
                ptr--;
                assembly ("memory-safe") { mstore8(ptr, byte(mod(value, 10), HEX_DIGITS)) }
                value /= 10;
                if (value == 0) break;
            }
            return buffer;
        }
    }
}

contract Vault is Ownable, ERC165 {
    using SafeMath for uint256;
    using Strings for uint256;
    struct Deposit { uint256 amount; uint64 time; address who; }
    enum State { Open, Closed }
    State public state;
    mapping(address => Deposit[]) public deposits;
    mapping(address => uint256) private _balances;
    uint256 public totalDeposited;
    uint256 public constant MAX = 1e24;
    bytes32 public immutable SALT;
    event Deposited(address indexed who, uint256 amount, uint64 time);
    event Withdrawn(address indexed who, uint256 amount);
    error InsufficientFunds(uint256 have, uint256 want);
    error Closed();

    constructor(bytes32 salt) Ownable(msg.sender) payable { SALT = salt; }

    modifier whenOpen() { if (state != State.Open) revert Closed(); _; }

    function deposit() external payable whenOpen {
        _balances[msg.sender] = _balances[msg.sender].add(msg.value);
        deposits[msg.sender].push(Deposit({amount: msg.value, time: uint64(block.timestamp), who: msg.sender}));
        totalDeposited += msg.value;
        emit Deposited(msg.sender, msg.value, uint64(block.timestamp));
    }

    function withdraw(uint256 amount) external {
        uint256 bal = _balances[msg.sender];
        if (bal < amount) revert InsufficientFunds({have: bal, want: amount});
        _balances[msg.sender] = bal - amount;
        (bool ok, ) = payable(msg.sender).call{value: amount}("");
        require(ok, "transfer failed");
        emit Withdrawn(msg.sender, amount);
    }

    function close() external onlyOwner { state = State.Closed; }

    function balanceOf(address who) external view returns (uint256) { return _balances[who]; }

    function describe(uint256 v) external pure returns (string memory) { return string.concat("v=", v.toString()); }

    function supportsInterface(bytes4 interfaceId) public view virtual override returns (bool) {
        return interfaceId == type(Vault).interfaceId || super.supportsInterface(interfaceId);
    }

    function hash(bytes calldata data) external pure returns (bytes32, bytes4) {
        return (keccak256(data), bytes4(data[:4]));
    }

    receive() external payable { totalDeposited += msg.value; }
}
