// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

library Set {
    struct Data { mapping(uint => bool) flags; uint[] items; }
    error AlreadyPresent(uint value);
    event Inserted(uint indexed value) anonymous;
    function insert(Data storage self, uint value) public returns (bool) {
        if (self.flags[value]) revert AlreadyPresent({value: value});
        self.flags[value] = true;
        self.items.push(value);
        emit Inserted(value);
        return true;
    }
    function contains(Data storage self, uint value) public view returns (bool) { return self.flags[value]; }
    function size(Data storage self) external view returns (uint) { return self.items.length; }
}

uint constant LIMIT = 10;
function clamp(uint x) pure returns (uint) { return x > LIMIT ? LIMIT : x; }

abstract contract Base {
    uint internal counter;
    constructor(uint start) { counter = start; }
    modifier bounded(uint x) { require(x <= LIMIT, "too big"); _; }
    function bump(uint by) public virtual bounded(by) { counter += by; }
    function name() public pure virtual returns (string memory);
}

interface INamed { function name() external pure returns (string memory); }

contract Registry is Base(1), INamed {
    using Set for Set.Data;
    Set.Data private data;
    address payable public treasury;
    bytes32[] public tags;

    constructor(address payable t) { treasury = t; }

    function bump(uint by) public override bounded(by) {
        super.bump(clamp(by));
        data.insert(counter);
    }

    function name() public pure override(Base, INamed) returns (string memory) { return "registry"; }

    function has(uint v) external view returns (bool) { return data.contains(v); }

    function tagAll(bytes32[] calldata ts) external {
        for (uint i; i < ts.length; ++i) tags.push(ts[i]);
        delete tags[0];
    }

    function pay() external payable {
        (bool ok, bytes memory ret) = treasury.call{value: msg.value, gas: 2300}(abi.encodeWithSignature("ping()"));
        if (!ok) { assembly { revert(add(ret, 32), mload(ret)) } }
    }

    function sig() external pure returns (bytes4, bytes32) {
        return (bytes4(keccak256("x()")), keccak256(abi.encode(uint8(1), true, "s")));
    }
}
