// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

library StorageSlot {
    struct AddressSlot { address value; }
    function getAddressSlot(bytes32 slot) internal pure returns (AddressSlot storage r) {
        assembly { r.slot := slot }
    }
}

abstract contract Proxy {
    function _delegate(address implementation) internal virtual {
        assembly {
            calldatacopy(0, 0, calldatasize())
            let result := delegatecall(gas(), implementation, 0, calldatasize(), 0, 0)
            returndatacopy(0, 0, returndatasize())
            switch result
            case 0 { revert(0, returndatasize()) }
            default { return(0, returndatasize()) }
        }
    }
    function _implementation() internal view virtual returns (address);
    function _fallback() internal virtual { _delegate(_implementation()); }
    fallback() external payable virtual { _fallback(); }
}

contract ERC1967Proxy is Proxy {
    bytes32 internal constant IMPLEMENTATION_SLOT = 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;
    event Upgraded(address indexed implementation);
    error ERC1967InvalidImplementation(address implementation);
    constructor(address implementation, bytes memory _data) payable {
        if (implementation.code.length == 0) revert ERC1967InvalidImplementation(implementation);
        StorageSlot.getAddressSlot(IMPLEMENTATION_SLOT).value = implementation;
        emit Upgraded(implementation);
        if (_data.length > 0) {
            (bool ok, ) = implementation.delegatecall(_data);
            require(ok);
        }
    }
    function _implementation() internal view virtual override returns (address) {
        return StorageSlot.getAddressSlot(IMPLEMENTATION_SLOT).value;
    }
}
